/* DAWAH X — ahmad, অধ্যায় 104 · খণ্ড 104 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][104]=[[20601,20601,"","ঈশ্বর এমন কাউকে দিয়েছেন, যার মাধ্যমে তিনি পার হতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏وَقَالَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِخَرْصِهَا ‏","","",""],[20602,20602,"","আমরা ২ মাস ধরে তার বাবার বাবার বাবার মত ফুল নিয়ে কথা বলেছি, প্রভু তার জন্য এসেছেন আর আমরা তাকে বলেছিলাম সে কি করতে। ঈশ্বর দোয়া করবেন যেন সে আমার লোকটাকে জঙ্গলে পৌঁছে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الثَّمَرِ بِالتَّمْرِ فَأَخْبَرَهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الْعَرَايَا ‏","","",""],[20603,20603,"","আমরা একটা ভাঙা দুর্ঘটনার কথা বলেছিলাম, যেখানে আমরা লোকেদের আবহাওয়ার সঙ্গে ধরা পড়ে যাওয়া লোকেদের সঙ্গে কথা বলেছিলাম । - এর যোগ্য।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْنَا إِلَى الْمَسْجِدِ فَأُقِيمَتْ الصَّلَاةُ قُلْتُ كَمْ كَانَ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ ‏ ‏آيَةً ‏","","",""],[20604,20604,"","আমরা দুই বছর ধরে একটা ছেলের পরিকল্পনা নিয়ে কথা বলেছি যে তার জন্য প্রার্থনা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الْعُمْرَى ‏ ‏لِلْوَارِثِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً قَضَى ‏ ‏بِالْعُمْرَى ‏","","",""],[20605,20605,"","আমরা একটা হাত ধরে বেঁচে থাকার কথা বলেছিলাম যেটা আমাকে বলেছে যে ঈশ্বর আমাকে এটা করতে বলবেন। আর তুমি ভালো অনুভব করবে, সে আমাকে বই শিখাচ্ছে না।","‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُحْسِنُ ‏ ‏السُّرْيَانِيَّةَ ‏ ‏إِنَّهَا تَأْتِينِي كُتُبٌ قَالَ قُلْتُ لَا قَالَ فَتَعَلَّمْهَا فَتَعَلَّمْتُهَا فِي سَبْعَةَ عَشَرَ يَوْمًا ‏","","",""],[20606,20606,"","আমি ক্ষমা চেয়ে আমার বাবাকে বাঁচাতে চেষ্টা করেছি। তারা বলেছে, খোদা এটা করেছে, তিনি একটা টাকাও শুনতে পাবেন না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِرَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَا وَاللَّهِ أَعْلَمُ بِالْحَدِيثِ مِنْهُ إِنَّمَا ‏ ‏أَتَى رَجُلَانِ قَدْ اقْتَتَلَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ هَذَا شَأْنَكُمْ فَلَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ قَالَ فَسَمِعَ ‏ ‏رَافِعٌ ‏ ‏قَوْلَهُ لَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏","","",""],[20607,20607,"","আমরা দুই বছর ধরে ব্যবসা করেছি, আবার অনেক মজা করেছি। আমি তাকে রক্ষা করেছিলাম যদি তুমি ভুল হয়ে থাকো তাহলে সে ভালো কিছু করবে। ভাগ্য জানে যে তোমার হৃদয় পিপাসার্ত না হয়ে মারা গেছে। আমি তাকে হত্যা করেছি। আমার মত তুমি আর আমি তোমার মতো করে বলতে পেরে খুশি হব, সে আমাকে ঈশ্বরের কাছে প্রার্থনা করতে বলেছিল, সে ঈশ্বরের কাছে প্রার্থনা করেছিল আর সে এভাবে তাকে উদ্ধার করেছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سِنَانٍ سَعِيدُ بْنُ سِنَانٍ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقُلْتُ يَا ‏ ‏أَبَا الْمُنْذِرِ ‏ ‏إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ فَحَدِّثْنِي بِشَيْءٍ لَعَلَّهُ يَذْهَبُ مِنْ قَلْبِي قَالَ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ أَنْفَقْتَ جَبَلَ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا فِي ‏ ‏سَبِيلِ اللَّهِ عَزَّ وَجَلَّ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَلَوْ مِتَّ عَلَى غَيْرِ ذَلِكَ لَدَخَلْتَ النَّارَ ‏ ‏قَالَ ‏ ‏فَأَتَيْتُ ‏ ‏حُذَيْفَةَ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ ‏ ‏وَأَتَيْتُ ‏ ‏ابْنَ مَسْعُودٍ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ ‏ ‏وَأَتَيْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَحَدَّثَنِي ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[20608,20608,"","আমরা আমাদের করা সমস্ত সমস্যার জন্য আমাদের সাহায্য করার চেষ্টা করেছি, দয়া করে এমন একটা ছেলে যে কিনা শোকের মাধ্যমে একটি ছেলেকে হারিয়েছে। এক ঘণ্টা বলে যে আমি কখনোই করতে পারবো না, ঈশ্বর তাকে বললেন আমরা ঈশ্বরকে দুর্বল করে দেই... ...সে বলছে যে, সে এটা তার উত্তরাধিকারীর জন্য করেনি, একজন স্বপ্নবী কখনো কাজ করতে পারে না। শেষ পর্যন্ত ঈশ্বর তা করেছেন এবং আমি তার কাছে শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত আমি শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত শেষ পর্যন্ত আমি শেষ হয়ে গিয়েছি । যে ব ্ যক ্ তি উপুড় হয়ে পড়েছে , সেই সফলকাম হয় । যে ব্যক্তি অধিকারপ্রাপ্ত, সেই ব্যক্তি যার অধিকার আছে, তাকেই অধিকার প্রদান করার অধিকার রয়েছে । ঋণের কথা কখনো খেয়াল করিনি।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سُلَيْمَانَ ‏ ‏مِنْ وَلَدِ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبَانَ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏خَرَجَ مِنْ عِنْدِ ‏ ‏مَرْوَانَ ‏ ‏نَحْوًا مِنْ نِصْفِ النَّهَارِ فَقُلْنَا مَا بَعَثَ إِلَيْهِ السَّاعَةَ إِلَّا لِشَيْءٍ سَأَلَهُ عَنْهُ فَقُمْتُ إِلَيْهِ فَسَأَلْتُهُ فَقَالَ أَجَلْ سَأَلَنَا عَنْ أَشْيَاءَ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏نَضَّرَ ‏ ‏اللَّهُ امْرَأً سَمِعَ مِنَّا حَدِيثًا فَحَفِظَهُ حَتَّى يُبَلِّغَهُ غَيْرَهُ فَإِنَّهُ رُبَّ حَامِلِ فِقْهٍ لَيْسَ بِفَقِيهٍ وَرُبَّ حَامِلِ فِقْهٍ إِلَى مَنْ هُوَ أَفْقَهُ مِنْهُ ثَلَاثُ خِصَالٍ لَا ‏ ‏يَغِلُّ ‏ ‏عَلَيْهِنَّ قَلْبُ مُسْلِمٍ أَبَدًا إِخْلَاصُ الْعَمَلِ لِلَّهِ وَمُنَاصَحَةُ ‏ ‏وُلَاةِ ‏ ‏الْأَمْرِ وَلُزُومُ الْجَمَاعَةِ فَإِنَّ دَعْوَتَهُمْ تُحِيطُ مِنْ وَرَائِهِمْ وَقَالَ مَنْ كَانَ هَمُّهُ الْآخِرَةَ جَمَعَ اللَّهُ شَمْلَهُ وَجَعَلَ غِنَاهُ فِي قَلْبِهِ وَأَتَتْهُ الدُّنْيَا وَهِيَ ‏ ‏رَاغِمَةٌ ‏ ‏وَمَنْ كَانَتْ ‏ ‏نِيَّتُهُ ‏ ‏الدُّنْيَا فَرَّقَ اللَّهُ عَلَيْهِ ضَيْعَتَهُ وَجَعَلَ فَقْرَهُ بَيْنَ عَيْنَيْهِ وَلَمْ يَأْتِهِ مِنْ الدُّنْيَا إِلَّا مَا كُتِبَ لَهُ وَسَأَلَنَا عَنْ الصَّلَاةِ الْوُسْطَى وَهِيَ الظُّهْرُ ‏","","",""],[20609,20609,"","আমি আমার বাবার সুখী ছেলের কথা বলেছি যে একজন যাজকের চেয়ে বেশি কিছু... ...যে আমার প্রিয় প্রভুর পতাকাটি পাঠ করে... ...তার জন্য প্রার্থনা করে...","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّجْمَ ‏ ‏فَلَمْ يَسْجُدْ ‏","","",""],[20610,20610,"","বাবার সাথে আমার বাবার মেয়ের সাথে বড় হওয়ার জন্য আমরা কিছু করেছি, সে ঈশ্বরের কাছে প্রার্থনা করলো আর তার চাকরের কাছে সাহায্য করল আমি আমার পরিবারের সঙ্গে প্রার্থনা করেছিলাম এবং আমার স্ত্রী ও দুই ছেলেমেয়ের সঙ্গে আমার দেখা হয়েছিল । আমি ইতোমধ্যে আমার ক্যারিয়ারের ফোকাস নিয়ে কথা বলেছি. ওয়েল, এটা শুধুমাত্র একটি উপায় তিনি তার শান্তির জন্য প্রার্থনা করেছেন এবং তিনি কি করছেন তার স্বপ্ন রেখেছেন.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ أَبِي الْجَهْمِ بْنِ صُخَيْرٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةَ الْخَوْفِ ‏ ‏بِذِي قَرَدٍ ‏ ‏أَرْضٌ مِنْ أَرْضِ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏فَصَفَّ النَّاسُ خَلْفَهُ صَفَّيْنِ صَفًّا ‏ ‏يُوَازِي الْعَدُوَّ وَصَفًّا خَلْفَهُ فَصَلَّى بِالصَّفِّ الَّذِي يَلِيهِ رَكْعَةً ثُمَّ ‏ ‏نَكَصَ ‏ ‏هَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ وَهَؤُلَاءِ إِلَى ‏ ‏مَصَافِّ ‏ ‏هَؤُلَاءِ فَصَلَّى بِهِمْ رَكْعَةً أُخْرَى ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ الْفَزَارِيِّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى صَلَاةَ الْخَوْفِ ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏ابْنِ عَبَّاسٍ ‏","","",""],[20611,20611,"","আমরা ইতোমধ্যে ঈশ্বরের সাহায্য নিয়ে একটি সুখী পৃথিবীতে আমার বাবার ছেলেকে নিয়ে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بِسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ بِحُجْرَةٍ فَكَانَ ‏ ‏يَخْرُجُ ‏ ‏يُصَلِّي فِيهَا ‏ ‏فَفَطِنَ ‏ ‏لَهُ أَصْحَابُهُ فَكَانُوا يُصَلُّونَ بِصَلَاتِهِ ‏","","",""],[20612,20612,"","আমরা খালি পায়ে হেঁটে কথা বলেছিলাম, বাবার গলা দিয়ে কথা বলার চেষ্টা করলাম, কিন্তু পাইলটদের একটা ছেলেকে হাতে তুলে দিতে হয়েছে যে বললো যে ঈশ্বর প্রার্থনা করছেন আর তা হবে। তিনি আমাকে বলেন যে, তার দুটো প্রার্থনা ছিল আর তারপর দুটো প্রার্থনা ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُو بْنُ أَبِي حَكِيمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الزِّبْرِقَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَاجِرَةِ ‏ ‏وَلَمْ يَكُنْ ‏ ‏يُصَلِّي صَلَاةً أَشَدَّ عَلَى ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهَا قَالَ فَنَزَلَتْ ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ‏} ‏وَقَالَ إِنَّ قَبْلَهَا صَلَاتَيْنِ وَبَعْدَهَا صَلَاتَيْنِ ‏","","",""],[20613,20613,"","আমরা অনেক কিছুর জন্য ভালো কাপুরুষ হওয়ার কথা বলেছি, একজন তরুণী যিনি রাজার কাছে লিখেছিলেন। তিনি বলবেন শেখ আর শিখ এরপর পরাজিত হবে। যদি তারা তাদের হত্যা করে, আল্লাহ আছে আর আমি তাকে বলবো যে সে তোমাকে কিভাবে ঘৃণা করে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏يُونُسَ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ الصَّلْتِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏ابْنُ الْعَاصِ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏يَكْتُبَانِ الْمَصَاحِفَ فَمَرُّوا عَلَى هَذِهِ الْآيَةِ فَقَالَ ‏ ‏زَيْدٌ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الشَّيْخُ وَالشَّيْخَةُ إِذَا زَنَيَا فَارْجُمُوهُمَا ‏ ‏الْبَتَّةَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏لَمَّا أُنْزِلَتْ هَذِهِ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَكْتِبْنِيهَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَكَأَنَّهُ كَرِهَ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏أَلَا ‏ ‏تَرَى أَنَّ الشَّيْخَ إِذَا لَمْ ‏ ‏يُحْصَنْ ‏ ‏جُلِدَ وَأَنَّ الشَّابَّ إِذَا زَنَى وَقَدْ ‏ ‏أُحْصِنَ ‏ ‏رُجِمَ ‏","","",""],[20614,20614,"","আমরা যে আবেগ নিয়ে প্রার্থনা করেছি তা হল প্রভুর বাণী যা প্রভুর আগুনের শিখার কথা শোনা যাবে। নিজের চোখেই গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَاضِرَ بْنَ الْمُهَاجِرِ الْبَاهِلِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُلَيْمَانَ بْنَ يَسَارٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ ذِئْبًا ‏ ‏نَيَّبَ ‏ ‏فِي شَاةٍ فَذَبَحُوهَا بِمَرْوَةٍ فَرَخَّصَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَكْلِهَا ‏","","",""],[20615,20615,"","বাবার ছেলে বাবার সাথে আমার বাবার বিয়ের পর বিয়ের ব্যাপারে কথা বলেছিলাম, কিন্তু তার পর ভাববাদী তার কাছে প্রার্থনা করে তাকে বলতে বলল যে তারা কি বলছে গুলি করো।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20616,20616,"","আমরা কথা বলেছি তৃতীয় পক্ষের পোশাকের চেয়ে একটু বেশি। ভগবান তার কাছে প্রার্থনা করেছেন আর তার সাথে বাইরে গিয়ে তার সাথে দেখা করতে চলে গেছেন। ঈশ্বর তাকে জিজ্ঞেস করবেন না, তাকে কিছু করতে হবে না।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَرَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ بِقِتْلَتِهِمْ وَفِرْقَةٌ تَقُولُ لَا فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي ‏ ‏الْخَبَثَ ‏ ‏كَمَا تَنْفِي النَّارُ ‏ ‏خَبَثَ ‏ ‏الْفِضَّةِ ‏","","",""],[20617,20617,"","আমরা বলেছিলাম, আমি কতবার মূল্য পাব। ৩ ও ২ বার প্রার্থনা করবো। সে তাকে বলতে বলেছে ঈশ্বর তার কাছে প্রার্থনা করেছে আর তাকে বলতে বলেছে যে, ঈশ্বর তাকে প্রার্থনা করেছেন তার সেবা জমা দাও.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُمِرْنَا أَنْ نُسَبِّحَ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ فَأُتِيَ رَجُلٌ فِي الْمَنَامِ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقِيلَ لَهُ أَمَرَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُسَبِّحُوا فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ كَذَا وَكَذَا قَالَ الْأَنْصَارِيُّ فِي مَنَامِهِ نَعَمْ قَالَ فَاجْعَلُوهَا خَمْسًا وَعِشْرِينَ خَمْسًا وَعِشْرِينَ وَاجْعَلُوا فِيهَا ‏ ‏التَّهْلِيلَ ‏ ‏فَلَمَّا أَصْبَحَ ‏ ‏غَدَا ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَافْعَلُوا ‏","","",""],[20618,20618,"","আমি পার্টির সেরা লোকদের ব্যাপারে কথা বলেছি, আমি চলে যাওয়ার জন্য বিখ্যাত হয়ে যাবার জন্য ক্লান্ত। আল্লাহ তার জন্য প্রার্থনা করেছেন এবং তাকে দেখার জন্য নিজেকে আত্মসমর্পণ করবেন। মন খারাপ মা, আমি ঈশ্বরের ক্রুশে যেতে ভালোবাসি, কিন্তু আমি এখন সময় মত তার প্রভুর অনুগ্রহ নিয়ে যেতে চাই, ঈশ্বর তাকে উদ্ধার করতে হবে এবং আমি ভয় পাচ্ছি, যতক্ষণ না তিনি আমাকে আত্মসমর্পণ করবেন। বিশ্বাসের নিয়ম আমার প্রথম বিবেক এবং পৃথিবী ঈশ্বরের হাল্কের ভিতরে আবদ্ধ, তাই আমি ঈশ্বরের দোহাই দিয়ে আবদ্ধ থাকবো। তার কাঁধে বলা হয়েছিল যে, তিনি একজন যুবতীর দ্বারা আবদ্ধ আছেন, যিনি তাকে বলেছিলেন যে, তিনি ঈশ্বরের কাছে এসেছিলেন । চিহ্নিত পংক্তির পূর্ববর্তী উপস্থিতি সনাক্ত করুন","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَكْتُبُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اكْتُبْ لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ فَجَاءَ ‏ ‏عَبْدُ اللَّهِ ابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أُحِبُّ الْجِهَادَ فِي سَبِيلِ اللَّهِ وَلَكِنْ بِي مِنْ ‏ ‏الزَّمَانَةِ ‏ ‏وَقَدْ ‏ ‏تَرَى وَذَهَبَ بَصَرِي قَالَ ‏ ‏زَيْدٌ ‏ ‏فَثَقُلَتْ فَخِذُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي حَتَّى خَشِيتُ أَنْ ‏ ‏تَرُضَّهَا ‏ ‏فَقَالَ اكْتُبْ ‏ { ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ ‏} ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏صَالِحٍ ‏ ‏قَالَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏حَدَّثَنِي ‏ ‏سَهْلُ بْنُ سَعْدٍ السَّاعِدِيُّ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ ‏ ‏مَرْوَانَ بْنَ الْحَكَمِ ‏ ‏جَالِسًا فِي الْمَسْجِدِ فَأَقْبَلْتُ حَتَّى جَلَسْتُ إِلَى جَنْبِهِ ‏ ‏فَأَخْبَرَنَا أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْلَى عَلَيْهِ ‏ { ‏لَا يَسْتَوِي الْقَاعِدُونَ ‏} ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[20619,20619,"","আমরা একটা খারাপের সাথে কথা বলেছি যখন আমি একটা আত্মা নিয়ে কথা বলেছি। সে একটা ছেলে যে ঈশ্বরের দোহাই প্রার্থনা করছে আর তাকে রাতে উদ্ধার করা হয়েছে। রাতে সে আমাকে ভয় পায় যে তারা ঈশ্বরের সর্বোচ্চ ঈশ্বর শান্তি এবং এটি করতে হবে এবং এটি করতে হবে. খুন, তুমি এটা করোনি... ...আর আমি তার নিজের বাড়িতে একজনের প্রার্থনা পছন্দ করি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنِي ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْلَةً فَسَمِعَ أَهْلُ الْمَسْجِدِ صَلَاتَهُ قَالَ فَكَثُرَ النَّاسُ اللَّيْلَةَ الثَّانِيَةَ فَخَفِيَ عَلَيْهِمْ صَوْتُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلُوا ‏ ‏يَسْتَأْنِسُونَ ‏ ‏وَيَتَنَحْنَحُونَ ‏ ‏قَالَ فَاطَّلَعَ عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَا زِلْتُمْ بِالَّذِي تَصْنَعُونَ حَتَّى خَشِيتُ أَنْ يُكْتَبَ عَلَيْكُمْ وَلَوْ كُتِبَتْ عَلَيْكُمْ مَا قُمْتُمْ بِهَا وَإِنَّ أَفْضَلَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا صَلَاةَ الْمَكْتُوبَةِ ‏","","",""],[20620,20620,"","আমরা দুই বছর ধরে কথা বলেছি যখন আমার বাবার ছেলে লর্ডের কাছে যায়, আমি দুঃখিত যে ঈশ্বর তার শান্তি এবং ঈশ্বরের দোহাই দিয়ে আল্লাহ তাকে রক্ষা করেছেন। রাজার সাথে কথা বলে আমি আমার বাবার মত হয়ে যাব.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏","","",""],[20621,20621,"","আমরা একটি ছেলে সম্পর্কে কথা বলেছি যে আমার বাবার মেয়ের প্রেমে আমাদের সাথে কথা বলেছে। অন্ধকারের জন্য ফেলে দাও, যাকে ছুড়ে ফেলা হয়েছে.","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِمَاسَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا حِينَ قَالَ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏قُلْتُ مَا بَالُ ‏ ‏الشَّامِ ‏ ‏قَالَ ‏ ‏الْمَلَائِكَةُ بَاسِطُو أَجْنِحَتِهَا عَلَى ‏ ‏الشَّامِ ‏","","",""],[20622,20622,"","আমরা বাবার ভালবাসা চুরি করার চেষ্টা করেছি। আমি তাকে বলেছি, তিনি একটা নিয়মিত ছেলে। যে বলেছে, আমরা ঈশ্বরের অনুগ্রহ এবং ঈশ্বরের দয়া পেয়েছি, সে আপনাকে কেন বলছে, ঈশ্বর বলেছিলেন যে, আপনার আনুগত্য জেল পরিকল্পনার ভিত্তিতে ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ شِمَاسَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نُؤَلِّفُ الْقُرْآنَ مِنْ ‏ ‏الرِّقَاعِ ‏ ‏إِذْ قَالَ ‏ ‏طُوبَى ‏ ‏لِلشَّامِ ‏ ‏قِيلَ وَلِمَ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏إِنَّ مَلَائِكَةَ الرَّحْمَنِ بَاسِطَةٌ أَجْنِحَتَهَا عَلَيْهَا ‏","","",""],[20623,20623,"","আমরা একটা শাস্তির কথা বলেছিলাম যেটা আমাকে বলতে হবে কিন্তু আমি নিশ্চিত যে তাকে ঈশ্বরের কাছে প্রার্থনা করতে হবে মসজিদে উদ্ধার করতে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏يُخْبِرُنِي عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْتَجَمَ ‏ ‏فِي الْمَسْجِدِ ‏ ‏قُلْتُ ‏ ‏لِابْنِ لَهِيعَةَ ‏ ‏فِي مَسْجِدِ بَيْتِهِ ‏ ‏قَالَ ‏ ‏لَا فِي ‏ ‏مَسْجِدِ الرَّسُولِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20624,20624,"","আমি আপনাকে সংক্ষিপ্ত করে বলেছিলাম যে, আপনি আমার মূর্খের মতো মনে করেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন । তাকে যেতে বল.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبِي ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏أَوْ ‏ ‏أَبَا أَيُّوبَ ‏ ‏قَالَ ‏ ‏لِمَرْوَانَ ‏ ‏أَلَمْ ‏ ‏أَرَكَ قَصَّرْتَ سَجْدَتَيْ الْمَغْرِبِ رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِيهَا ‏ ‏بِالْأَعْرَافِ ‏","","",""],[20625,20625,"","আমরা একটি মেয়ে হিসেবে আপনার টাকা হারানোর কথা বলেছি। ঈশ্বর শপথ নেয়ার আগে তাকে আদেশ দিয়েছেন এবং আত্মসমর্পণ করেছেন। আমাদের শহরের ভেতরে.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اطَّلَعَ قِبَلَ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ وَاطَّلَعَ مِنْ قِبَلِ كَذَا فَقَالَ اللَّهُمَّ أَقْبِلْ بِقُلُوبِهِمْ وَبَارِكْ لَنَا فِي ‏ ‏صَاعِنَا ‏ ‏وَمُدِّنَا ‏","","",""],[20626,20626,"","আমরা কথা বলেছি বাবার রক্তের মাধ্যমে বাবার দাঁতের দুই ভাগের কথা, সে আমার শরীরে কিছু একটা পড়েছিল তার কাজ শোনার জন্য আমি পাপ করেছি তাদের প্রতি স্বপ্ন আর দয়া থাকে, কিন্তু একটা কাপুরুষের মত, আমি এটা করতে যাচ্ছি, ঈশ্বরের কাছে যা করা হয়েছে, তা করার জন্য। তুমি কখনো এটা পরিকল্পনা করোনি.","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سِنَانٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏وَهْبِ بْنِ خَالِدٍ الْحِمْصِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ الْقَدَرِ فَأَتَيْتُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَسَأَلْتُهُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ غَيْرَ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ لَكَ جَبَلُ ‏ ‏أُحُدٍ ‏ ‏أَوْ مِثْلُ جَبَلِ ‏ ‏أُحُدٍ ‏ ‏ذَهَبًا أَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ مَا قَبِلَهُ اللَّهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ وَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ وَأَنَّكَ إِنْ مِتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ ‏","","",""],[20627,20627,"","আগে যা শুনেছি তার চেয়ে আমরা অনেক ভালো করেছি। জলদস্যুদের বলা হয়েছে, তার জন্য ঈশ্বরের কাছে পাঠানো হয়েছে এবং তারা শান্তির জন্য প্রার্থনা করবে। ঈশ্বর যে শুধু ঈশ্বরের বিরুদ্ধে যুদ্ধ করে সেই লোকেদেরই আপনার কাছে ছিলেন । আর সে ফিরে যেতে পারবে না, তারপর সে ওটা উড়িয়ে দিবে। সেদিন বিকেলের পরই না আমি সিংহাসনের পরে কিছু করতে পেরেছি। ঈশ্বরের অনুগ্রহের শেষ থেকে, ঈশ্বর প্রার্থনা করেছেন। বিয়ের পাপের কারণে ঈশ্বর আমাকে আশীর্বাদ করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ هُبَيْرَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَبِيصَةَ بْنَ ذُؤَيْبٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْ آلَ ‏ ‏الزُّبَيْرِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عِنْدَهَا رَكْعَتَيْنِ بَعْدَ الْعَصْرِ فَكَانُوا يُصَلُّونَهَا ‏ ‏قَالَ ‏ ‏قَبِيصَةُ ‏ ‏فَقَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِعَائِشَةَ ‏ ‏نَحْنُ أَعْلَمُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَائِشَةَ ‏ ‏إِنَّمَا كَانَ ذَلِكَ لِأَنَّ أُنَاسًا مِنْ ‏ ‏الْأَعْرَابِ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِهَجِيرٍ ‏ ‏فَقَعَدُوا يَسْأَلُونَهُ ‏ ‏وَيُفْتِيهِمْ حَتَّى صَلَّى الظُّهْرَ وَلَمْ يُصَلِّ رَكْعَتَيْنِ ثُمَّ قَعَدَ ‏ ‏يُفْتِيهِمْ حَتَّى صَلَّى الْعَصْرَ فَانْصَرَفَ إِلَى بَيْتِهِ فَذَكَرَ أَنَّهُ لَمْ يُصَلِّ بَعْدَ الظُّهْرِ شَيْئًا فَصَلَّاهُمَا بَعْدَ الْعَصْرِ يَغْفِرُ اللَّهُ ‏ ‏لِعَائِشَةَ ‏ ‏نَحْنُ أَعْلَمُ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏عَائِشَةَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّلَاةِ بَعْدَ الْعَصْرِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ هُبَيْرَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ ذُؤَيْبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْ آلَ ‏ ‏الزُّبَيْرِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20628,20628,"","আমরা আমার বাবার ছেলের কথা বলেছিলাম একটি ছেলের জন্য একটা ছেলে খুঁজতে যে একটা মেয়ের মেয়ে ছিল যে একটা ছেলে ছিল যে তার ছেলে ছিল তার ছেলে ছিল, যে তার ছেলে সন্তান ছিল, যে তার ছেলে সন্তান ছিল, যে কিনা সন্তান ধারণ করেছিল। তার নিজের ভুল করে তার নিজের সমস্যা আর প্রিয়দের জন্য হস্তান্তর করেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُحَاقَلَةِ ‏ ‏وَالْمُزَابَنَةِ ‏","","",""],[20629,20629,"","আমরা আমার বাবার সাথে কথা বলেছি একজন পর্যটকের সাথে যেতে চেষ্টা করে। তিনি বলেছেন, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার বন্ধু হওয়ার আগ পর্যন্ত তৃতীয়টি বিক্রি করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبِيعُوا الثَّمَرَةَ حَتَّى يَبْدُوَ صَلَاحُهَا ‏","","",""],[20630,20630,"","আমরা একটি মেয়ে সম্পর্কে কথা বলেছি যে আমাদের একটি মেয়ে আছে যে কিনা সুখী হবে না, সে কথা বলেছে। ঈশ্বরের আত্মসমর্পণ করতে হবে এবং তারপর আমাদের সেই সার্ভিস থেকে বের হতে হবে কিভাবে কমান্ড করতে হবে। তুমি অনেক কিছু বলতে পারো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏تَسَحَّرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ خَرَجْنَا إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ بَيْنَ ذَلِكَ ‏ ‏قَالَ ‏ ‏قَدْرُ قِرَاءَةِ خَمْسِينَ آيَةً ‏","","",""],[20631,20631,"","আমি আমার বাবাকে সাহায্য করার চেষ্টা করেছি । আমাদের মধ্যে যারা পাপ করে, তারা বলে যে, সে পাপ করে । জড ছেলে, যে কিনা সফল করতে ব্যর্থ হয়েছে। তোমার বাবা জীবন থেকে ভালো লোকদের হত্যা করতে বড় হয়েছে, অথবা দশ বছর বয়সীদের দিয়ে, তুমি তোমার মন পরিবর্তন করেছ, যখন তারা তোমাকে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا تُوُفِّيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ خُطَبَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏فَجَعَلَ مِنْهُمْ مَنْ يَقُولُ ‏ ‏يَا مَعْشَرَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا اسْتَعْمَلَ رَجُلًا مِنْكُمْ قَرَنَ مَعَهُ رَجُلًا مِنَّا ‏ ‏فَنَرَى أَنْ يَلِيَ هَذَا الْأَمْرَ رَجُلَانِ أَحَدُهُمَا مِنْكُمْ وَالْآخَرُ مِنَّا قَالَ فَتَتَابَعَتْ خُطَبَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏عَلَى ذَلِكَ قَالَ فَقَامَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فَقَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَإِنَّمَا الْإِمَامُ يَكُونُ مِنْ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَنَحْنُ أَنْصَارُهُ كَمَا كُنَّا أَنْصَارَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ ‏ ‏جَزَاكُمْ اللَّهُ خَيْرًا مِنْ حَيٍّ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏وَثَبَّتَ قَائِلَكُمْ ثُمَّ قَالَ وَاللَّهِ لَوْ فَعَلْتُمْ غَيْرَ ذَلِكَ لَمَا صَالَحْنَاكُمْ ‏","","",""],[20632,20632,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি কিন্তু আমার বড় বাবার ভালো স্বাদ আছে। আমি তাকে বলেছি সে প্রভুর সাথে আসেনি। আমি বলছি, আমি তাকে ভালবাসি, আমার ছেলের আশীর্বাদ, ঈশ্বরের কাছে আমি তার কাছে প্রার্থনা করি আর সে তার ইচ্ছা পূর্ণ করবে, আর বলবে, আমার কাছে বই আছে, আমার কাছে সে চাইলে বই আছে। দশ বছর ধরে এটা করার পর আমি এটা লিখে রাখতে চাই যে, আমার বাবার ছেলের জীবন অভিজ্ঞতার পর আমরা বিছানায় যেতে চাই। কিন্তু একজন যুবক বলেছিল যে, ঈশ্বর তার জন্য প্রার্থনা করেছেন। আর আমি আমার বাবার ছেলের জন্য প্রার্থনা করছি। আর আমি আমার বাবার ছেলের জন্য এই বিষয়ে আমার বাবার সাথে কথা বলেছি। আমি যদি আমার বাবার ছেলের ছেলের জীবনের জন্য প্রার্থনা করি, তাহলে আমি তাকে বলতে চাই, আমি আমার বাবার সাথে আমার বাবার সাথে কথা বলতে চাই। আমি যদি আমার বাবার ছেলের ছেলের ছেলের জন্য প্রার্থনা করি, আমি যদি আমার ছেলের জন্য একটা ভাল সম্পর্ক করি, তাহলে আমি আমার ছেলের জন্য একটা ভাল সম্পর্ক গড়ে তুলতে চাই। আর আমি যদি আমার বাবার সাথে আমার বাবার মত আচরণ করি, তাহলে আমি আমার ছেলের জন্য আমার বাবার মত আচরণ করতে চাই। কিন্তু আমি যদি আমার বাবার ছেলের জন্য এটা একটা ভালো কিছু করতে চাই, তাহলে আমি আমার বাবাও করতে চাই না। কিন্তু আমি আমার বাবা আমাকে বলতে চাই যে, আমি আমার বাবা আমাকে এটা একটা কাজ করতে হবে। আর আমি কি করবো? কিন্তু আমি জানি না। আর আমি যদি আমার বাবা আমাকে জিজ্ঞেস করি, আমি জানি যে, আমি জানি যে, আমি আমার বাবা আমাকে ছেড়ে দেব। আর আমি জানি না যে, আমি কি করে, আমি জানি না। আর তার ভাগ্যকে আত্মসমর্পণ করে.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدًا ‏ ‏أَخْبَرَهُ أَنَّهُ ‏ ‏لَمَّا قَدِمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏ذُهِبَ بِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُعْجِبَ بِي فَقَالُوا يَا رَسُولَ اللَّهِ هَذَا غُلَامٌ مِنْ ‏ ‏بَنِي النَّجَّارِ ‏ ‏مَعَهُ مِمَّا أَنْزَلَ اللَّهُ عَلَيْكَ بِضْعَ عَشْرَةَ سُورَةً فَأَعْجَبَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ يَا ‏ ‏زَيْدُ ‏ ‏تَعَلَّمْ لِي كِتَابَ ‏ ‏يَهُودَ ‏ ‏فَإِنِّي وَاللَّهِ مَا آمَنُ ‏ ‏يَهُودَ ‏ ‏عَلَى كِتَابِي قَالَ ‏ ‏زَيْدٌ ‏ ‏فَتَعَلَّمْتُ كِتَابَهُمْ مَا مَرَّتْ بِي خَمْسَ عَشْرَةَ لَيْلَةً حَتَّى ‏ ‏حَذَقْتُهُ ‏ ‏وَكُنْتُ أَقْرَأُ لَهُ كُتُبَهُمْ إِذَا كَتَبُوا إِلَيْهِ وَأُجِيبُ عَنْهُ إِذَا كَتَبَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ ‏ ‏الْمَدِينَةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[20633,20633,"","আমরা একটি মৃত দেহ সম্পর্কে কথা বলেছি যে আমরা একটি মাত্র বার-এর দ্বারা আবদ্ধ না এবং একই নিয়মের দ্বারা আবদ্ধ না। কিন্তু একজন যুবক বলেছিল আমরা লর্ডের লর্ডশিপ থেকে মুক্ত এবং আমাদের যেতে দেব। পাঁচ বছর আগে সে তার নিজের সময় আরো বেশি বলেছে, পাঁচ বছর আগে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏ح ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏ح ‏ ‏وَوَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَرَجْنَا إِلَى الْمَسْجِدِ وَأُقِيمَتْ الصَّلَاةُ ‏ ‏فَقُلْتُ كَمْ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً قَالَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏فِي حَدِيثِهِ فَقُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ كَانَ قَدْرُ مَا بَيْنَهُمَا قَالَ نَحْوًا مِنْ خَمْسِينَ آيَةً ‏","","",""],[20634,20634,"","আমরা কয়েক বছর সুখী হওয়ার কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর সে আমাদের লর্ডকে খুঁজে পেতে ব্যর্থ হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏الدَّسْتَوَائِيُّ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏تَسَحَّرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجْنَا إِلَى الْمَسْجِدِ فَأُقِيمَتْ الصَّلَاةُ ‏ ‏قُلْتُ كَمْ كَانَ بَيْنَهُمَا قَالَ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً ‏","","",""],[20635,20635,"","আমরা অনেক বার আগেও কথা বলেছি। দুপুরের দিকে চোররা বলল এটা প্রভুর প্রার্থনা এবং তার শান্তি শেষ হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ سُئِلَ عَنْ الْقِرَاءَةِ فِي الظُّهْرِ وَالْعَصْرِ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطِيلُ الْقِيَامَ وَيُحَرِّكُ شَفَتَيْهِ ‏","","",""],[20636,20636,"","আমরা অনেকবার কথা বলেছি এবং আমাদের বাবার ছেলেকে অনেক কিছু বলা হয়েছে, ঈশ্বরের পুত্রকে কঠিন সময় দিতে। কিন্তু আমি ঈশ্বরের ইচ্ছা সম্পর্কে পড়েছি, ঈশ্বরের শান্তি এবং বিশ্বের জীবন হবে। তার নিজের হাতে, ঈশ্বরের বার্তাবাহক তাকে উদ্ধার করেছেন এবং উদ্ধার করেছেন","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَا ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّجْمِ ‏ ‏فَلَمْ يَسْجُدْ فِيهَا ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏قَرَأْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20637,20637,"","আমরা ইতোমধ্যে বাবার রক্ত নিয়ে ঈশ্বরের সাহায্য নিয়ে কথা বলেছি। শেষটি হলো ঈশ্বরের কাছে প্রার্থনা করা। আর আমি তার মৃত্যুর প্রার্থনা পছন্দ করবো।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الْمَكْتُوبَةَ ‏","","",""],[20638,20638,"","আমরা রাজাকে তার বাবার পাপের কথা বলেছিলাম আর তারপর আমরা বাবার পাপের মধ্য দিয়ে গিয়েছিলাম। দুই বছরের ছেলে যে কিনা আমাদের রক্ষা করবে। ঈশ্বর বলে যে ঈশ্বরের দেবতা তাদের নবী দ্বারা নিযুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏وَعُثْمَانُ بْنُ عُمَرَ ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَاتَلَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَقَالَ ‏ ‏عُثْمَانُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏","","",""],[20639,20639,"","আমরা আমাদের জীবনের সেরাটা নিয়ে কথা বলেছিলাম, ঈশ্বরের কাছে প্রার্থনা করে প্রভুকে জিততে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَمْلَاهُ عَلَيْنَا ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الرُّقْبَى ‏ ‏لِلْوَارِثِ ‏","","",""],[20640,20640,"","আমরা আপনার টাকা নিয়ে কথা বলেছি একটি ছেলের জন্য যে ছেলে জিততে পারবে না, সে এমন একটা ছেলে যে তাকে জিততে দেবে না। সে একজন মানুষকে তার কাছে এই জলাঞ্জলি কম্প্রেশন বিক্রির জন্য দিয়েছে। বের হও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لِصَاحِبِ ‏ ‏الْعَرِيَّةِ ‏ ‏أَنْ يَبِيعَهَا ‏ ‏بِخَرْصِهَا ‏","","",""],[20641,20641,"","আমি ক্ষমা চেয়ে আমার বাবাকে বাঁচাতে চেষ্টা করেছি। তারা বলেছে, খোদা এটা করেছে, তিনি একটা টাকাও শুনতে পাবেন না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عُبَيْدَةَ بْنِ مُحَمَّدِ بْنِ عَمَّارٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي الْوَلِيدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏يَغْفِرُ اللَّهُ ‏ ‏لِرَافِعِ بْنِ خَدِيجٍ ‏ ‏أَنَا وَاللَّهِ أَعْلَمُ بِالْحَدِيثِ مِنْهُ إِنَّمَا ‏ ‏أَتَى رَجُلَانِ قَدْ اقْتَتَلَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كَانَ هَذَا شَأْنَكُمْ فَلَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏ ‏قَالَ ‏ ‏فَسَمِعَ ‏ ‏رَافِعٌ ‏ ‏قَوْلَهُ لَا ‏ ‏تُكْرُوا ‏ ‏الْمَزَارِعَ ‏","","",""],[20642,20642,"","আমরা এমন আবেগ কাটিয়ে ওঠার চেষ্টা করেছি, যা একবার আমার বাবার সাথে বিশ্বাসঘাতকতা করেছে। কিন্তু, এক কঠিন প্রচেষ্টা করা হয়েছে । আমার বাবা বলেছিলেন যে, এই দুটো ঘটনা ঠিক যেন আপনার প্রতি ঘটে, সেই কাজগুলো করার জন্য আমার বাবা খুশি হবেন, যা তাকে গুলি করতে হত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الْبَخْتَرِيِّ الطَّائِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَمَّا نَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ ‏} ‏قَالَ قَرَأَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى خَتَمَهَا وَقَالَ النَّاسُ ‏ ‏حَيِّزٌ ‏ ‏وَأَنَا وَأَصْحَابِي ‏ ‏حَيِّزٌ ‏ ‏وَقَالَ لَا هِجْرَةَ بَعْدَ الْفَتْحِ وَلَكِنْ جِهَادٌ وَنِيَّةٌ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مَرْوَانُ ‏ ‏كَذَبْتَ وَعِنْدَهُ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمَا قَاعِدَانِ مَعَهُ عَلَى السَّرِيرِ فَقَالَ ‏ ‏أَبُو سَعِيدٍ الْخُدْرِيُّ ‏ ‏لَوْ شَاءَ هَذَانِ لَحَدَّثَاكَ فَرَفَعَ عَلَيْهِ ‏ ‏مَرْوَانُ ‏ ‏الدِّرَّةَ ‏ ‏لِيَضْرِبَهُ فَلَمَّا رَأَيَا ذَلِكَ قَالَا ‏ ‏صَدَقَ ‏","","",""],[20643,20643,"","আমরা একটা ছেলের কথা বলেছিলাম যে এমনকি আমাকে বলতে পারবে না, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার একজনের কাছে আত্মসমর্পণ করেছেন। তারা দুজন দল এই কথা দিয়ে দেবে। হত্যা করা হচ্ছে তাদের জন্য অগ্নি নির্বাপক। তারা বলে যে একজন মানুষ দেবতা। সে চলে যাওয়ার পর আমি শুনেছি ঈশ্বর আমার সাথে কথা বলার সময় তার মন আরও বাড়িয়ে তুলবে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَرَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِمْ فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ بِقَتْلِهِمْ وَفِرْقَةٌ تَقُولُ لَا ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَكَانَ النَّاسُ فِيهِمْ فِرْقَتَيْنِ فَرِيقًا يَقُولُونَ بِقَتْلِهِمْ وَفَرِيقًا يَقُولُونَ لَا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏ ‏حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏فِيهِ ‏ ‏سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏بَهْزٍ ‏","","",""],[20644,20644,"","আমরা অনেক কথা বলেছি সে কি যুক্তি সম্পর্কে জানতে সে বলেছে সে এখনো ছেলে. আমি যে বুদ্ধিমত্তার কথা বলেছি বা গোয়েন্দা বলা হয় ঋণের জন্য ভাড়া অর্ধেক অথবা তৃতীয়।","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرٌ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏قُلْتُ وَمَا ‏ ‏الْمُخَابَرَةُ ‏ ‏قَالَ يَأْجُرُ الْأَرْضَ بِنِصْفٍ أَوْ بِثُلُثٍ أَوْ بِرُبُعٍ ‏","","",""],[20645,20645,"","আমরা ঈশ্বরের সাথে আমার ছেলের প্রেমে আমার বাবার সাথে আমার ছেলের প্রেমে আমার সাহায্য করার কথা বলেছিলাম। ঈশ্বরের কাছে প্রার্থনা করতে বলা হয়েছে, তার কাছে প্রার্থনা করেছে এবং মসজিদে তাকে উদ্ধার করা হয়েছে। রাতে সে আমার কাছে প্রার্থনা করবে যেন সে তার প্রার্থনা করে। মানে, সে আমার কাছে এমন একজন লোক হবে যে তার নিজেরই হবে। লর্ড তার প্রভুর কাছে প্রার্থনা করতে আসে নি। আর আমি তোমাকে একটা বোকা দেব যারা বলেছে যে মানুষ যা করেছে তাই করতে হবে। তোমার বাড়িতে প্রার্থনা করে, একটার জন্য প্রার্থনা করা ভালো।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏احْتَجَرَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ حُجْرَةً وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ مِنْ اللَّيْلِ فَيُصَلِّي فِيهَا فَصَلَّوْا مَعَهُ بِصَلَاتِهِ ‏ ‏يَعْنِي رِجَالًا ‏ ‏وَكَانُوا يَأْتُونَهُ كُلَّ لَيْلَةٍ حَتَّى إِذَا كَانَ لَيْلَةٌ مِنْ اللَّيَالِي لَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَنَحْنَحُوا وَرَفَعُوا أَصْوَاتَهُمْ قَالَ فَخَرَجَ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُغْضَبًا قَالَ فَقَالَ لَهُمْ أَيُّهَا النَّاسُ ‏ ‏مَا زَالَ بِكُمْ صَنِيعُكُمْ حَتَّى ظَنَنْتُ أَنْ سَيُكْتَبُ عَلَيْكُمْ فَعَلَيْكُمْ بِالصَّلَاةِ فِي بُيُوتِكُمْ فَإِنَّ خَيْرَ صَلَاةِ الْمَرْءِ فِي بَيْتِهِ إِلَّا الصَّلَاةَ الْمَكْتُوبَةَ ‏","","",""],[20646,20646,"","আমরা এমন একটা ছেলের সাথে লড়াই করতে কথা বলেছি যার সাথে যুদ্ধ করতে হবে। নিয়ম আমাকে বলল যে আমি আজ রাতে যেতে চাই নি... ... গৌরবের গৌরবে পড়ার ভয় পাওয়ার জন্য। আমাকে দেওয়া হয়েছে আর কাপড়ের মধ্যে পড়া না করার জন্য পৌঁছে দেয়া হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَرْوَانَ بْنِ الْحَكَمِ ‏ ‏قَالَ ‏ ‏قَالَ لِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَلَمْ أَرَكَ اللَّيْلَةَ ‏ ‏خَفَّفْتَ الْقِرَاءَةَ فِي سَجْدَتَيْ الْمَغْرِبِ وَالَّذِي نَفْسِي بِيَدِهِ إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَقْرَأُ فِيهِمَا ‏ ‏بِطُولَى ‏ ‏الطُّولَيَيْنِ ‏","","",""],[20647,20647,"","আমরা কথা বলেছিলাম যে আমাকে একটা ছেলে বলতে হবে যে আমি এটা শুনতে চাই। সে ঈশ্বরের কাছে প্রার্থনা করতে যায় নি এবং সে সেই লোকদের কাছে আত্মসমর্পণ করে। ঈশ্বর দুটি দলকে আত্মসমর্পণ করেছেন যারা বলেছে তাদের হত্যা করতে আর হত্যা করতে। তাদের বলে কোন ছেলে বলে না যে তারা বলে ঈশ্বরের কথা শোনে না যখন সে ঈশ্বরের কাছে প্রার্থনা করছিল। সে ভালো আছে, আর সে শেষ পর্যন্ত মারা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَدِيُّ بْنُ ثَابِتٍ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏أُحُدٍ ‏ ‏رَجَعَ أُنَاسٌ خَرَجُوا مَعَهُ فَكَانَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ فِرْقَةٌ تَقُولُ نَقْتُلُهُمْ وَفِرْقَةٌ تَقُولُ لَا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فَكَانَ فَرِيقٌ يَقُولُونَ قَتْلَهُمْ وَفَرِيقٌ يَقُولُونَ لَا ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فَأَنْزَلَ اللَّهُ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏","","",""],[20648,20648,"","আমরা একটি সাদা ছেলের সাথে কথা বলেছি যার বাবা রাগের জন্য ঘোমটা। আমরা ঈশ্বরের কাছে প্রার্থনা করবো তার আদেশের জন্য। অর্ধেক বা অর্ধেক বা চার।","‏ ‏حَدَّثَنَا ‏ ‏فَيَّاضُ بْنُ مُحَمَّدٍ أَبُو مُحَمَّدٍ الرَّقِّيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرٍ يَعْنِي ابْنَ بُرْقَانَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏نَهَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْمُخَابَرَةِ ‏ ‏قَالَ وَقِيلَ لَهُ مَا ‏ ‏الْمُخَابَرَةُ ‏ ‏قَالَ أَنْ تَأْخُذَ الْأَرْضَ بِنِصْفٍ أَوْ بِثُلُثٍ أَوْ بِرُبُعٍ أَوْ بِأَشْبَاهِ هَذَا ‏","","",""],[20649,20649,"","আমরা একটা ছেলেকে খুঁজে বের করার জন্য একটু আগ্রহ নিয়ে এসেছি, যে কিনা একটা জামা পেয়েছে। আমি এভাবে বলেছি যে, আমি হয়তো আমার মাথা হারিয়ে ফেলেছি। লর্ড তার কাছে প্রার্থনা করে এবং আত্মসমর্পণ করে। আমি বলেছিলাম, আমি যদি আমার মনের অবস্থা হারিয়ে ফেলি, তাহলে আমি যেন আমার মন হারিয়ে ফেলেছি। আমি আমার মনের কথা বলি, আমি যেন আমি আমার মনের কথা বলি, আমি আমার মন হারিয়ে ফেলেছি। আমি আমার মনের কথা বলছি, তাই, কতজন কপট মহিলা বলেছিল যে, তিনি কতটা ভয় পেয়েছিলেন, তা তিনি কত জনই না বর্ণনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ وَاللَّهُ ‏ ‏أَرْكَسَهُمْ ‏ ‏بِمَا كَسَبُوا ‏} ‏قَالَ رَجَعَ أُنَاسٌ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَانَ النَّاسُ فِيهِمْ فِرْقَتَيْنِ فَرِيقٌ يَقُولُونَ قَتْلَهُمْ وَفَرِيقٌ يَقُولُونَ لَا فَنَزَلَتْ هَذِهِ الْآيَةُ ‏ { ‏فَمَا لَكُمْ فِي الْمُنَافِقِينَ فِئَتَيْنِ ‏} ‏وَقَالَ إِنَّهَا ‏ ‏طَيْبَةُ ‏ ‏وَإِنَّهَا تَنْفِي الْخَبَثَ كَمَا تَنْفِي النَّارُ خَبَثَ الْفِضَّةِ ‏","","",""],[20650,20650,"","আমরা বাবার ছেলেকে জেতার কথা বলেছিলাম, তার চেয়ে ভালো ছেলেকে খুঁজে বের করে, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তারপর আমরা বললাম যে আমরা প্রার্থনা না করে বেরিয়েছি, তিনি বললেন, তিনি পড়ে গেছেন। তিনি বললেন, তিনি পড়ে গেছেন। পাঁচ বছর অথবা ৬০ পাউন্ড।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ أَبُو الْأَسْوَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏تَسَحَّرَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ثُمَّ خَرَجْنَا حَتَّى أَتَيْنَا الصَّلَاةَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَقُلْتُ ‏ ‏لِزَيْدٍ ‏ ‏كَمْ كَانَ بَيْنَ ذَلِكَ ‏ ‏قَالَ ‏ ‏قَدْرُ قِرَاءَةِ خَمْسِينَ آيَةً ‏ ‏أَوْ سِتِّينَ آيَةً ‏","","",""],[20651,20651,"","আমরা একজন দাসের কথা বলেছি যে আমাদের সাথে কথা বলেছে একটা ছেলের জন্য যে কিনা জয় লাভ করেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে সারা রাত ছেড়ে অন্য কাউকে দিয়ে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي بَيْعِ ‏ ‏الْعَرَايَا ‏ ‏بِخَرْصِهَا ‏ ‏كَيْلًا ‏","","",""],[20652,20652,"","আমরা কিছু আশীর্বাদের বিচার করেছি আমরা, আমরা কথা বলেছি আর তারপর আমি একটি বিবাহ আর একজন বোনের জন্য অনুরোধ করছি, যে বিছানায় গিয়েছে আর তার জন্য। সৎ, ঈশ্বর আপনার সাথে শান্তি স্থাপন করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏وَعَطِيَّةَ ‏ ‏وَضَمْرَةَ ‏ ‏وَرَاشِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ ‏ ‏سُئِلَ عَنْ زَوْجٍ وَأُخْتٍ لِأُمٍّ وَأَبٍ فَأَعْطَى الزَّوْجَ النِّصْفَ وَالْأُخْتَ النِّصْفَ فَكُلِّمَ فِي ذَلِكَ فَقَالَ حَضَرْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بِذَلِكَ ‏","","",""],[20653,20653,"","কিন্তু, আমি যখন তাকে বলি যে, আমি একটা ঘোড়াকে হারিয়ে ফেলব, তখন আমি তাকে বলেছিলাম যে, একটা ঘোড়া ডাইনির কাছে হারিয়ে যাবে । আমি হয়ত ভাববাদীর কাছে প্রার্থনা শুনতে পেলাম এবং তার স্পর্শ করতে শুনেছি। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَسَخْنَا الْمَصَاحِفَ ‏ ‏فُقِدَتْ آيَةٌ مِنْ سُورَةِ ‏ ‏الْأَحْزَابِ ‏ ‏قَدْ كُنْتُ أَسْمَعُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا فَالْتَمَسْتُهَا فَلَمْ أَجِدْهَا مَعَ أَحَدٍ إِلَّا مَعَ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ الْأَنْصَارِيِّ ‏ ‏الَّذِي جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهَادَتَهُ شَهَادَةَ رَجُلَيْنِ قَوْلُ اللَّهِ عَزَّ وَجَلَّ ‏ { ‏مِنْ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏}","","",""],[20654,20654,"","আমরা একটা আবেগ দিয়ে বাপ্তাইজিত হয়েছি, যা আমার বাবার ছেলের জন্য একটা সাহসী পুত্র সৃষ্টি করেছে, যার সাথে আমাকে বলা হয়েছে আমি সেই লোকের ভয় পাই না যে অন্য কারো ভয় পায়। আমি তাকে বলে দিয়েছি, সে হয়তো সূর্যের আলোয় পড়তে পারে। সে তার কাছে সব রকম বলতে পারে আমার বাবার ছেলে রাজা এবং সে এমনকি সে তা করতে পারে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ لَهُ مَا لِي أَرَاكَ ‏ ‏تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ السُّوَرِ قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِيهَا ‏ ‏بِطُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ أَبِي مُلَيْكَةَ ‏ ‏وَمَا ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏الْأَعْرَافُ ‏","","",""],[20655,20655,"","আমরা সুই নিয়ে কথা বলেছি, আমার ঘোড়া দিয়ে যাত্রা করা সবচেয়ে ভালো। আমি তাকে বলেছি আমি মাতাল। আল্লাহ তাঁর কাছে প্রার্থনা করুন এবং আগুনের ভেতর থেকে আলো জ্বালাবেন।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20656,20656,"","বাবা যখন মাতাল ছিলেন, তখন তিনি বলেছিলেন যে, আমরা যে - অনুষ্ঠানের জন্য কথা বলেছিলাম, তার কোনো দুঃখ নেই । তার গৌরব, বিশ্বাসঘাতকতার সাথে.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَخْبَرَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏يَقُولُ ‏ ‏فُقِدَتْ آيَةٌ مِنْ سُورَةِ ‏ ‏الْأَحْزَابِ ‏ ‏حِينَ نَسَخْنَا الْمَصَاحِفَ قَدْ كُنْتُ أَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ بِهَا ‏ { ‏رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏} ‏فَالْتَمَسْتُهَا فَوَجَدْتُهَا مَعَ ‏ ‏خُزَيْمَةَ بْنِ ثَابِتٍ ‏ ‏فَأَلْحَقْتُهَا فِي سُورَتِهَا فِي الْمُصْحَفِ ‏","","",""],[20657,20657,"","কয়েক দিন পর আমরা যেভাবে কথা বলেছিলাম, সেই বিষয়ে আমরা কথা বলেছিলাম । ঈশ্বর আমাকে নিশ্চয়ই একটা পর্বতের মূল্য দিতে পারতেন, কখনও বিশ্বাস করতেন না যে, এটা ঈশ্বর করেছেন । তার কাছে প্রার্থনা করুন এবং এটা প্রদান করা হবে ঈশ্বরের শান্তি যেন মুক্তি হয়। আমার বাবা বড় হয়েছেন, তিনি তাদের জন্য আমার পরিতৃপ্তি বয়ে এনেছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَ إِلَيَّ ‏ ‏أَبُو بَكْرٍ ‏ ‏مَقْتَلَ أَهْلِ ‏ ‏الْيَمَامَةِ ‏ ‏فَإِذَا ‏ ‏عُمَرُ ‏ ‏عِنْدَهُ جَالِسٌ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَا ‏ ‏زَيْدُ بْنَ ثَابِتٍ ‏ ‏إِنَّكَ غُلَامٌ شَابٌّ عَاقِلٌ لَا نَتَّهِمُكَ قَدْ كُنْتَ تَكْتُبُ الْوَحْيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَتَبَّعْ الْقُرْآنَ فَاجْمَعْهُ قَالَ ‏ ‏زَيْدٌ ‏ ‏فَوَاللَّهِ ‏ ‏لَوْ كَلَّفُونِي نَقْلَ جَبَلٍ مِنْ الْجِبَالِ مَا كَانَ أَثْقَلَ عَلَيَّ مِمَّا أَمَرَنِي بِهِ مِنْ جَمْعِ الْقُرْآنِ فَقُلْتُ أَتَفْعَلَانِ شَيْئًا لَمْ يَفْعَلْهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ هُوَ وَاللَّهِ خَيْرٌ فَلَمْ يَزَلْ ‏ ‏أَبُو بَكْرٍ ‏ ‏يُرَاجِعُنِي حَتَّى شَرَحَ اللَّهُ صَدْرِي بِالَّذِي شَرَحَ لَهُ صَدْرَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[20658,20658,"","আমরা বাবার ছেলে হিসেবে আমাদের সবচেয়ে ভালো ছেলে হবার কথা বলেছিলাম... ...একজন মানুষের জীবন রক্ষা করতে যে একটা ছেলেকে একটা জামা দিয়ে হারিয়ে গেছে, সে তার কাছে প্রার্থনা করেছে, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি সেই ছেলের জন্য। তাকে চুমু দিয়ে পার করার জন্য আমার সবচেয়ে ভালোটা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي نَجِيحٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَعَلَ ‏ ‏الرُّقْبَى ‏ ‏لِلَّذِي ‏ ‏أُرْقِبَهَا ‏ ‏وَالْعُمْرَى ‏ ‏لِلَّذِي ‏ ‏أُعْمِرَهَا ‏","","",""],[20659,20659,"","আমরা সেরাদের ব্যাপারে কথা বলেছি, আমাদের বলা হয়েছে, লর্ডের কথা শুনেছি। সিদ্ধান্ত নিলাম, লর্ডের দয়াটা হতে পারতো। আর এটা করতে হবে... ...আর পৃথিবীর রাজার কাছে তৈরি হওয়া প্রলোভনের মধ্যে পড়তে হবে। জানতে জিজ্ঞাসা","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ أَبِي مُلَيْكَةَ ‏ ‏يُحَدِّثُ يَقُولُ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏مَرْوَانَ ‏ ‏أَخْبَرَهُ قَالَ ‏ ‏قَالَ لِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏مَا لَكَ ‏ ‏تَقْرَأُ فِي الْمَغْرِبِ ‏ ‏بِقِصَارِ ‏ ‏الْمُفَصَّلِ ‏ ‏لَقَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي صَلَاةِ الْمَغْرِبِ ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعُرْوَةَ ‏ ‏مَا ‏ ‏طُولَى ‏ ‏الطُّولَيَيْنِ ‏ ‏قَالَ ‏ ‏الْأَعْرَافُ ‏","","",""],[20660,20660,"","সেই সময়ে, আমি আমার ভাইয়ের কাছ থেকে যে - সমস্ত তথ্য পেতাম, সেগুলোর মধ্যে একটা ছিল আমার ভাইয়ের কাছ থেকে সবচেয়ে ভাল বই । গুলি করো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ فِي كِتَابِ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْوُضُوءِ مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20661,20661,"","তিনি ঈশ্বরের কাছে প্রার্থনা করতে বলেছিলেন এবং প্রভুর কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏لِلْوَارِثِ ‏","","",""],[20662,20662,"","আমরা সবচেয়ে ভালো কথা বলেছি, তিনি বলেছিলেন আমি একটা পিপপির পুত্র এবং আমি পরামর্শ দিচ্ছি যে আমরা হলামপিপিপিপিপির পুত্র. অথবা আমি তাকে বলি প্রভুর পাথর তাকে বলে যে তিনি একটি ছেলে কে বলবে না, চাঁদ আয়নায় আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏أَنَّ ‏ ‏طَاوُسًا ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏حُجْرًا الْمَدَرِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏فِي الْمِيرَاثِ ‏","","",""],[20663,20663,"","আমরা তাদের সঙ্গে কথা বলেছিলাম, যিনি কাপুরুষ ধর্মের প্রতি সম্মান দেখিয়ে সন্ন্যাসীদের তৈরি করেছিলেন । নিষ্ঠুর.","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏تُرْقِبُوا ‏ ‏فَمَنْ ‏ ‏أَرْقَبَ ‏ ‏فَسَبِيلُ الْمِيرَاثِ ‏","","",""],[20664,20664,"","আমরা ঈশ্বরের দোহাই দিয়ে বলছি আমি কত বার আমার পোশাকের মধ্যে আছি, সে তার জন্য প্রার্থনা করেছে আর তাকে জিজ্ঞেস করেছে যে আমি কি করতে পারি সে কি করছে, আমি চাই সে যেন আমাকে ক্ষমা করে দেয়। আমি চাই, আমি এটা করি। প্রতিশোধপরায়ণ কাজের জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏شِبْلٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ دِينَارٍ ‏ ‏عَنْ ‏ ‏طَاوُسٍ ‏ ‏عَنْ ‏ ‏حُجْرٍ الْمَدَرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَعْمَرَ ‏ ‏عُمْرَى ‏ ‏فَهِيَ لِمُعْمِرِهِ مَحْيَاهُ وَمَمَاتَهُ لَا ‏ ‏تُرْقِبُوا ‏ ‏فَمَنْ ‏ ‏أَرْقَبَ ‏ ‏شَيْئًا فَهُوَ سَبِيلُ الْمِيرَاثِ ‏","","",""],[20665,20665,"","আমরা ভাল খেলাটার সেরা দিক নিয়ে কথা বলেছি, অথবা ভালোর ঈর্ষার কথা বলেছি। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আমার ভাই ও ভাইয়ের লোকেদের কাছে সাক্ষ্য দেবেন । তার মৃত্যু, তাদের সম্পর্কে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏أَوْ غَيْرِهِ ‏ ‏أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏لَمَّا كُتِبَتْ الْمَصَاحِفُ فَقَدْتُ آيَةً كُنْتُ أَسْمَعُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَجَدْتُهَا عِنْدَ ‏ ‏خُزَيْمَةَ الْأَنْصَارِيِّ ‏ { ‏مِنْ الْمُؤْمِنِينَ رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ ‏ ‏إِلَى ‏ ‏تَبْدِيلًا ‏} ‏قَالَ فَكَانَ ‏ ‏خُزَيْمَةُ ‏ ‏يُدْعَى ذَا الشَّهَادَتَيْنِ ‏ ‏أَجَازَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهَادَتَهُ بِشَهَادَةِ رَجُلَيْنِ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَقُتِلَ يَوْمَ ‏ ‏صِفِّينَ ‏ ‏مَعَ ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏","","",""],[20666,20666,"","আমি যেমন বলেছি, আমার মেয়ের ছেলের বাধ্য হতে আমার বাবার দুই বছর পাপ বছর পূর্ণ। আমি এমন কিছু বলতে চাই, যেগুলো আমি বলতে চাই। অত্যাচার করা মানেই মারা যাওয়া। আর আমি তাদের করেছি, আর যদি আমি তোমার মধ্যে থাকি, তাহলে তুমি না। বিশ্বাস করো, আর আমি তোমাকে কখনোই ভুলতে পারবো না যদি তুমি আগুনে না পড় আর ভেতরে না আসো। আমি তাকে তোমার মত করে থাকতে বলে খুশি। এক ক্রমাগত এই প্রবাদে আবদ্ধ থেকে তিনি কখনও তার সঙ্গে কথা বলেননি ।","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏أَبِي سِنَانٍ الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏وَهْبٍ الْحِمْصِيِّ ‏ ‏عَنِ ‏ ‏ابْنِ الدَّيْلَمِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏أُبَيَّ بْنَ كَعْبٍ ‏ ‏فَقُلْتُ لَهُ إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي مِنْ الْقَدَرِ شَيْءٌ فَأُحِبُّ أَنْ تُحَدِّثَنِي بِحَدِيثٍ لَعَلَّ اللَّهَ أَنْ يُذْهِبَ عَنِّي مَا أَجِدُ قَالَ ‏ ‏لَوْ أَنَّ اللَّهَ عَزَّ وَجَلَّ عَذَّبَ أَهْلَ السَّمَوَاتِ وَأَهْلَ الْأَرْضِ عَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ وَلَوْ رَحِمَهُمْ كَانَتْ رَحْمَتُهُ لَهُمْ خَيْرًا مِنْ أَعْمَالِهِمْ وَلَوْ كَانَ ‏ ‏أُحُدٌ ‏ ‏لَكَ ذَهَبًا فَأَنْفَقْتَهُ فِي سَبِيلِ اللَّهِ ثُمَّ لَمْ تُؤْمِنْ بِالْقَدَرِ وَتَعْلَمْ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ مَا تُقُبِّلَ مِنْكَ وَلَوْ مِتَّ عَلَى غَيْرِ ذَلِكَ دَخَلْتَ النَّارَ ‏ ‏وَلَا عَلَيْكَ أَنْ ‏ ‏تَلْقَى أَخِي ‏ ‏عَبْدَ اللَّهِ بْنَ مَسْعُودٍ ‏ ‏فَتَسْأَلَهُ ‏ ‏فَلَقِيَ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏ثُمَّ لَقِيَ ‏ ‏حُذَيْفَةَ بْنَ الْيَمَانِ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ ‏ ‏ثُمَّ لَقِيَ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏فَقَالَ ‏ ‏لَهُ ‏ ‏مِثْلَ ذَلِكَ إِلَّا أَنَّهُ حَدَّثَهُ عَنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[20667,20667,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমি আপনাকে ঈশ্বর ও তাঁর লোকেদের কাছে লিখিত হওয়ার আদেশ দিচ্ছি সে হয়তো লেখা আছে, আমাকে একটা জিনিস করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الرُّكَيْنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ حَسَّانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي تَارِكٌ فِيكُمْ خَلِيفَتَيْنِ كِتَابُ اللَّهِ وَأَهْلُ بَيْتِي وَإِنَّهُمَا لَنْ ‏ ‏يَتَفَرَّقَا حَتَّى يَرِدَا عَلَيَّ الْحَوْضَ جَمِيعًا ‏","","",""],[20668,20668,"","আমরা কয়েক দিন আগে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20669,20669,"","আমি আমার ভাই জেডিকে কি ভাবে বলেছিলাম, ঈশ্বরের এটা করতে হবে আর সে পৃথিবীর কাউকে তার ফিল্টারের মাধ্যমে উদ্ধার করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ عُمَرَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الْعَرِيَّةِ ‏ ‏أَنْ تُؤْخَذَ بِمِثْلِ ‏ ‏خَرْصِهَا ‏ ‏تَمْرًا يَأْكُلُهَا أَهْلُهَا رُطَبًا ‏","","",""],[20670,20670,"","আমরা একটা ছেলের কথা বলেছি যে লর্ডকে জেতার জন্য দৃঢ়প্রতিজ্ঞ ছিল, তাকে শেষকৃত্য শেষ করতে হবে আর তার আত্মার রাজত্বের অবসান ঘটাতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏نَافِعٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَابَنَةِ ‏ ‏وَالْمُحَاقَلَةِ ‏ ‏إِلَّا أَنَّهُ رَخَّصَ لِأَهْلِ ‏ ‏الْعَرَايَا ‏ ‏أَنْ يَبِيعُوهَا بِمِثْلِ ‏ ‏خَرْصِهَا ‏","","",""],[20671,20671,"","আমরা বাবার সাথে আমার বাবার সাথে সুখী হওয়ার কথা বলেছি, সে বলেছিল ঈশ্বরের দয়া তাকে দেওয়া হয়েছে আর তাকে রাজ্যের বীজের দেয়ালে রাখা হবে। আর প্রায় ফেলে চলে গেল এটা কে জানে। যদি তুমি ওকে ছেড়ে না দাও, তাহলে তার পাপ থেকে তাকে ছেড়ে দাও। যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে, যে হতে পারে সেই ব্যক্তি, যে হতে পারে সেই হতে হবে, যে হবে সেই হবে। হতে পারে যে, যে একজন হবে সেই হতে পারে সেই হতে পারে যে-ই হতে পারে সেই ব্যক্তি যে হতে পারে, সে হতে পারে সেই ব্যক্তি, যে হবে সেই হবে সেই ব্যক্তি, যে হবে সেই হবে সেই ব্যক্তি, যে হবে সেই হবে, যে হবে সেই হবে, যে হবে এক হবে, হতে হবে সেই ব্যক্তি, যে হবে সেই হবে, যে হবে সেই হবে, যে হবে সেই হবে হবে সেই হবে হবে, যে হবে সেই হবে এক হবে, আর সেই হবে সেই ব্যক্তি, যে হবে হবে সেই ব্যক্তি, যে হবে হবে হবে সেই ব্যক্তি, যে হবে হবে হবে, যে হবে হবে হবে হবে হবে, সেই হবে সেই হবে, যে হবে হবে হবে হবে সেই হবে, যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে যে হতে পারে সেই হতে পারে, যে হতে পারে সেই ব্যক্তি, যে হতে পারে সেই হতে পারে। যে হবে সেই হবে যে কিনা হবে সেই হবে যে কিনা হবে সেই হবে যে কিনা হবে সেই হবে যে কিনা, যে কিনা কিনা তখন সে বলবে যে কবরের উপর ঈশ্বরের কাছে যাবে আমরা বলেছিলাম আমরা তার কাছে যাব আর তাকে ছেড়ে দেব.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَنَا ‏ ‏أَبُو مَسْعُودٍ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏مِنْ ‏ ‏حِيطَانِ ‏ ‏الْمَدِينَةِ ‏ ‏فِيهِ ‏ ‏أَقْبُرٌ ‏ ‏وَهُوَ عَلَى بَغْلَتِهِ ‏ ‏فَحَادَتْ ‏ ‏بِهِ وَكَادَتْ أَنْ تُلْقِيَهُ فَقَالَ مَنْ يَعْرِفُ أَصْحَابَ هَذِهِ ‏ ‏الْأَقْبُرِ ‏ ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ قَوْمٌ هَلَكُوا فِي الْجَاهِلِيَّةِ فَقَالَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَدَعَوْتُ اللَّهَ عَزَّ وَجَلَّ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ثُمَّ قَالَ لَنَا تَعَوَّذُوا بِاللَّهِ مِنْ عَذَابِ جَهَنَّمَ قُلْنَا نَعُوذُ بِاللَّهِ مِنْ عَذَابِ جَهَنَّمَ ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏فَقُلْنَا نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ ‏ ‏الْمَسِيحِ الدَّجَّالِ ‏ ‏ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ فَقُلْنَا نَعُوذُ بِاللَّهِ مِنْ عَذَابِ الْقَبْرِ ثُمَّ قَالَ تَعَوَّذُوا بِاللَّهِ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ قُلْنَا نَعُوذُ بِاللَّهِ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ ‏","","",""],[20672,20672,"","আমরা কিছু সময়ের কথা বলেছি যখন আমার মূল্য জয় হওয়ার কথা ছিল। প্রত্যেকটা প্রার্থনা পড়ে যায়, দু’টি সাঁতার কাটা এবং তিনটা ফাইলফিশ, যেমন দুই ফল আর একটা বিড়ালফিশ। নারীত্বের মত নারীত্বের ঘটনা, যেমন নারীত্বের ঘটনা, আপনি এটা করেছেন এবং বেঁচে গেছেন। আমি ভেবেছিলাম, আমি তার জন্য ঈশ্বরের কাছে যাব এবং তিনি তাঁর জন্য ঈশ্বরের কাছে যাবেন। আমাকে বলতে বলল আমি হয়তো তাকে দেখেছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُمِرْنَا أَنْ نُسَبِّحَ فِي ‏ ‏دُبُرِ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ تَكْبِيرَةً قَالَ فَرَأَى رَجُلٌ فِي الْمَنَامِ فَقَالَ أُمِرْتُمْ بِثَلَاثٍ وَثَلَاثِينَ تَسْبِيحَةً وَثَلَاثٍ وَثَلَاثِينَ تَحْمِيدَةً وَأَرْبَعٍ وَثَلَاثِينَ تَكْبِيرَةً فَلَوْ جَعَلْتُمْ فِيهَا التَّهْلِيلَ فَجَعَلْتُمُوهَا خَمْسًا وَعِشْرِينَ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَدْ رَأَيْتُمْ فَافْعَلُوا ‏ ‏أَوْ نَحْوَ ذَلِكَ ‏","","",""],[20673,20673,"","আমি আমার বাবাকে খুব ভালভাবে কাজ করার কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20674,20674,"","আমরা দুই দিন আগে কথা বলেছি, দুই শুয়োরের কথা, তাকে তার আত্মার অনুগ্রহে দেয়া হবে...","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يُصَلَّى إِذَا طَلَعَ قَرْنُ الشَّمْسِ أَوْ غَابَ قَرْنُهَا وَقَالَ إِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ أَوْ مِنْ بَيْنِ قَرْنَيْ شَيْطَانٍ ‏","","",""],[20675,20675,"","আমরা ঈশ্বর সম্পর্কে কথা বলেছি কিন্তু আমার শ্বশুর আব্বা একটা ভালো সময় পেয়েছেন। তিনি শহর জয় করেছেন এবং আমরা তৃতীয়বার জিততে পারব। তিনি ঈশ্বরের প্রার্থনা শুনতে পাবেন এবং তিনি কি বলতে হবে তা বলার জন্য পাপ করবেন। ( যোহন ১৭: ৩) তিনি বলেছিলেন যে, তৃতীয় বাবা - মা রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَدِينَةَ ‏ ‏وَنَحْنُ نَتَبَايَعُ الثِّمَارَ قَبْلَ أَنْ يَبْدُوَ صَلَاحُهَا فَسَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُصُومَةً فَقَالَ مَا هَذَا فَقِيلَ لَهُ هَؤُلَاءِ ابْتَاعُوا الثِّمَارَ يَقُولُونَ أَصَابَنَا ‏ ‏الدُّمَانُ ‏ ‏وَالْقُشَامُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا تَبَايَعُوهَا حَتَّى يَبْدُوَ صَلَاحُهَا ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَقَالَ ‏ ‏الْأُدْمَانُ ‏ ‏وَالْقُشَامُ ‏","","",""],[20676,20676,"","আমরা ঈশ্বর আমাদের সাথে দেখা করতে গিয়ে দুই ছেলের সাথে কথা বলেছি, যারা আমাকে শিকার করতে সাহায্য করার চেষ্টা করেছে। আমি একটা দেয়ালে কাপড় পরবো, আমরা আমাদের সাথে আছি। ঈশ্বর তাঁর কাছে প্রার্থনা করুন এবং তার কাছে আত্মসমর্পণ করুন। শিকারী.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ سَعْدٍ الْخُرَاسَانِيُّ ‏ ‏سَمِعَ ‏ ‏شُرَحْبِيلَ بْنَ سَعْدٍ ‏ ‏يَقُولُ ‏ ‏أَتَانَا ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَنَحْنُ فِي ‏ ‏حَائِطٍ ‏ ‏لَنَا وَمَعَنَا ‏ ‏فِخَاخٌ ‏ ‏نَنْصِبُ بِهَا فَصَاحَ بِنَا وَطَرَدَنَا وَقَالَ أَلَمْ تَعْلَمُوا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ صَيْدَهَا ‏","","",""],[20677,20677,"","আমরা দুটো বিষয় নিয়ে কথা বলেছি যেগুলো আমাদের বাবার সাথে বিয়ের আগে আমরা কিছু লোকের সাথে বিয়ে করতে পারব। আমি এমন একটা নিয়ম করেছি যে, ভাববাদী তার কাছে প্রার্থনা করেছেন এবং তার কাছে প্রার্থনা করেছেন। তাকে উদ্ধার করা হবে এবং সে শপথ করবে যে সে মারা গেছে। আমি এটা শুনে খুশি হলাম যে আমি সাহায্য করছি না। সব কিছুর গৌরব বলতে গেলে আমি তোমার মুখে ভুল করেছি। সে এমনকি বিপথগামী সাক্ষী বলেছিল, \"ঈশ্বর, তিনি কখনো যেতে পারবেন না\" বলেছেন। ঈশ্বর কখনও তার সমস্ত শব্দ বা আকাশের একমাত্র শপথটা পালন করেননি। আমি তাকে পেয়েছি। বিশ্বস্ত ও তারা হল দরিদ্রের মধ্যে সবচেয়ে ভাল । আমার ছেলের কথা গোপনে বলতে গিয়ে বলেছিলেন, একটা ঘোড়া তাকে বাঁধা দিয়েছিল, যে কিনা ঈশ্বরের দোহাইর কারণে পড়ে গিয়েছিল, আর তার নিজের মত ছিল।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏إِنِّي قَاعِدٌ إِلَى جَنْبِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا إِذْ أُوحِيَ إِلَيْهِ قَالَ ‏ ‏وَغَشِيَتْهُ ‏ ‏السَّكِينَةُ ‏ ‏وَوَقَعَ فَخِذُهُ عَلَى فَخِذِي حِينَ ‏ ‏غَشِيَتْهُ ‏ ‏السَّكِينَةُ ‏ ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏فَلَا وَاللَّهِ مَا وَجَدْتُ شَيْئًا قَطُّ أَثْقَلَ مِنْ فَخِذِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَقَالَ اكْتُبْ يَا ‏ ‏زَيْدُ ‏ ‏فَأَخَذْتُ ‏ ‏كَتِفًا ‏ ‏فَقَالَ اكْتُبْ ‏ ‏لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ الْآيَةَ كُلَّهَا إِلَى قَوْلِهِ أَجْرًا عَظِيمًا فَكَتَبْتُ ذَلِكَ فِي ‏ ‏كَتِفٍ ‏ ‏فَقَامَ حِينَ سَمِعَهَا ‏ ‏ابْنُ أُمِّ مَكْتُومٍ ‏ ‏وَكَانَ رَجُلًا أَعْمَى فَقَامَ حِينَ سَمِعَ فَضِيلَةَ الْمُجَاهِدِينَ قَالَ يَا رَسُولَ اللَّهِ فَكَيْفَ بِمَنْ لَا يَسْتَطِيعُ الْجِهَادَ مِمَّنْ هُوَ أَعْمَى وَأَشْبَاهِ ذَلِكَ قَالَ ‏ ‏زَيْدٌ ‏ ‏فَوَاللَّهِ مَا مَضَى كَلَامُهُ أَوْ مَا هُوَ إِلَّا أَنْ قَضَى كَلَامَهُ ‏ ‏غَشِيَتْ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّكِينَةُ ‏ ‏فَوَقَعَتْ فَخِذُهُ عَلَى فَخِذِي فَوَجَدْتُ مِنْ ثِقَلِهَا كَمَا وَجَدْتُ فِي الْمَرَّةِ الْأُولَى ثُمَّ ‏ ‏سُرِّيَ ‏ ‏عَنْهُ فَقَالَ اقْرَأْ فَقَرَأْتُ عَلَيْهِ لَا يَسْتَوِي الْقَاعِدُونَ مِنْ الْمُؤْمِنِينَ وَالْمُجَاهِدُونَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏غَيْرُ ‏ ‏أُولِي ‏ ‏الضَّرَرِ ‏} ‏قَالَ ‏ ‏زَيْدٌ ‏ ‏فَأَلْحَقْتُهَا ‏ ‏فَوَاللَّهِ لَكَأَنِّي أَنْظُرُ إِلَى مُلْحَقِهَا عِنْدَ ‏ ‏صَدْعٍ ‏ ‏كَانَ فِي ‏ ‏الْكَتِفِ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏أَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏قَالَ قَالَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ عَلَى رَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا إِلَى جَنْبِهِ فَذَكَرَ نَحْوَهُ ‏","","",""],[20678,20678,"","আমরা সেই হিংসার বাবার কথা বলেছিলাম, যে কিনা একবার ভালো ছেলেকে ভালবেসেছিল, আমি ঈশ্বরের কাছে প্রার্থনা করব আর তার সব ছেড়ে দেব। ঈশ্বর তোমার এবং তোমার বাবা ও ঈশ্বর তোমার প্রতি দয়া করে কখনো নেই। আমি তোমার জিনিস বের করেছি কিন্তু কখনো হয়নি। আমি প্রার্থনা করেছিলাম, কে করেছে, যে কিনা আমার অভিশাপের জন্য করেছে। তুমি আমাকে বলতে চাচ্ছ আলোতে যোগ দিতে এবং গৌরবকে সতেজ করতে। আমি নিশ্চিত নই যে তুমি আঘাত করবে না, না আমি তোমাকে দোষ দিচ্ছি না, আমি তোমার জন্য পরিকল্পনা করছি, অন্ধকার আর অন্ধকারের প্রতি ঈর্ষা করছি না, আমি প্রতিজ্ঞা করছি, আমি তোমার কাছে প্রতিজ্ঞা করছি, আমি রাজার কাছে সাক্ষ্য দিচ্ছি। তোমার কাছে যে সমস্ত জিনিস আছে সেগুলো নষ্ট হয়ে যাচ্ছে, ঠিক আছে, ঘন্টা হল, আমি নিশ্চিত না যে আপনি বেজমেন্টে এসেছেন আর আমি নিশ্চিত আপনি বিক্রি করছেন আমি তোমাকে বিশ্বাস করি না, তুমি আমাকে ক্ষমা করবে, এই ধূসর উলের সাথে বিয়ে করার কথা বলছি। আমি ঈশ্বরের কাছে এসেছি, সে যেন আমার কাছে ফিরে আসে। আমি তোমার জন্য প্রার্থনা করি। আমি আমার জন্য তোমার কাছে এসেছি। তার মৃত্যুর কারণ হল, তার বাবার হাতে একটা হাত রেখে তার বাবার সাথে বের হয়ে আসা ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ بْنُ حَبِيبِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَن ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَّمَهُ دُعَاءً وَأَمَرَهُ أَنْ يَتَعَاهَدَ بِهِ أَهْلَهُ كُلَّ يَوْمٍ قَالَ قُلْ كُلَّ يَوْمٍ حِينَ تُصْبِحُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ وَمِنْكَ وَبِكَ وَإِلَيْكَ اللَّهُمَّ مَا قُلْتُ مِنْ قَوْلٍ أَوْ ‏ ‏نَذَرْتُ ‏ ‏مِنْ ‏ ‏نَذْرٍ ‏ ‏أَوْ حَلَفْتُ مِنْ حَلِفٍ فَمَشِيئَتُكَ بَيْنَ يَدَيْهِ مَا شِئْتَ كَانَ وَمَا لَمْ تَشَأْ لَمْ يَكُنْ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِكَ إِنَّكَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ اللَّهُمَّ وَمَا صَلَّيْتُ مِنْ صَلَاةٍ فَعَلَى مَنْ صَلَّيْتَ وَمَا لَعَنْتُ مِنْ لَعْنَةٍ فَعَلَى مَنْ لَعَنْتَ إِنَّكَ أَنْتَ ‏ ‏وَلِيِّي ‏ ‏فِي الدُّنْيَا وَالْآخِرَةِ تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ أَسْأَلُكَ اللَّهُمَّ الرِّضَا بَعْدَ الْقَضَاءِ وَبَرْدَ الْعَيْشِ بَعْدَ الْمَمَاتِ وَلَذَّةَ نَظَرٍ إِلَى وَجْهِكَ وَشَوْقًا إِلَى لِقَائِكَ مِنْ غَيْرِ ضَرَّاءَ مُضِرَّةٍ وَلَا ‏ ‏فِتْنَةٍ ‏ ‏مُضِلَّةٍ أَعُوذُ بِكَ اللَّهُمَّ أَنْ أَظْلِمَ أَوْ أُظْلَمَ أَوْ أَعْتَدِيَ أَوْ ‏ ‏يُعْتَدَى عَلَيَّ أَوْ أَكْتَسِبَ خَطِيئَةً مُحْبِطَةً أَوْ ذَنْبًا لَا يُغْفَرُ اللَّهُمَّ ‏ ‏فَاطِرَ ‏ ‏السَّمَوَاتِ وَالْأَرْضِ عَالِمَ الْغَيْبِ وَالشَّهَادَةِ ذَا ‏ ‏الْجَلَالِ ‏ ‏وَالْإِكْرَامِ فَإِنِّي أَعْهَدُ إِلَيْكَ فِي هَذِهِ الْحَيَاةِ الدُّنْيَا وَأُشْهِدُكَ وَكَفَى بِكَ شَهِيدًا أَنِّي أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا أَنْتَ وَحْدَكَ لَا شَرِيكَ لَكَ لَكَ الْمُلْكُ وَلَكَ الْحَمْدُ وَأَنْتَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَشْهَدُ أَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُكَ وَرَسُولُكَ وَأَشْهَدُ أَنَّ وَعْدَكَ حَقٌّ وَلِقَاءَكَ حَقٌّ وَالْجَنَّةَ حَقٌّ وَالسَّاعَةَ آتِيَةٌ لَا ‏ ‏رَيْبَ ‏ ‏فِيهَا وَأَنْتَ تَبْعَثُ مَنْ فِي الْقُبُورِ وَأَشْهَدُ أَنَّكَ إِنْ ‏ ‏تَكِلْنِي ‏ ‏إِلَى نَفْسِي ‏ ‏تَكِلْنِي ‏ ‏إِلَى ‏ ‏ضَيْعَةٍ ‏ ‏وَعَوْرَةٍ وَذَنْبٍ وَخَطِيئَةٍ وَإِنِّي لَا أَثِقُ إِلَّا بِرَحْمَتِكَ فَاغْفِرْ لِي ذَنْبِي كُلَّهُ إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ وَتُبْ عَلَيَّ إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَقْدَمَهُ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏سُلَيْمَانَ بْنِ دَاوُدَ ‏ ‏عَنْ ‏ ‏أَبِي الزِّنَادِ ‏ ‏عَنْ أَبِيهِ عَنْ ‏ ‏خَارِجَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏","","",""],[20679,20679,"","বাবার বাবার ছেলের কথা বলেছিলাম আমার ভালবাসার জন্য চেষ্টা করার জন্য। আমি এংগেজড. আমি এমন কোন লোক পাইনি যে আমাকে নিয়ে যেতে চায়.","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزِّنَادِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ حُنَيْنٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏بِزَيْتٍ ‏ ‏فَسَاوَمْتُهُ ‏ ‏فِيمَنْ ‏ ‏سَاوَمَهُ ‏ ‏مِنْ التُّجَّارِ حَتَّى ‏ ‏ابْتَعْتُهُ ‏ ‏مِنْهُ حَتَّى قَالَ فَقَامَ إِلَيَّ رَجُلٌ فَرَبَّحَنِي فِيهِ حَتَّى أَرْضَانِي قَالَ فَأَخَذْتُ بِيَدِهِ لِأَضْرِبَ عَلَيْهَا فَأَخَذَ رَجُلٌ بِذِرَاعِي مِنْ خَلْفِي فَالْتَفَتُّ إِلَيْهِ فَإِذَا ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فَقَالَ لَا تَبِعْهُ حَيْثُ ابْتَعْتَهُ حَتَّى تَحُوزَهُ إِلَى رَحْلِكَ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَى عَنْ ذَلِكَ فَأَمْسَكْتُ يَدِي ‏","","",""],[20680,20680,"","আমি মনে করি যে, আমার অহংকারের কারণে একটা ছেলে আবদ্ধ হয়ে আছে, তাকে বলে যে, সে একটা ছেলে । যে তার বাবার নাম শুনেছে সে আগুন থেকে আলো বের করে দিবে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏أَنَّ ‏ ‏خَارِجَةَ بْنَ زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏زَيْدَ بْنَ ثَابِتٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَوَضَّئُوا مِمَّا مَسَّتْ النَّارُ ‏","","",""],[20681,20681,"","আমার ছেলেকে সাহায্য করার চেষ্টা করার সময় বাবা খেলার খেলা নিয়ে কথা বলেছিলাম। আমি দুঃখিত যে আমার ক্ষমতাটা আমার নয়, ঈশ্বর আমার বাবার যা আছে তার জন্য যুদ্ধ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏فِي الْأَسْوَاقِ وَمَعِي طَيْرٌ اصْطَدْتُهُ قَالَ فَلَطَمَ قَفَايَ وَأَرْسَلَهُ مِنْ يَدِي وَقَالَ أَمَا عَلِمْتَ يَا عَدُوَّ نَفْسِكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَرَّمَ مَا بَيْنَ ‏ ‏لَابَتَيْهَا ‏","","",""],[20682,20682,"","আমরা কথা বলেছি যে মোশির ছেলে আছে দুই টাকা দিয়ে বিচারক হতে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আত্মসমর্পণ করবেন এবং তিনি খেতে পারবেন না। আপনি চান না যে তিনি খাওয়া ছেড়ে দেন। আপনি কি এটা করতে চান? আমাদের খেয়ে ফেলো তাহলে আমরা প্রার্থনা করে ফেলেছি যে, আমরা যেন এর চেয়ে ভালো থাকি এবং আমরা প্রার্থনা করি।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ ثَابِتٍ ‏ ‏قَالَ ‏ ‏مَرَرْتُ بِنَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَتَسَحَّرُ يَأْكُلُ تَمْرًا فَقَالَ تَعَالَ فَكُلْ فَقُلْتُ إِنِّي أُرِيدُ الصَّوْمَ فَقَالَ وَأَنَا أُرِيدُ مَا تُرِيدُ فَأَكَلْنَا ثُمَّ قُمْنَا إِلَى الصَّلَاةِ ‏ ‏فَكَانَ بَيْنَ مَا أَكَلْنَا وَبَيْنَ أَنْ قُمْنَا إِلَى الصَّلَاةِ قَدْرُ مَا يَقْرَأُ الرَّجُلُ خَمْسِينَ آيَةً ‏","","",""],[20683,20683,"","আমরা দিনের দুই বাচ্চা হয়ে যাব, ঈশ্বর শান্তি চুক্তি করেছেন যে আপনি আর একবার কিনবেন না আর আপনি সেটা না হওয়া পর্যন্ত বিক্রি করবেন না। লর্ডের কাছে প্রার্থনা করার সময়... ...আর সে আমাদের যুদ্ধে আত্মসমর্পণ করতো, অন্ধকার... ...যে অন্ধকারের মধ্যে সে দেবতাদের হাতে ছিল না, তার জন্য অপেক্ষা করতে পারে. যখন তারা মাতাল ছিল.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏أَنْبَأَنَا ‏ ‏سُفْيَانُ بْنُ حُسَينٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ عُمَرَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُبَاعُ ثَمَرَةٌ بِتَمْرَةٍ وَلَا تُبَاعُ ثَمَرَةٌ حَتَّى يَبْدُوَ صَلَاحُهَا قَالَ فَلَقِيَ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏فَقَالَ رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي عَرَايَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْعَرَايَا نَخْلٌ كَانَتْ تُوهَبُ لِلْمَسَاكِينِ فَلَا يَسْتَطِيعُونَ أَنْ يَنْتَظِرُوا بِهَا فَيَبِيعُونَهَا بِمَا شَاءُوا مِنْ ثَمَرِهِ ‏","","",""],[20684,20684,"","আমি তাকে জিজ্ঞেস করার আগে সাক্ষীটি তার হাতে ধরা পড়ে নি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْرُ الشَّهَادَةِ مَا شَهِدَ بِهَا صَاحِبُهَا قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20685,20685,"","আমরা ভালর থেকে ভালোর ব্যাপারে কথা বলেছি, কিন্তু আমার দুর্দশার প্রধান ঈশ্বরের কাছে বলেছেন তার বেঁচে থাকার অধিকার নেই। হাতকড়া।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ الْمَسَاجِدَ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[20686,20686,"","আমরা অনেক খুশি হয়েছি কিন্তু একজন বিশেষ দাসের প্রতিশ্রুতির সাহায্যে আমাকে সাহায্য করতে পেরে আমি ভীত যে আমি প্রভুর মঙ্গলভাবে উৎসাহিত হয়েছি আর তাকে বলা হয়েছে ঈশ্বর তাকে আদেশ দিয়েছেন এবং আপনার বন্ধুদের ও আপনার মুখ থেকে পরিবর্তন হয়ে গিয়েছে । অন্য ষাঁড়দের থেকে যারা পরাজিত হবে তাদের মূল্য কত।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدِ بْنِ حَيَّانَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَشْجَعَ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُوُفِّيَ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَذُكِرَ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏صَلُّوا عَلَى صَاحِبِكُمْ فَتَغَيَّرَ وُجُوهُ النَّاسِ مِنْ ذَلِكَ فَقَالَ إِنَّ صَاحِبَكُمْ ‏ ‏غَلَّ ‏ ‏فِي سَبِيلِ ‏ ‏اللَّهِ ‏ ‏فَفَتَّشْنَا مَتَاعَهُ فَوَجَدْنَا خَرَزًا مِنْ خَرَزِ ‏ ‏يَهُودَ ‏ ‏مَا ‏ ‏يُسَاوِي دِرْهَمَيْنِ ‏","","",""],[20687,20687,"","আমরা তোমার বয়ফ্রেন্ডের জন্য কখনো মূল্য প্রদান করার ব্যাপারে খুশি হয়েছি। খোদা, সে তার লেখা লিখেছে অথবা আমি গ্যাস ভাড়া করেছি... ...যেন সে টাকা হারাতে না পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏عَطَاءٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فَطَّرَ صَائِمًا كَانَ لَهُ ‏ ‏أَوْ كُتِبَ لَهُ ‏ ‏مِثْلُ أَجْرِ الصَّائِمِ مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَجْرِ الصَّائِمِ شَيْئًا وَمَنْ ‏ ‏جَهَّزَ ‏ ‏غَازِيًا ‏ ‏فِي سَبِيلِ اللَّهِ كَانَ لَهُ ‏ ‏أَوْ كُتِبَ لَهُ ‏ ‏مِثْلُ أَجْرِ ‏ ‏الْغَازِي ‏ ‏فِي أَنَّهُ لَا يَنْقُصُ مِنْ أَجْرِ ‏ ‏الْغَازِي ‏ ‏شَيْئًا ‏","","",""],[20688,20688,"","আমরা একটি সুখী ছেলে কথা বলেছি যে আপনাকে একটা স্বামীর উপহার দিয়েছে... ...যে বলেছে সে আপনার বাড়িতে শান্তি পেয়েছে আর তুমি এটা নিয়ে আসবে না.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي بُيُوتِكُمْ وَلَا تَتَّخِذُوهَا قُبُورًا ‏","","",""],[20689,20689,"","আমরা দুই বছর ধরে আমার বাবার প্রতি ঈশ্বরের প্রেম, এক পাপবাদী ছেলের জন্য বাবার প্রতি আমার ভালবাসার কথা বলেছি। আমার পাশে বিশ্বাসঘাতক হওয়ার কারণ হল, ঈশ্বরের প্রতি বিশ্বাস আছে তার শান্তি এবং শান্তির জন্য, বলো মুহামের। আমি তাদের মত কথা বলার চেষ্টা করছি তারা এমনকি ভদ্র নয়.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي لَبِيدٍ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ بْنِ عَبْدِ اللَّهِ بْنِ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏خَلَّادِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏مُرْ أَصْحَابَكَ فَلْيَرْفَعُوا أَصْوَاتَهُمْ بِالتَّلْبِيَةِ فَإِنَّهَا مِنْ شَعَائِرِ الْحَجِّ ‏","","",""],[20690,20690,"","বাবার সবচেয়ে সাম্প্রতিক স্বপ্নের চেয়ে প্রিয় একটা ছেলেকে আমি আমার বাবার কাছে বেশি কথা বলেছি, আমার বাবা আমার একটা ছেলের স্বপ্নের কথা মনে রাখবে, যে আমার ঈশ্বরের প্রেমে খুশি হবে। আমি শুধু জিজ্ঞাসা করতে চাই না যে ঈশ্বর তাকে সাহায্য করতে চান, তারা কখনো ডিকেকে ফোন করবে না, আমার বাবা তার কাছে প্রার্থনা করবে আর তাকে তার কাছে ক্ষমা চাইতে হবে ডেকে আর বললো যে সে প্রার্থনার প্রতি অনুগত।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏صَالِحُ بْنُ كَيْسَانَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَسُبُّوا الدِّيكَ فَإِنَّهُ يَدْعُو إِلَى الصَّلَاةِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ سَبِّ الدِّيكِ وَقَالَ إِنَّهُ يُؤَذِّنُ بِالصَّلَاةِ ‏","","",""],[20691,20691,"","সে বলেছিল, আমার বাবা যখন এত ভয় পেয়ে যেত, তখন আমি তোমার সবচেয়ে ভালো টাকা পড়েছি। আমি ভয় পাচ্ছি, সে আজ রাতে জানতে পারলাম যে, আমি ঈশ্বরের কাছে প্রার্থনা করি যে তিনি তা করবেন। তার ক্ষমতা দুটো পথ অতিক্রম করেছে, তারপর দুটো পথ অতিক্রম করেছে । ঈশ্বরের দিনে তিনবার দশবার... ...আর আমি ঈশ্বরের প্রেম নিয়ে কথা বলেছি যখন আমার বাবা আমার সাথে কথা বলেছিলেন, ঈশ্বর হয়তো একজন যাজক হতে পারেন, যে আমাকে শিকার করতে বলেছিল এবং তোমাকে বলে, তোমার টাকা নিয়ে যেতে হবে। তার বাবা ও ছেলে কখনোই বাবার সঙ্গে কথা বলার সময় কঠিন সময় দেখেনি । তার বাবার জন্য ক্রুশ এবং তিনি কখনোই তার প্রেম এবং তাদের অনুপ্রাণিত অনুপ্রেরণা উল্লেখ করেন নি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّهُ ‏ ‏قَالَ ‏ ‏لَأَرْمُقَنَّ ‏ ‏اللَّيْلَةَ صَلَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَوَسَّدْتُ ‏ ‏عَتَبَتَهُ ‏ ‏أَوْ ‏ ‏فُسْطَاطَهُ ‏ ‏فَصَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ صَلَّى رَكْعَتَيْنِ طَوِيلَتَيْنِ ثُمَّ صَلَّى رَكْعَتَيْنِ وَهُمَا دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ صَلَّى رَكْعَتَيْنِ دُونَ اللَّتَيْنِ قَبْلَهُمَا ثُمَّ ‏ ‏أَوْتَرَ ‏ ‏فَذَلِكَ ثَلَاثَ عَشْرَةَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏و حَدَّثَنَا ‏ ‏مُصْعَبٌ ‏ ‏حَدَّثَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَلَمْ يَذْكُرْ ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏فِي حَدِيثِ ‏ ‏مَالِكٍ ‏ ‏عَنْ أَبِيهِ وَالصَّوَابُ مَا رَوَى ‏ ‏مُصْعَبٌ ‏ ‏عَنْ أَبِيهِ ‏ ‏وَكَذَا ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُوسَى الْأَنْصَارِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَعْنٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ قَيْسِ بْنِ مَخْرَمَةَ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏وَالصَّوَابُ مَا قَالَ ‏ ‏مُصْعَبٌ ‏ ‏ومَعْنٌ ‏ ‏عَنْ أَبِيهِ وَلَمْ يَذْكُرْ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فِيهِ عَنْ أَبِيهِ وَهِمَ فِيهِ ‏","","",""],[20692,20692,"","আমরা সেই বধিরদের কথা বলেছি, যাদের আমরা একটা ভালো স্বপ্ন নিয়ে কথা বলার চেষ্টা করেছি। সুপার-গাস্টরিয়ান যে একটা সংকেত হারিয়েছে আর যে ভুল করতে ইচ্ছুক, সে জিতে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏بُسْرُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ خَالِدٍ الْجُهَنِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ جَهَّزَ ‏ ‏غَازِيًا ‏ ‏فَقَدْ غَزَا وَمَنْ خَلَفَ ‏ ‏غَازِيًا ‏ ‏فِي أَهْلِهِ بِخَيْرٍ فَقَدْ غَزَا ‏","","",""],[20693,20693,"","আমরা আমার প্রভুর কথা বলেছি... ...তার আগে আমাদের কাছে একটা ছেলে কথা বলেছে... ...যে তার কাছে আমাদের কথা বলেছে, সে বলে যে, ঈশ্বর এটা অবিশ্বাস্য করেছে. জানালা থেকে বের হয়ে আয়।","‏ ‏حَدَّثَنَا ‏ ‏رِبْعِيٌّ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَمْنَعُوا ‏ ‏إِمَاءَ ‏ ‏اللَّهِ الْمَسَاجِدَ وَلْيَخْرُجْنَ ‏ ‏تَفِلَاتٍ ‏","","",""],[20694,20694,"","আমার দুই ছেলে একবার একটা ছেলের উপর জোর দিয়ে বলেছিলেন যে, তিনি চলে গিয়েছেন । তিনি আপনাকে সেই সাক্ষ্যের উত্তম বিষয়টা বলতে নিষেধ করেননি, যা তার নিজের ভয়ে বিপথগামী হবে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَمْرَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُخْبِرُكُمْ بِخَيْرِ الشُّهَدَاءِ الَّذِي يَأْتِي بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا أَوْ يُخْبِرُ بِشَهَادَتِهِ قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20695,20695,"","আমি তাদের সঙ্গে কথা বলেছিলাম, তিনি আমাকে ছেড়ে চলে যেতে বলেছিলেন । বলা হয়েছে যে, একজন শিকারী যিনি এই কাজটি করতে পেরে খুশি এবং তা করতে পারেন, প্রার্থনা করার আগে প্রার্থনা করুন।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِبْرَاهِيمَ بْنِ الْحَارِثِ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏زَيْدٌ ‏ ‏يَرُوحُ إِلَى الْمَسْجِدِ وَسِوَاكُهُ عَلَى أُذُنِهِ بِمَوْضِعِ قَلَمِ الْكَاتِبِ مَا تُقَامُ صَلَاةٌ إِلَّا اسْتَاكَ قَبْلَ أَنْ يُصَلِّيَ ‏","","",""],[20696,20696,"","আমাদের বাবার ছেলে সাহায্যের জন্য চলে গেছে, সে তার জন্য প্রার্থনা করছে আর সে শেষ পর্যন্ত হাল ছেড়ে দেবে -a-a-a--Ta-a-a--a---aaa-----aa----aaaaaa------aaaa----------aaaaaaaaaaaaa--------------------aaaaaaaaaaaaaaaaaaaaa-----------------------aaaaaaaaaaaaaaaaaaaaaaaaaaaaaa--------------------------------------T-T-----------T-aaa-------------------------------- -a-a-a-a--a---------------------------------------------------------------------া-া--া-রা-এ","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مَوْلًى لِجُهَيْنَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ ‏ ‏النُّهْبَةِ ‏ ‏وَالْخُلْسَةِ ‏","","",""],[20697,20697,"","আমরা বাবার ছেলের কথা বলেছিলাম যখন তিনি আমার সাথে কথা বলেছিলেন যখন তিনি তাকে খুঁজে পেয়েছিলেন. যখন বাগহা এসেছিল, তখন সে কখনোই তার প্রতিপক্ষের কথা জানতে পারবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنِي ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَن ‏ ‏أَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ ‏ ‏اللُّقَطَةِ ‏ ‏فَقَالَ ‏ ‏عَرِّفْهَا ‏ ‏سَنَةً فَإِنْ جَاءَ ‏ ‏بَاغِيهَا ‏ ‏فَأَدِّهَا إِلَيْهِ وَإِلَّا فَاعْرِفْ ‏ ‏عِفَاصَهَا ‏ ‏وَوِكَاءَهَا ‏ ‏ثُمَّ كُلْهَا فَإِنْ جَاءَ ‏ ‏بَاغِيهَا ‏ ‏فَأَدِّهَا إِلَيْهِ ‏","","",""],[20698,20698,"","আমি আমার বাবার সাথে কথা বলেছি কিন্তু সে আমাকে সাহায্য করবে। আমি আল্লাহ্‌কে বলা হয়েছে, যখন আমি একজন দু:খজনক ব্যক্তি হয়ে গেলাম, আমার বাবা আমার জয়ের সময় চলে গেল। আমার যাজকদের হাতে তিনি বলেছিলেন যে তিনি আগে সাক্ষ্য দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏أُبَيُّ بْنُ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ مُحَمَّدِ بْنِ عَمْرِو بْنِ حَزْمٍ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ عُثْمَانَ بْنِ عَفَّانَ ‏ ‏حَدَّثَنِي ‏ ‏خَارِجَةُ بْنُ زَيْدِ بْنِ ثَابِتٍ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ أَبِي عَمْرَةَ الْأَنْصَارِيُّ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ خَالِدٍ الْجُهَنِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خَيْرُ الشُّهُودِ مَنْ أَدَّى شَهَادَتَهُ قَبْلَ أَنْ يُسْأَلَهَا ‏","","",""],[20699,20699,"","আমরা এক জীবন্ত জীবন্ত জীবন সম্পর্কে কথা বলেছি, আমি আমার সাথে প্রতারণা করার চেষ্টা করেছি। সামি বলেছে, সে বেঁচে আছে এবং আমি তাকে বলতে পারি না যে সে জন্ম নেবে। সে বলেছিল হাঙ্গর আর আমি একটা জগাখিচুড়ি রহস্য আর সে ছিল তার কব্জির একজন। আর আমি আমার আনুগত্যের দ্বারা উৎসাহিত হয়েছি, ঈশ্বরের ঋণ না হওয়া আর তাকে টাকা পাঠাতে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏أَخْبَرَنِي ‏ ‏يَعْقُوبُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ السَّمَّانِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَلَا أَعْلَمُهُ إِلَّا أَنَّهُ قَالَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قُرَيْشٌ ‏ ‏وَالْأَنْصَارُ ‏ ‏وَأَسْلَمُ ‏ ‏وَغِفَارٌ ‏ ‏أَوْ ‏ ‏غِفَارٌ ‏ ‏وَأَسْلَمُ ‏ ‏وَمَنْ كَانَ مِنْ ‏ ‏أَشْجَعَ ‏ ‏وَجُهَيْنَةَ ‏ ‏أَوْ ‏ ‏جُهَيْنَةَ ‏ ‏وَأَشْجَعَ ‏ ‏حُلَفَاءُ ‏ ‏مَوَالِيَّ لَيْسَ لَهُمْ مِنْ دُونِ اللَّهِ وَلَا رَسُولِهِ ‏ ‏مَوْلًى ‏","","",""],[20700,20700,"","আমি আমার উপেক্ষা করে আমার বাবার সঙ্গে বাইবেল অধ্যয়ন করার চেষ্টা করার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ مُسْلِمٍ الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ مَسَّ فَرْجَهُ فَلْيَتَوَضَّأْ ‏","","",""],[20701,20701,"","আমি আমার বাবার কথা বলেছিলাম, আমি আরেকটু বেশি করে চেষ্টা করে যাওয়ার চেষ্টা করছি । আমি প্রতিজ্ঞা করেছিলাম যে, হঠাৎ করে আমি তাকে হারিয়ে ফেলেছি ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُمَارَةُ بْنُ عَبْدِ اللَّهِ بْنِ طُعْمَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَسَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَصْحَابِهِ غَنَمًا لِلضَّحَايَا ‏ ‏فَأَعْطَانِي ‏ ‏عَتُودًا ‏ ‏جَذَعًا ‏ ‏مِنْ الْمَعْزِ قَالَ فَجِئْتُهُ بِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّهُ ‏ ‏جَذَعٌ ‏ ‏قَالَ ضَحِّ بِهِ فَضَحَّيْتُ بِهِ ‏","","",""],[20702,20702,"","আমাদের কথা বলার জন্য বলা হয়েছে আমরা কিভাবে যেতে পারি. আমার ঈশ্বর তাকে আশ্বস্ত করেছেন যে, তাকে আত্মসমর্পণ করতে হবে, যে কিনা ভুলে যাবে না. তার পাপ.","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي الدَّرَاوَرْدِيَّ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى سَجْدَتَيْنِ لَا ‏ ‏يَسْهُو فِيهِمَا غَفَرَ اللَّهُ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ ‏","","",""],[20703,20703,"","আমরা নিশ্চিত হয়েছি যে আমরা একটা ছেলে করেছি আর খুশি বেনের সাথে সমুদ্র পাড়ি দিয়ে যাব। আমার মা বলেছেন যে আমার বাবা আমাকে বলেছেন যে তিনি খুঁজে পেয়েছেন মহামান্য লর্ডশিপের সাথে, তাদের অনেক ঘুমিয়ে আছে।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِلَالٍ ‏ ‏عَنْ ‏ ‏عُمَرَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ حَدَّثَنِي ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَنَّهُ ‏ ‏سَجَدَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِحْدَى عَشْرَةَ سَجْدَةً مِنْهُنَّ ‏ ‏النَّجْمُ ‏","","",""],[20704,20704,"","আমরা আমাদের মন পরিবর্তন করেছি, আমি আবার আমার মনে ফিরে যাব, সে তার ইচ্ছার কথা বলেছে আর সে তোমার বাবা-মাকে আত্মসমর্পণ করেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي زَكَرِيَّا الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّكُمْ تُدْعَوْنَ يَوْمَ الْقِيَامَةِ بِأَسْمَائِكُمْ وَأَسْمَاءِ آبَائِكُمْ فَحَسِّنُوا أَسْمَاءَكُمْ ‏","","",""],[20705,20705,"","আমরা একটা রাজধানী সম্পর্কে কথা বলেছি যে আমার বাবা আমার বাবার কাছ থেকে চলে গেছে, আমার বাবা খুবই নিষ্ঠুর বাবা শয়তানের প্রতি আপনার ভালবাসা জানতে চেয়েছেন। আমার ডান বাবা তাকে বড় করেনি এবং তাকে ঐ কুত্তির পবিত্র পুত্র দ্বারা বড় করেনি.","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ الْغَسَّانِيُّ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مُحَمَّدٍ الثَّقَفِيِّ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُبُّكَ ‏ ‏الشَّيْءَ ‏ ‏يُعْمِي وَيُصِمُّ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَاه ‏ ‏أَبُو الْيَمَانِ ‏ ‏لَمْ يَرْفَعْهُ ‏ ‏وَرَفَعَهُ ‏ ‏الْقُرْقُسَانِيُّ مُحَمَّدُ بْنُ مُصْعَبٍ ‏","","",""],[20706,20706,"","আমরা একজন প্রবীনকে বলেছিলাম যে আমার বাবার সাথে ঘটেছে কিন্তু ঈশ্বর হয়তো আমার বাবার ব্যাপারে জানতে চান।","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏ضَمْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مِنْ ‏ ‏فِقْهِ ‏ ‏الرَّجُلِ رِفْقُهُ فِي مَعِيشَتِهِ ‏","","",""],[20707,20707,"","আমরা মন পরিবর্তন সম্পর্কে কথা বলেছি আমরা ঈশ্বরের প্রেম নিয়ে কথা বলতে পেরে খুশি হব। আমার বাবা বলেছিলেন, প্রভু আমাদের প্রভুর সাথে আছেন। এক মাসের মধ্যে আর হাতে হাত তুলে হাত তুলে, বিনামূল্যের এবং আমরা ঈশ্বরের কাছে প্রার্থনা করতে চাই না যে ঈশ্বর এটা দিয়েছেন আর ঈশ্বর হয়তো ঈশ্বরের সাথে তাঁর ইচ্ছার সম্পর্ক আছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏حَدَّثَنِي ‏ ‏إِسْمَاعِيلُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَإِنَّ أَحَدَنَا لَيَضَعُ يَدَهُ عَلَى رَأْسِهِ مِنْ شِدَّةِ الْحَرِّ ‏ ‏وَمَا مِنَّا صَائِمٌ إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏","","",""],[20708,20708,"","আমরা অনেক বছর ধরে আমার বাবা বা বাবা একজন ভালো মানুষ। তারা আমাকে বলেছে আমার বুকের ভিতরেই হারিয়ে গেছে। আমি বলেছিলাম, আমার হৃদয়টা ভেঙে গেছে। তুমি ঈশ্বরের কাছে প্রার্থনা করেছিলে যেন তিনি তাকে প্রার্থনা করেন, সে বলবে, তুমি যা করবে এবং জিতবে, সে তাই হবে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي ثَابِتٍ ‏ ‏أَنَّ رَجُلًا دَخَلَ مَسْجِدَ ‏ ‏دِمَشْقَ ‏ ‏فَقَالَ اللَّهُمَّ آنِسْ وَحْشَتِي وَارْحَمْ غُرْبَتِي وَارْزُقْنِي جَلِيسًا صَالِحًا فَسَمِعَهُ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَقَالَ لَئِنْ كُنْتَ صَادِقًا لَأَنَا أَسْعَدُ بِمَا قُلْتَ مِنْكَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ { ‏فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ ‏} ‏يَعْنِي الظَّالِمَ ‏ ‏يُؤْخَذُ مِنْهُ فِي مَقَامِهِ ذَلِكَ فَذَلِكَ الْهَمُّ وَالْحَزَنُ ‏ { ‏وَمِنْهُمْ ‏ ‏مُقْتَصِدٌ ‏ } ‏قَالَ يُحَاسَبُ حِسَابًا يَسِيرًا ‏ { ‏وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ‏} ‏قَالَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ ‏","","",""],[20709,20709,"","আমরা এক ছেলের কথা বলেছিলাম, যে বেঁচে থাকার পর বেঁচে থাকবে। আমার বাবা বলেছিলেন আমরা হয়তো ঈশ্বরের অনুগ্রহে অবতীর্ণ হতে পারি। এমনকি, তারও কিছু না। ( গীতসংহিতা ৩৪: ৮) ঈশ্বর হলেন স্বস্তি ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ حَيَّانَ الدِّمَشْقِيِّ ‏ ‏أَخْبَرَتْنِي ‏ ‏أُمُّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فِي الْيَوْمِ الْحَارِّ الشَّدِيدِ الْحَرِّ ‏ ‏حَتَّى إِنَّ الرَّجُلَ لَيَضَعُ يَدَهُ عَلَى رَأْسِهِ فِي شِدَّةِ الْحَرِّ ‏ ‏وَمَا فِي الْقَوْمِ صَائِمٌ إِلَّا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏","","",""],[20710,20710,"","বাবা আমার চেয়ে ভালো কিছু খুঁজে পাওয়ার চেষ্টা করে। সে ঈশ্বরকে জিজ্ঞেস করে, সে কি দেশ দিতে চায়, সে কি কি করতে পারে। এবং সে বলেছে, সে টাকা দিয়ে টাকা আয় করেছে। ( আদিপুস্তক ১: ২৭) এর চেয়ে ভাল করুণা আর নেই ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ حَسَّانَ الْقُرْدُوسِيُّ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ إِعْطَاءِ السُّلْطَانِ قَالَ مَا آتَاكَ اللَّهُ مِنْهُ مِنْ غَيْرِ مَسْأَلَةٍ وَلَا إِشْرَافٍ فَخُذْهُ وَتَمَوَّلْهُ ‏ ‏قَالَ ‏ ‏وَقَالَ ‏ ‏الْحَسَنُ ‏ ‏رَحِمَهُ اللَّهُ ‏ ‏لَا بَأْسَ بِهَا مَا لَمْ تَرْحَلْ إِلَيْهَا أَوْ تَشَرَّفْ لَهَا ‏","","",""],[20711,20711,"","বাবার বিরুদ্ধে কথোপকথনের কথা বলেছিলাম আমরা তার মায়ের রক্ত নিয়ে কথা বলেছিলাম সে বলল তুমি কি বলবে আমি যা জানি তা আমি জানি ( পড়ুন, গীতসংহিতা ১১৯: ৯৭ - ১০০.)","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْهَا يَوْمًا ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مُغْضَبًا فَقَالَتْ مَا لَكَ قَالَ وَاللَّهِ ‏ ‏مَا أَعْرِفُ فِيهِمْ شَيْئًا مِنْ أَمْرِ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا أَنَّهُمْ يُصَلُّونَ جَمِيعًا ‏","","",""],[20712,20712,"","আমি যখন সেখানে পৌঁছাই, তখন আমার বাবা আমাকে একটা ছোট্ট ঘরের মধ্যে লুকিয়ে রাখার জন্য ঈশ্বরের কাছে প্রার্থনা করেছিলেন । আমি তাকে আর তাকে তোমার ভ্রান্ত ইচ্ছার জন্য জিজ্ঞেস করবো... ...আমি তাকে তার আত্মার সবচেয়ে ভালো হতে আদেশ দিয়েছি.","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏أَوْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏ ‏قَالَ ‏ ‏فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏فِي ‏ ‏مَسْجِدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ ‏ ‏فَقَالَ ‏ ‏أَنَا صَبَبْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءَهُ ‏","","",""],[20713,20713,"","আমরা আনন্দের সাথে কথা বলেছি যে আমার বাবা মুক্ত হতে এসেছিলেন, আমরা ঈশ্বরের মঙ্গলের কথা বলেছি বাবার মুক্তির জন্য বাবার ঘোড়াকে শিকার করতে গিয়ে। কিন্তু, তারা বলেছিল যে ঈশ্বর জয়ী হয়েছেন এবং তিনি জয়ী হয়েছেন । ভালোবাসাটা অনেক ভালো হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏حَدَّثَنِي ‏ ‏مَوْلَى ابْنِ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي بَحْرِيَّةَ ‏ ‏و حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي بَحْرِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ ‏ ‏قَالَ ‏ ‏مَكِّيٌّ ‏ ‏وَأَزْكَاهَا ‏ ‏عِنْدَ مَلِيكِكُمْ وَأَرْفَعِهَا فِي دَرَجَاتِكُمْ وَخَيْرٍ لَكُمْ مِنْ إِعْطَاءِ الذَّهَبِ ‏ ‏وَالْوَرِقِ ‏ ‏وَخَيْرٍ لَكُمْ مِنْ أَنْ تَلْقَوْا عَدُوَّكُمْ فَتَضْرِبُوا أَعْنَاقَهُمْ وَيَضْرِبُوا أَعْنَاقَكُمْ قَالُوا وَذَلِكَ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ ذِكْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[20714,20714,"","আমরা পাঁচ মাসেরও বেশি সময় ধরে কথা বলেছি কিন্তু ঈশ্বরের একজন সর্বশ্রেষ্ঠ গুণ হলো, ভাববাদী তার কাছে প্রার্থনা করেছেন এবং একজন মহিলার একটা দর্শন দিয়েছেন। একদম সাধারণ শপথের দ্বারা মুগ্ধ হয়ে গেছে, নাকি রাবারের ছাপে, ঈশ্বর তাকে বলেছেন, আমি তাকে স্বপ্নের জন্য সর্বোচ্চ চেষ্টা করবো, সে এটা সমাধান করবে না আর সে তার শোক আর শোক ব্যবহার করবে। আমার বাবা এটা সমাধান করবেন না, আমার বাবার কাছে বড় হয়ে ওঠা একজন আধুনিক শিকারী, আমি আপনাকে বলছি আপনি আমাকে কিভাবে ভাল করতে পারেন আমাকে আমার হাত দিয়ে সাহায্য করার জন্য। আমি আপনাকে বলছি, আপনি কি করে কথা বলেন? বাবা শিকারী।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَى امْرَأَةً ‏ ‏مُجِحًّا ‏ ‏عَلَى بَابِ ‏ ‏فُسْطَاطٍ ‏ ‏أَوْ طَرَفِ ‏ ‏فُسْطَاطٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّ صَاحِبَهَا يُلِمُّ بِهَا قَالُوا نَعَمْ قَالَ لَقَدْ هَمَمْتُ أَنْ أَلْعَنَهُ لَعْنَةً تَدْخُلُ مَعَهُ فِي قَبْرِهِ كَيْفَ يُوَرِّثُهُ وَهُوَ لَا يَحِلُّ لَهُ وَكَيْفَ يَسْتَخْدِمُهَا وَهُوَ لَا يَحِلُّ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏زِيَادُ بْنُ أَبِي زِيَادٍ ‏ ‏حَدِيثًا يَرْفَعُهُ إِلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَا أُنَبِّئُكُمْ بِخَيْرِ أَعْمَالِكُمْ فَذَكَرَ الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏وَمَكِّيٍّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ أَبِي زِيَادٍ ‏","","",""],[20715,20715,"","আমরা খুশি যে, আমরা আমার বাবাকে ঋণের জন্য ফিরে পেতে চেষ্টা করে খুশি হয়েছি। আমি তার জন্য প্রার্থনা করেছি এবং বলবো যে, আমি তোমাকে ভালবাসি আমার মনের শেষ নিঃশ্বাস পড়ার জন্য। আমি কি ভাবে আমার মন থেকে খুশি? আমি এটা বলতে চাই যে, আমি আপনাকে ভালোবাসি, আমি আমার মনের শেষ নিঃশ্বাসটি পড়তে। আমি কি করে মন থেকে কিছু জানতে চাই? আমি এটা আমার বাবার কাছে অনেক খুশি। আমি মনে করি, আমি যদি আমার বাবার কাছে ফিরে যাই, আমি আমার বাবার কাছে এটা একটা ছোট ছোট ছোট জিনিস আছে। আমি শুধু একটা জিনিস আছে। আমি যদি আমার বাবার কাছে ফিরে যাই, আমি মনে করি, আমি মনে করি, আমি মনে করি, আমি আমার বাবার কাছে প্রার্থনা করি, আমি যেন আমার জীবনের জন্য এটা একটা সহজ জিনিস। আমি তোমার জন্য একটা জিনিস আছে। আমি তোমার কাছে ঋণী। আমি কি করবো? আমি কি জানি? আমি জানি না? আমি জানি, আমি কি করবো? বল সে বিশ্বাস করতে পারছে না তুমি বলেছিলে সে ভগবান।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيَعْجَبُ أَحَدُكُمْ أَنْ يَقْرَأَ ثُلُثَ الْقُرْآنِ فِي لَيْلَةٍ قَالُوا كَيْفَ يُطِيقُ ذَلِكَ ‏ ‏أَوْ مَنْ يُطِيقُ ذَلِكَ ‏ ‏قَالَ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[20716,20716,"","আমরা দুটো জাহাজের কথা বলেছিলাম যেটা আমার বাবার জন্য ঈশ্বরের দোহাই লাগে। ঈশ্বর তাকে হত্যা করার জন্য প্রার্থনা করেছেন । বন্ধুত্ব।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيَّبِ ‏ ‏عَنْ الضَّبُعِ فَكَرِهَهَا فَقُلْتُ لَهُ إِنَّ قَوْمَكَ يَأْكُلُونَهُ قَالَ لَا يَعْلَمُونَ ‏ ‏فَقَالَ ‏ ‏رَجُلٌ ‏ ‏عِنْدَهُ ‏ ‏سَمِعْتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ كُلِّ ذِي ‏ ‏نُهْبَةٍ ‏ ‏وَكُلِّ ذِي ‏ ‏خَطْفَةٍ ‏ ‏وَكُلِّ ذِي ‏ ‏نَابٍ مِنْ السِّبَاعِ ‏ ‏قَالَ ‏ ‏سَعِيدٌ ‏ ‏صَدَقَ ‏","","",""],[20717,20717,"","আমরা কয়েক বার ওকে গ্রীষ্মের সময় দেওয়ার ব্যাপারে কথা বলেছি। আমি বলেছি, আমরা প্রভুর কাছে গিয়ে বিদায় জানাচ্ছি, বোকা কোথাকার, ওর ভাইয়ের কাছে নিজের রাজার ডাক আছে, সে আমাকে বলেছে কি হয়েছে। আপনি তাকে ভবিষ্যদ্‌বাণীর প্রভাব থেকে প্রভাবিত করবেন এবং তিনি আমাদের সময় দিয়েছেন, কিন্তু তিনি একজন পলাতকের চেয়ে অনেক বেশি. ঈশ্বরের পরে একটি ছেলে উল্লেখ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عَبْدِ اللَّهِ بْنِ صَفْوَانَ ‏ ‏قَالَ ‏ ‏وَكَانَتْ تَحْتَهُ ‏ ‏الدَّرْدَاءُ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏الشَّامَ ‏ ‏فَدَخَلْتُ عَلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏فَلَمْ أَجِدْهُ وَوَجَدْتُ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏فَقَالَتْ تُرِيدُ الْحَجَّ الْعَامَ قَالَ قُلْتُ نَعَمْ فَقَالَتْ فَادْعُ لَنَا بِخَيْرٍ فَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ دَعْوَةَ الْمُسْلِمِ مُسْتَجَابَةٌ لِأَخِيهِ بِظَهْرِ الْغَيْبِ عِنْدَ رَأْسِهِ مَلَكٌ مُوَكَّلٌ كُلَّمَا دَعَا لِأَخِيهِ بِخَيْرٍ قَالَ آمِينَ وَلَكَ بِمِثْلٍ ‏ ‏فَخَرَجْتُ إِلَى السُّوقِ فَأَلْقَى ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقَالَ ‏ ‏لِي ‏ ‏مِثْلَ ذَلِكَ يَأْثُرُهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَيَعْلَى ‏ ‏قَالَا ثَنَا ‏ ‏عَبْدُ الْمَلِكِ ‏ ‏عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏ابْنُ عَبْدِ اللَّهِ ‏ ‏فَذَكَرَهُ ‏","","",""],[20718,20718,"","আমরা আমাদের টাকা নিয়ে কথা বলেছিলাম বাবার মৃত্যুর পরে যে ছেলের বিচার হয়েছে তার ব্যাপারে। আমার বাবা বলেন, আমার বাবা, সম্মানিত একজন মানুষ, একটি প্রতিজ্ঞা করলে তার জন্য অনেক খুশি হবে। আমি যা চাই তা হল, ঈশ্বরের কাছে প্রার্থনা করা এবং তাকে যেতে বলা । যে কেউ তোমাকে নারীসুলভ কাজ করতে শিখিয়েছে... ...যার প্রতিটি কোণই তিন ফুটের সমান.","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ يَعْنِي ابْنَ مِغْوَلٍ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏أَبِي عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏نَزَلَ ‏ ‏بِأَبِي الدَّرْدَاءِ ‏ ‏رَجُلٌ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مُقِيمٌ فَنَسْرَحَ أَمْ ‏ ‏ظَاعِنٌ ‏ ‏فَنَعْلِفَ قَالَ بَلْ ‏ ‏ظَاعِنٌ ‏ ‏قَالَ فَإِنِّي سَأُزَوِّدُكَ زَادًا لَوْ أَجِدُ مَا هُوَ أَفْضَلُ مِنْهُ لَزَوَّدْتُكَ أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ ذَهَبَ الْأَغْنِيَاءُ بِالدُّنْيَا وَالْآخِرَةِ نُصَلِّي وَيُصَلُّونَ وَنَصُومُ وَيَصُومُونَ وَيَتَصَدَّقُونَ وَلَا نَتَصَدَّقُ قَالَ ‏ ‏أَلَا أَدُلُّكَ عَلَى شَيْءٍ إِنْ أَنْتَ فَعَلْتَهُ لَمْ يَسْبِقْكَ أَحَدٌ كَانَ قَبْلَكَ وَلَمْ يُدْرِكْكَ أَحَدٌ بَعْدَكَ إِلَّا مَنْ فَعَلَ الَّذِي تَفْعَلُ ‏ ‏دُبُرَ ‏ ‏كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ تَسْبِيحَةً وَثَلَاثًا وَثَلَاثِينَ تَحْمِيدَةً وَأَرْبَعًا وَثَلَاثِينَ تَكْبِيرَةً ‏","","",""],[20719,20719,"","আমরা কয়েকদিন ধরে আমার খাবারকে ভালোবাসার জন্য নেতৃত্বের জন্য আমার কাছে কিছু সময় করে নিয়েছি। সে আমাকে বলেছে আমার বাবা ছিলেন সেই সম্মানিত। আপনি বলতে পারেন যে আমি ডান-এর একটা গ্রামে ছিলাম। সে বলল, \"আমি আপনাকে এই কথা বলতে চাই\" এবং আমি তাকে যে, \"আমি\" বলতে চাই যে আমি তাকে \"না\" বলে। আর আমি জানি না যে, আমি জানি না। আমি জানি না যে, আমি জানি না। আমি এটা আমার বাবা আমাদের জন্য অনেক ধন্যবাদ। আর আমি যদি আমার বাবা আমাকে বলেছিলাম, আমি শুধু একটা ছোট দলে নেই, তাহলে আমি শুধু একটা ছোট মেয়েও ছিলাম। আর আমি যদি আমার বাবা না-ই তো শুধু একটা ছেলে-মেয়ে। আমি চাই, আমি চাই, আমি চাই, আমি জানি যে, আমি আমার বাবা আমার বাবা আমাকে সাহায্য করে। আমি জানি যে, আমি শুধু একটা ছোট মেয়ে। আর আমি তোমার সাথে নেই। আর আমি যদি আমি চাই, আমি আমার বাবা না যে আমি আমার বাবা আমাকে সাহায্য করে। আমি আমার বাবা আমাকে সাহায্য করে। আমি জানি যে, আমি শুধু একটা ছোট ছিলাম। আর আমি যদি তুমি জানো যে, আমি তোমার সাথে কথা বলে, আমি তোমার বাবা না। আমি আমার বাবা, আমি আমার বাবা। আর আমি আমার বাবা। আর আমি আমার বাবা। আমি যখন আমাকে এই ব্যাপারে আমাকে জিজ্ঞেস করে। আর আমি যখন আমরা যত ত্রাণকর্মী কথা বলেছি, সব বাবাও তো খুশি আমরাও আমাদের সময় জয় করতে পেরেছি সমস্যা সমাধান করার চেষ্টা করছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏زَائِدَةُ بْنُ قُدَامَةَ ‏ ‏حَدَّثَنِي ‏ ‏السَّائِبُ بْنُ حُبَيْشٍ الْكَلَاعِيُّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏لِي ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَيْنَ مَسْكَنُكَ قَالَ قُلْتُ فِي قَرْيَةٍ دُونَ ‏ ‏حِمْصَ ‏ ‏قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ ثَلَاثَةٍ فِي قَرْيَةٍ لَا يُؤَذَّنُ وَلَا تُقَامُ فِيهِمْ الصَّلَاةُ إِلَّا اسْتَحْوَذَ عَلَيْهِمْ الشَّيْطَانُ فَعَلَيْكَ بِالْجَمَاعَةِ فَإِنَّ الذِّئْبَ يَأْكُلُ ‏ ‏الْقَاصِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏أَيْضًا ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏السَّائِبُ بْنُ حُبَيْشٍ الْكَلَاعِيُّ ‏ ‏فَذَكَرَهُ ‏","","",""],[20720,20720,"","আমরা কথা বলেছি, আমার বাবা কিভাবে আমার ভালবাসার সাথে বসবাস করবেন। ভাববাদীর প্রতি শ্রদ্ধা তার জন্য প্রার্থনা করেছেন এবং প্রথমের দশম শব্দটি দিয়েছেন। ঋতুর রক্ত।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَفِظَ عَشْرَ آيَاتٍ مِنْ أَوَّلِ سُورَةِ ‏ ‏الْكَهْفِ ‏ ‏عُصِمَ مِنْ ‏ ‏الدَّجَّالِ ‏","","",""],[20721,20721,"","আমরা বাবার ভালবাসার জন্য খেলতে গিয়ে কথা বলেছি, ঈশ্বর তার পাছা নষ্ট করে দিয়েছে আর দুজন আহত বুট দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏ابْنِ نُعْمَانَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ ‏ ‏جَذَعَيْنِ ‏ ‏مُوجِبَيْنِ ‏","","",""],[20722,20722,"","তিনি ঈশ্বরের কাছে প্রার্থনা করতে বলেছিলেন এবং দুটো বিশেষ শাখাকে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو شِهَابٍ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ نُعْمَانَ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ أَبِي الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ضَحَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِكَبْشَيْنِ ‏ ‏جَذَعَيْنِ ‏ ‏خَصِيَّيْنِ ‏","","",""],[20723,20723,"","আমরা আমাদের থেকে ভাল কথা বলেছি, আমার বাবা, সম্মানিত মানুষ আর সে প্রেমে পড়েছে, বলেছে যে সে তোমার নিজের ছেলের সাথে যা করেছে, তা নিয়ে আমি যা বলছি, সে তার নিজের ছেলের সাথে করেছে। আমি তার কাছে প্রার্থনা করলাম, আর সে বলে কে তোমার পতাকা নিয়ে গেছে। তারা উত্তরাধিকারসূত্রে পাওয়া বিজ্ঞানকে গ্রহণ করে না, বরং দীর্ঘ সময় ধরে নেওয়াকে বেছে নেয় । একজন বাবা হিসেবে জন্ম নেওয়া এক ছেলের বিচার করার সময়","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏أَنَا ‏ ‏عَاصِمُ بْنُ رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏قَدِمَ رَجُلٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏وَهُوَ ‏ ‏بِدِمَشْقَ ‏ ‏فَقَالَ مَا أَقْدَمَكَ أَيْ أَخِي قَالَ حَدِيثٌ بَلَغَنِي أَنَّكَ تُحَدِّثُ بِهِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَمَا قَدِمْتَ لِتِجَارَةٍ قَالَ لَا قَالَ أَمَا قَدِمْتَ لِحَاجَةٍ قَالَ لَا قَالَ مَا قَدِمْتَ إِلَّا فِي طَلَبِ هَذَا الْحَدِيثِ قَالَ نَعَمْ قَالَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ سَلَكَ طَرِيقًا يَطْلُبُ فِيهِ عِلْمًا سَلَكَ اللَّهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ وَإِنَّ الْمَلَائِكَةَ لَتَضَعُ أَجْنِحَتَهَا رِضًا لِطَالِبِ الْعِلْمِ وَإِنَّهُ لَيَسْتَغْفِرُ لِلْعَالِمِ مَنْ فِي السَّمَوَاتِ وَالْأَرْضِ حَتَّى الْحِيتَانُ فِي الْمَاءِ وَفَضْلُ الْعَالِمِ عَلَى الْعَابِدِ كَفَضْلِ الْقَمَرِ عَلَى سَائِرِ الْكَوَاكِبِ إِنَّ الْعُلَمَاءَ هُمْ وَرَثَةُ الْأَنْبِيَاءِ لَمْ يَرِثُوا دِينَارًا وَلَا دِرْهَمًا وَإِنَّمَا وَرِثُوا الْعِلْمَ فَمَنْ أَخَذَهُ أَخَذَ بِحَظٍّ وَافِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ رَجَاءِ بْنِ حَيْوَةَ ‏ ‏عَنْ ‏ ‏دَاوُدَ بْنِ جَمِيلٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏أَقْبَلَ رَجُلٌ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20724,20724,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি... ...আমরা প্রভুর অনুগ্রহের কথা শুনেছি. কিন্তু, যিহোবা তাঁর লোকেদের জন্য যা করেছেন, তা নিয়ে চিন্তা করুন । ( গীত.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ السُّلَمِيَّ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَجُلًا أَمَرَتْهُ أُمُّهُ ‏ ‏أَوْ أَبُوهُ أَوْ كِلَاهُمَا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏يَقُولُ ذَلِكَ ‏ ‏أَنْ يُطَلِّقَ امْرَأَتَهُ فَجَعَلَ عَلَيْهِ مِائَةَ مُحَرَّرٍ فَأَتَى ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَإِذَا هُوَ ‏ ‏يُصَلِّي الضُّحَى يُطِيلُهَا وَصَلَّى مَا بَيْنَ الظُّهْرِ وَالْعَصْرِ فَسَأَلَهُ فَقَالَ لَهُ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏أَوْفِ نَذْرَكَ وَبَرَّ وَالِدَيْكَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْوَالِدُ أَوْسَطُ بَابِ الْجَنَّةِ فَحَافِظْ عَلَى الْوَالِدِ أَوْ اتْرُكْ ‏","","",""],[20725,20725,"","আমরা প্রবল আবেগে বাপ্তাইজিত হয়েছি, বাবার ভালবাসার কথা শুনে, কিন্তু প্রভুর পথে, আমার বাবাকে জিজ্ঞাসা করছি প্রভুর দোহাই, আমি কথা বলি, ঈশ্বরের কাছে। ঈশ্বরের দোহাই, ঈশ্বরের দোহাই, সে তার মৃত্যুকে এভাবে তাড়া করে, যেন সে আমাকে ভালোবাসে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا إِسْحَاقَ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أَبَا حَبِيبَةَ ‏ ‏قَالَ ‏ ‏أَوْصَى رَجُلٌ بِدَنَانِيرَ فِي سَبِيلِ اللَّهِ فَسُئِلَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَحَدَّثَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَثَلُ الَّذِي يُعْتِقُ أَوْ يَتَصَدَّقُ عِنْدَ مَوْتِهِ مَثَلُ الَّذِي يُهْدِي بَعْدَمَا يَشْبَعُ ‏ ‏قَالَ ‏ ‏أَبُو حَبِيبَةَ ‏ ‏فَأَصَابَنِي مِنْ ذَلِكَ شَيْءٌ ‏","","",""],[20726,20726,"","আমি আমার বাবার খাবারের জন্য দু বছর ধরে যে - অপবাদের কথা বলেছি, তার জন্য আমি আমার বাবার সবচেয়ে ভাল ছেলের কথা বলেছিলাম । আমি যা করতে পারতাম, তার মত যে কিনা মৃতদের সাথে ঘুরে বেড়াত, সে লুকিয়ে থাকতে ভয় পায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي حَبِيبَةَ الطَّائِيِّ ‏ ‏قَالَ ‏ ‏أَوْصَى إِلَيَّ أَخِي بِطَائِفَةٍ مِنْ مَالِهِ قَالَ فَلَقِيتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقُلْتُ إِنَّ أَخِي أَوْصَانِي بِطَائِفَةٍ مِنْ مَالِهِ فَأَيْنَ أَضَعُهُ فِي الْفُقَرَاءِ أَوْ فِي الْمُجَاهِدِينَ أَوْ فِي الْمَسَاكِينَ قَالَ أَمَّا أَنَا فَلَوْ كُنْتُ لَمْ أَعْدِلْ بِالْمُجَاهِدِينَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَثَلُ الَّذِي يُعْتِقُ عِنْدَ الْمَوْتِ مَثَلُ الَّذِي يُهْدِي إِذَا شَبِعَ ‏","","",""],[20727,20727,"","আমরা আমার শ্যালকের কথা অনেক কষ্ট করে বলছি। আমি এমন একজন মানুষ যে বলে, \"ঈশ্বর, আমি সবাই জিনিয়াস।\" আমরা বলেছি একজন মানুষ মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَفِي كُلِّ صَلَاةٍ قِرَاءَةٌ قَالَ نَعَمْ فَقَالَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَجَبَتْ هَذِهِ ‏","","",""],[20728,20728,"","ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাঁর জিনতার প্রতি আমি যা করেছি, সেগুলোর মধ্যে রয়েছে, তাঁর জিনগুলোর প্রতি শ্রদ্ধা, যে লোক এই জন ্ য বেঁচে থাকবে সে-ই হবে সাহায ্ য করবে । সেই ব্যক্তি যিনি হলেন সেই ব্যক্তি, যিনি হলেন রাজা । মেয়েরা আমার কথা ভুল শুনতো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏خُلَيْدٍ الْعَصَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا طَلَعَتْ شَمْسٌ قَطُّ إِلَّا بُعِثَ بِجَنْبَتَيْهَا مَلَكَانِ يُنَادِيَانِ يُسْمِعَانِ أَهْلَ الْأَرْضِ إِلَّا ‏ ‏الثَّقَلَيْنِ ‏ ‏يَا أَيُّهَا النَّاسُ هَلُمُّوا إِلَى رَبِّكُمْ فَإِنَّ مَا قَلَّ وَكَفَى خَيْرٌ مِمَّا كَثُرَ وَأَلْهَى وَلَا ‏ ‏آبَتْ ‏ ‏شَمْسٌ قَطُّ إِلَّا بُعِثَ بِجَنْبَتَيْهَا مَلَكَانِ يُنَادِيَانِ يُسْمِعَانِ أَهْلَ الْأَرْضِ إِلَّا ‏ ‏الثَّقَلَيْنِ ‏ ‏اللَّهُمَّ أَعْطِ مُنْفِقًا ‏ ‏خَلَفًا ‏ ‏وَأَعْطِ مُمْسِكًا مَالًا ‏ ‏تَلَفًا ‏","","",""],[20729,20729,"","বাবা ঈশ্বরের কাছে প্রার্থনা করেছিলেন যেন তিনি তাঁর দাসকে সেবা করেন । অস্বাভাবিক.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي حَلْبَسٍ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ فَرَغَ إِلَى كُلِّ عَبْدٍ مِنْ خَلْقِهِ مِنْ خَمْسٍ مِنْ أَجَلِهِ وَعَمَلِهِ وَمَضْجَعِهِ وَأَثَرِهِ وَرِزْقِهِ ‏","","",""],[20730,20730,"","আমরা অতীতে ধূসর মানুষ নিয়ে কথা বলেছি, আমি বাবার রিহার্সাল নিয়ে মা বলতে শুনেছি... ...আমি শুনেছি ভগবানের কাছে প্রার্থনা করেছে, আল্লাহ যেন তা দিয়েছেন আর তাকে উদ্ধার করা হয়। জীবনের শেষ পঞ্চম স্থানে তার প্রতিটি পঞ্চমাংশ আছে এবং তার প্রভাব সুখী।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى الدِّمَشْقِيُّ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ صُبَيْحٍ الْمُرِّيُّ ‏ ‏قَاضِي ‏ ‏الْبَلْقَاءِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تُحَدِّثُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏فَرَغَ اللَّهُ إِلَى كُلِّ عَبْدٍ مِنْ خَمْسٍ مِنْ أَجَلِهِ وَرِزْقِهِ وَأَثَرِهِ وَشَقِيٍّ أَمْ سَعِيدٍ ‏","","",""],[20731,20731,"","আমরা যখন সেই টোপটা শুরু করেছিলাম, তখন আমরা সেই টোপ সম্বন্ধে কথা বলেছিলাম । সে ছিল সব কিছু, একজন মানুষকে বাঁচানোর চেষ্টা করছে, মানুষ তাকে বলেনি আমি তাকে কিভাবে বলব আমি ভয় পেয়েছি. ঈশ্বর রক্ত বা সোনার উপর ছেড়ে দিয়েছেন, অগ্নিমানব তাদের পিছু নিয়েছে আর আমাকে আদেশ করছে যে তারা যদি তাকে ধোঁকা দিতে চায়, আমি তার সাথে প্রতারণা করবো না, কিন্তু কখনোই না। আমার বাবার একটা আত্মা হবে, আমি যা শুনেছি তা হলো, ঈশ্বর বলে যে সবকিছু শেষ হয়ে গেছে, সে বলবে আমি কি করতে চাচ্ছি, আমার আনন্দের দিক থেকে, আমি আমার বাবার বিশ্বাস করি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامٍ ‏ ‏حَدَّثَنَا ‏ ‏شَهْرُ بْنُ حَوْشَبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ غَنْمٍ ‏ ‏أَنَّهُ ‏ ‏زَارَ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏بِحِمْصَ ‏ ‏فَمَكَثَ عِنْدَهُ ‏ ‏لَيَالِيَ وَأَمَرَ بِحِمَارِهِ ‏ ‏فَأُوكِفَ ‏ ‏فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏مَا أَرَانِي إِلَّا مُتَّبِعَكَ فَأَمَرَ بِحِمَارِهِ فَأُسْرِجَ فَسَارَا جَمِيعًا عَلَى حِمَارَيْهِمَا فَلَقِيَا رَجُلًا شَهِدَ الْجُمُعَةَ بِالْأَمْسِ عِنْدَ ‏ ‏مُعَاوِيَةَ ‏ ‏بِالْجَابِيَةِ ‏ ‏فَعَرَفَهُمَا الرَّجُلُ وَلَمْ يَعْرِفَاهُ فَأَخْبَرَهُمَا خَبَرَ النَّاسِ ثُمَّ إِنَّ الرَّجُلَ قَالَ وَخَبَرٌ آخَرُ كَرِهْتُ أَنْ أُخْبِرَكُمَا أُرَاكُمَا تَكْرَهَانِهِ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏فَلَعَلَّ ‏ ‏أَبَا ذَرٍّ ‏ ‏نُفِيَ قَالَ نَعَمْ وَاللَّهِ فَاسْتَرْجَعَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏وَصَاحِبُهُ قَرِيبًا مِنْ عَشْرِ مَرَّاتٍ ثُمَّ قَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏ارْتَقِبْهُمْ وَاصْطَبِرْ كَمَا قِيلَ لِأَصْحَابِ النَّاقَةِ اللَّهُمَّ إِنْ كَذَّبُوا ‏ ‏أَبَا ذَرٍّ ‏ ‏فَإِنِّي لَا أُكَذِّبُهُ اللَّهُمَّ وَإِنْ اتَّهَمُوهُ فَإِنِّي لَا أَتَّهِمُهُ اللَّهُمَّ وَإِنْ ‏ ‏اسْتَغَشُّوهُ ‏ ‏فَإِنِّي لَا ‏ ‏أَسْتَغِشُّهُ ‏ ‏فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَأْتَمِنُهُ حِينَ لَا يَأْتَمِنُ أَحَدًا وَيُسِرُّ إِلَيْهِ حِينَ لَا يُسِرُّ إِلَى أَحَدٍ أَمَا وَالَّذِي نَفْسُ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏بِيَدِهِ لَوْ أَنَّ ‏ ‏أَبَا ذَرٍّ ‏ ‏قَطَعَ يَمِينِي مَا أَبْغَضْتُهُ بَعْدَ الَّذِي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أَظَلَّتْ ‏ ‏الْخَضْرَاءُ ‏ ‏وَلَا ‏ ‏أَقَلَّتْ ‏ ‏الْغَبْرَاءُ ‏ ‏مِنْ ذِي لَهْجَةٍ أَصْدَقَ مِنْ ‏ ‏أَبِي ذَرٍّ ‏","","",""],[20732,20732,"","আমরা আমাদের চেয়ে ভাল ছেলেকে খুঁজছি, সে আমাকে হালকা বেলের কথা বলছিল যে আমার বাবা তার শান্তির জন্য ঈশ্বরের কাছে প্রার্থনা করছে। শহরের পাশে অলোমান ওক আছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَرْطَاةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جُبَيْرَ بْنَ نُفَيْرٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فُسْطَاطُ ‏ ‏الْمُسْلِمِينَ يَوْمَ ‏ ‏الْمَلْحَمَةِ ‏ ‏الْغُوطَةُ ‏ ‏إِلَى جَانِبِ مَدِينَةٍ يُقَالُ لَهَا ‏ ‏دِمَشْقُ ‏","","",""],[20733,20733,"","আমরা আমার বাবার সাথে ভবিষ্যৎের সালমেন্স হওয়ার কথা বলেছি। সে বলল আমি আমার চাচা আর আমি তাকে ভালবাসি আর আমি তাকে ছেড়ে দিতে আদেশ করছি, কিন্তু তোমার বাবা আমি তোমাকে বলছি। ঈশ্বরের কাছ থেকে পাওয়া তার প্রার্থনা শুনে তিনি তার কাছে প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الرَّحْمَنِ السُّلَمِيِّ ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَقَالَ إِنَّ امْرَأَتِي بِنْتُ عَمِّي وَأَنَا أُحِبُّهَا وَإِنَّ وَالِدَتِي تَأْمُرُنِي أَنْ أُطَلِّقَهَا فَقَالَ لَا آمُرُكَ أَنْ تُطَلِّقَهَا وَلَا آمُرُكَ أَنْ تَعْصِيَ وَالِدَتَكَ وَلَكِنْ أُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْوَالِدَةَ أَوْسَطُ أَبْوَابِ الْجَنَّةِ فَإِنْ شِئْتَ فَأَمْسِكْ وَإِنْ شِئْتَ فَدَعْ ‏","","",""],[20734,20734,"","আমরা একটা খারাপ ছেলের সাথে কথা বলেছি তার জন্য শাস্তি নিয়ে। বাবার জন্য আমি খুবই দুঃখিত। আমি বলতে চাই যে ঈশ্বরই তার ছেলে আর সে বলবে \"ঈশ্বর\" হল মই। যারা আমাদের হাত থেকে শিকার হয়েছে তারা তাদের ভয় পায় । যারা তাদেরকে প্রান্তরে ভালবাসে এবং যারা সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে সম্পূর্ণভাবে এই শপথটা নিয়ে আমরা হয়তো তার এই প্রশ্নটাকে পুরোপুরি পুরোপুরি পুরোপুরি পুরোপুরি ভুলতে পারি ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنِي ‏ ‏أَنَسُ بْنُ عِيَاضٍ اللَّيْثِيُّ أَبُو ضَمْرَةَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ عَبْدِ اللَّهِ الْأَزْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ وَمِنْهُمْ ‏ ‏مُقْتَصِدٌ ‏ ‏وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ ‏} ‏فَأَمَّا الَّذِينَ سَبَقُوا بِالْخَيْرَاتِ فَأُولَئِكَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَأَمَّا الَّذِينَ اقْتَصَدُوا فَأُولَئِكَ يُحَاسَبُونَ حِسَابًا يَسِيرًا وَأَمَّا الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ فَأُولَئِكَ الَّذِينَ يُحْبَسُونَ فِي طُولِ الْمَحْشَرِ ثُمَّ هُمْ الَّذِينَ تَلَافَاهُمْ اللَّهُ بِرَحْمَتِهِ فَهُمْ الَّذِينَ يَقُولُونَ ‏ { ‏الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنَّا الْحَزَنَ إِنَّ رَبَّنَا لَغَفُورٌ شَكُورٌ ‏ ‏إِلَى قَوْلِهِ ‏ ‏لُغُوبٌ ‏ }","","",""],[20735,20735,"","আমরা একটা Moos ছেলে কথা বলেছি যে আমার সাথে কথা বলেছে কিন্তু আমার ছেলে আমাকে ভালোবাসে। আমার বাবা আমার বাবার পুনঃসমর্পন করছে এই কথা না বলে যে ডঃ স্কুইডের দেহকের দেহ থেকে না বলে আল্লাহকে যেন ডাক, সে বলবে কামনার সাথে কোন লড়াই নয়... ...আর তার অপরাধবোধের সাথে তার অপরাধকে বলা হয় ধ্বংস হয়ে যাওয়া থেকে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ الْجُهَنِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ دَخَلَ عَلَى ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏فَقَالَ بِالصِّحَّةِ لَا بِالْمَرَضِ فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الصُّدَاعَ ‏ ‏وَالْمَلِيلَةَ ‏ ‏لَا تَزَالُ بِالْمُؤْمِنِ وَإِنَّ ذَنْبَهُ مِثْلُ ‏ ‏أُحُدٍ ‏ ‏فَمَا تَدَعُهُ وَعَلَيْهِ مِنْ ذَلِكَ مِثْقَالُ حَبَّةٍ مِنْ ‏ ‏خَرْدَلٍ ‏","","",""],[20736,20736,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি তার জন্য ভাল কিছু করেছেন । আর দুঃখটা শেষ না হওয়া পর্যন্ত তাকে থামাতে এটা তাকে কষ্ট দেয়নি।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيُّ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ اغْتَسَلَ يَوْمَ الْجُمُعَةِ وَلَبِسَ ثِيَابَهُ وَمَسَّ طِيبًا إِنْ كَانَ عِنْدَهُ ثُمَّ مَشَى إِلَى الْجُمُعَةِ وَعَلَيْهِ السَّكِينَةُ وَلَمْ يَتَخَطَّ أَحَدًا وَلَمْ يُؤْذِهِ وَرَكَعَ مَا قُضِيَ لَهُ ثُمَّ انْتَظَرَ حَتَّى يَنْصَرِفَ الْإِمَامُ غُفِرَ لَهُ مَا بَيْنَ الْجُمُعَتَيْنِ ‏","","",""],[20737,20737,"","আমরা বাবার কাছে তার দয়ার কথা বলেছি, আমার বাবার সবচেয়ে ভালো পাপের কথা বলে তাকে এটা বলতে হবে। আমার বাবা তোমাকে ছেড়ে যাবে না যখন আমি ঈশ্বরের কাছে যাবো। তোমার মুখ শুনে মনে হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مَكِّيٌّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏حَرْبِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏جَلَسَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا عَلَى الْمِنْبَرِ فَخَطَبَ النَّاسَ وَتَلَا آيَةً وَإِلَى جَنْبِي ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَقُلْتُ لَهُ يَا ‏ ‏أُبَيُّ ‏ ‏مَتَى أُنْزِلَتْ هَذِهِ الْآيَةُ قَالَ فَأَبَى أَنْ يُكَلِّمَنِي ثُمَّ سَأَلْتُهُ فَأَبَى أَنْ يُكَلِّمَنِي حَتَّى نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي ‏ ‏أُبَيٌّ ‏ ‏مَا لَكَ مِنْ جُمُعَتِكَ إِلَّا مَا ‏ ‏لَغَيْتَ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جِئْتُهُ فَأَخْبَرْتُهُ فَقُلْتُ أَيْ رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تَلَوْتَ آيَةً وَإِلَى جَنْبِي ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏فَسَأَلْتُهُ مَتَى أُنْزِلَتْ هَذِهِ الْآيَةُ فَأَبَى أَنْ يُكَلِّمَنِي حَتَّى إِذَا نَزَلْتَ زَعَمَ ‏ ‏أُبَيٌّ ‏ ‏أَنَّهُ لَيْسَ لِي مِنْ جُمُعَتِي إِلَّا مَا ‏ ‏لَغَيْتُ فَقَالَ صَدَقَ ‏ ‏أُبَيٌّ ‏ ‏فَإِذَا سَمِعْتَ إِمَامَكَ يَتَكَلَّمُ فَأَنْصِتْ حَتَّى يَفْرُغَ ‏","","",""],[20738,20738,"","আমরা আপনাকে ঈশ্বরের পুত্র খুঁজছি, কিন্তু আমি আপনাকে সাহায্য করার চেষ্টা করছি, আমরা আমার বাবার নোংরা কথার মধ্যে থেকে বেরিয়ে এসেছি ঈশ্বর তার কাছে প্রার্থনা করুন যেন সে বলতে পারে, তুমি সাপের সাথে চিৎকার করে কথা বলতে পারো।","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَبْغُونِي ‏ ‏ضُعَفَاءَكُمْ فَإِنَّكُمْ إِنَّمَا تُرْزَقُونَ وَتُنْصَرُونَ بِضُعَفَائِكُمْ ‏","","",""],[20739,20739,"","আমি ভাবছিলাম সূর্য দিয়ে যখন আমি আমার ভালবাসা থেকে নিজেকে রক্ষা করতে পারবো, তখন আমি কিভাবে নিজেকে রক্ষা করতে পারি। তোমার মা... আমি বলছি না যে তুমি বলেছিলে তুমি একাই বলেছিলে যে তুমিই একমাত্র ব্যক্তি যে তুমিই খুন হয়েছে। আমি দেখেছি বা আমি দেখেছি। ঈশ্বরের কাছে প্রার্থনা করুন, তাঁর শান্তি আছে আর যদি সে বিষ না দেয় তাহলে কথা বলুন।","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُمَرَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏يُكَنَّى ‏ ‏أَبَا عَبْدِ الصَّمَدِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُمَّ الدَّرْدَاءِ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏إِذَا حَدَّثَ حَدِيثًا تَبَسَّمَ فَقُلْتُ لَا يَقُولُ النَّاسُ إِنَّكَ أَيْ أَحْمَقُ فَقَالَ مَا رَأَيْتُ ‏ ‏أَوْ ‏ ‏مَا سَمِعْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ حَدِيثًا إِلَّا تَبَسَّمَ ‏","","",""],[20740,20740,"","আমরা আমার ভালবাসা খুঁজে পাওয়ার জন্য একটা মূল্য মুছে ফেলার চেষ্টা করেছি। আমার বাবা হচ্ছেন প্রভু প্রভু, যিনি আমাদেরকে ঈশ্বরের রাজা হতে বলেছেন। লেখকেরা আমার উপর বিশ্বাস করে। আমি এই বিষয়টি নিয়ে কথা বলেছি, আমি যদি আমার ভালোবাসা হারিয়ে ফেলি, তাহলে আমি আমার বাবা, আমার বাবা, আমার বাবা, আমার বাবা, আমি কি এমন কিছু একটা জিনিস বের করতে পারি? আমি কি করি, মাথা, আমার মনে হয় আমাকে তাকে গোপনে অনুসরন করতে হবে, ঐ উলকিগুলোর শিল্প","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏بُسْرُ بْنُ عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو إِدْرِيسَ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَا أَنَا نَائِمٌ إِذْ رَأَيْتُ عَمُودَ الْكِتَابِ احْتُمِلَ مِنْ تَحْتِ رَأْسِي فَظَنَنْتُ أَنَّهُ مَذْهُوبٌ بِهِ فَأَتْبَعْتُهُ بَصَرِي فَعُمِدَ بِهِ إِلَى ‏ ‏الشَّامِ ‏ ‏أَلَا وَإِنَّ الْإِيمَانَ حِينَ تَقَعُ الْفِتَنُ ‏ ‏بِالشَّامِ ‏","","",""],[20741,20741,"","আমরা পাপের পাপের সবচেয়ে ভালো কথা বলেছি, খোদা তাঁর কাছে প্রার্থনা করেছেন আর আমি তোমাদের ক্ষমা করবো।","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ ثَابِتِ بْنِ ثَوْبَانَ ‏ ‏عَنْ ‏ ‏عُمَيْرِ بْنِ هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَذْرَاءِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجِلُّوا اللَّهَ يَغْفِرْ لَكُمْ ‏ ‏قَالَ ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏يَعْنِي أَسْلِمُوا ‏","","",""],[20742,20742,"","আমরা আমার বাবাকে ভালবাসি যখন তার কথায় সাড়া না দিয়ে বাবা শুধু কথা বলবেন না, যদি সে তার ক্ষতির কারণে বিষ প্রয়োগ করে থাকে। বিষের মতো।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُمَرَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ الصَّمَدِ ‏ ‏عَنْ ‏ ‏أُمِّ الدَّرْدَاءِ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏لَا يُحَدِّثُ بِحَدِيثٍ إِلَّا تَبَسَّمَ فِيهِ فَقُلْتُ لَهُ إِنِّي أَخْشَى أَنْ يُحَمِّقَكَ النَّاسُ فَقَالَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُحَدِّثُ بِحَدِيثٍ إِلَّا تَبَسَّمَ ‏","","",""],[20743,20743,"","আমরা সবাই একটা ছেলের সাথে কথা বলেছি আমার বাবার কাছে বিক্রি করার চেষ্টা করার ব্যাপারে। আমার বাবা কখনো কখনো সতের সাথে কথা বলবেন না। আমি তার অনুগ্রহ আর কল্পনার চেয়ে ভাল যে কেউ তাকে অন্য কারো প্রেমে পড়তে দেয় না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَبَّانُ ‏ ‏عَنْ ‏ ‏سَهْلِ بْنِ مُعَاذٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّهُ أَتَاهُ ‏ ‏عَائِدًا ‏ ‏فَقَالَ ‏ ‏أَبُو الدَّرْدَاءِ ‏ ‏لِأَبِي بَعْدَ أَنْ سَلَّمَ عَلَيْهِ بِالصِّحَّةِ لَا بِالْوَجَعِ ثَلَاثَ مَرَّاتٍ يَقُولُ ذَلِكَ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا يَزَالُ الْمَرْءُ الْمُسْلِمُ بِهِ ‏ ‏الْمَلِيلَةُ ‏ ‏وَالصُّدَاعُ وَإِنَّ عَلَيْهِ مِنْ الْخَطَايَا لَأَعْظَمَ مِنْ ‏ ‏أُحُدٍ ‏ ‏حَتَّى يَتْرُكَهُ وَمَا عَلَيْهِ مِنْ الْخَطَايَا مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ ‏","","",""],[20744,20744,"","আমরা একটি ছেলে কথা বলেছি যে আমাদের সাথে কথা বলেছে কিন্তু আমার বাবা ভালো লর্ডকে ভালোবাসে। তিনি বলেছিলেন, ঈশ্বর যেন আমাদের জন্য প্রার্থনা করেন এবং আমি জীবনের ক্ষমতা পাওয়ার জন্য প্রথম অনুমতি পাব আর দুনিয়ার জীবন যা-কিছু আছে সে-সমস ্ ত ত ত ত ্ রণা দিয়েছে , আর জীবন দান করে দেয়ার জন ্ য । জীবন জীবনের প ্ রাচুর ্ যের এবং পরকালের জীবন জীবন দান করে । জীবন জীবনের প ্ রাচুর ্ যের এবং পরকালের জীবন জীবন দান করে । জীবন জীবনের প ্ রাচুর ্ যের এবং পরকালের জীবন জীবন দান করে । জীবন জীবনের প ্ রাচুর ্ যের এবং পরকালের জীবন জীবন দান করে । আমার মা যখন মারা যান, তখন আমি তাকে বলি যে, আমার মা তোমার সঙ্গে কী করেছে । আমি যা চিন্তা করি বা করি, তা খুঁজে বের করার জন্য আমরা কথা বলেছি । তাদের দুঃখ তাদের সাহায্য করবে এবং তাদের বিশ্বাস হয়ত আমাদের সাথে হয়েছে, প্রভু ঈশ্বরের মঙ্গলের জন্য, তিনি পিতা অথবা পিতার দয়া শুনেছেন, তিনি তাদের এই কথা শুনতে দিন। আমাদের প্রথম মনে আছে, কে কালোদের অনুমতি দিয়েছে... ...আর তার সাথে কথা বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ بِالسُّجُودِ يَوْمَ الْقِيَامَةِ وَأَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ أَنْ يَرْفَعَ رَأْسَهُ فَأَنْظُرَ إِلَى بَيْنِ يَدَيَّ فَأَعْرِفَ أُمَّتِي مِنْ بَيْنِ الْأُمَمِ وَمِنْ خَلْفِي مِثْلُ ذَلِكَ وَعَنْ يَمِينِي مِثْلُ ذَلِكَ وَعَنْ شِمَالِي مِثْلُ ذَلِكَ فَقَالَ لَهُ رَجُلٌ يَا رَسُولَ اللَّهِ كَيْفَ تَعْرِفُ أُمَّتَكَ مِنْ بَيْنِ الْأُمَمِ فِيمَا بَيْنَ ‏ ‏نُوحٍ ‏ ‏إِلَى أُمَّتِكَ قَالَ هُمْ ‏ ‏غُرٌّ ‏ ‏مُحَجَّلُونَ ‏ ‏مِنْ أَثَرِ الْوُضُوءِ لَيْسَ أَحَدٌ كَذَلِكَ غَيْرَهُمْ وَأَعْرِفُهُمْ أَنَّهُمْ يُؤْتَوْنَ كُتُبَهُمْ بِأَيْمَانِهِمْ وَأَعْرِفُهُمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ ذُرِّيَّتُهُمْ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏شَكَّ فِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا ذَرٍّ ‏ ‏أَوْ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏فَيَقُولُ ‏ ‏فَأَعْرِفُهُمْ أَنَّ نُورَهُمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ وَبِأَيْمَانِهِمْ ‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ لَهِيعَةَ ‏ ‏حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا ذَرٍّ ‏ ‏أَوْ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏قَالَا ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا أَوَّلُ مَنْ يُؤْذَنُ لَهُ فِي السُّجُودِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[20745,20745,"","আমরা একটি সুখী ছেলেকে লিখতে চেষ্টা করেছি, আমি আমার ছেলেকে ভালোর জন্য সাহায্য করার জন্য একটি ছেলে তৈরি করেছি। আমার বাবা আমার বাবাকে বলেছে যে, ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং আমার মা আমার মাকে দিয়েছেন। মা বলেছিল তারা বই জানত, আমি কালোদের প্রভাব তাদের আলো দ্বারা প্রভাবিত, আমি তাদেরকে তাদের হাতে তুলে দেব।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مِنْ ‏ ‏أَبِي ذَرٍّ ‏ ‏وَأَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي لَأَعْرِفُ أُمَّتِي يَوْمَ الْقِيَامَةِ مِنْ بَيْنِ الْأُمَمِ قَالُوا يَا رَسُولَ اللَّهِ وَكَيْفَ تَعْرِفُ أُمَّتَكَ قَالَ أَعْرِفُهُمْ يُؤْتَوْنَ كُتُبَهُمْ بِأَيْمَانِهِمْ وَأَعْرِفُهُمْ ‏ ‏بِسِيمَاهُمْ ‏ ‏فِي وُجُوهِهِمْ مِنْ أَثَرِ السُّجُودِ وَأَعْرِفُهُمْ بِنُورِهِمْ ‏ ‏يَسْعَى بَيْنَ أَيْدِيهِمْ ‏","","",""],[20746,20746,"","আমি দুঃখিত, কিন্তু দুঃখিত। পাপ ও পাপ থেকে কখনোই ভাল কিছু করা যায় না ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي مَرْيَمَ الْغَسَّانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَحْوَصِ حَكِيمُ بْنُ عُمَيْرٍ ‏ ‏وحَبِيبُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَدَعُ رَجُلٌ مِنْكُمْ أَنْ يَعْمَلَ لِلَّهِ عَزَّ وَجَلَّ أَلْفَ حَسَنَةٍ حِينَ يُصْبِحُ يَقُولُ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ مِائَةَ مَرَّةٍ فَإِنَّهُ أَلْفُ حَسَنَةٍ فَإِنَّهُ لَنْ يَعْمَلَ إِنْ شَاءَ اللَّهُ مِثْلَ ذَلِكَ فِي يَوْمٍ مِنْ الذُّنُوبِ وَيَكُونُ مَا عَمِلَ مِنْ خَيْرٍ سِوَى ذَلِكَ وَافِرًا ‏","","",""],[20747,20747,"","আমি বলেছিলাম, তুমি কিভাবে জীবন ঈশ্বরের দোহাই দিয়ে চলেছো, ঈশ্বরের ভয়েসে কোন সূর্য নেই, ঈশ্বরের নিজের সময় আর তারপর পানি হাতে থাকবে যাওয়ার সময় উজ্জ্বল এবং আলো নিয়ম করার জন্য খুব একটা অন্ধকার নয়। আমি একটা পিন দিয়ে তার চেয়ে ভালো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ عُقْبَةَ ‏ ‏أَخْبَرَنِي ‏ ‏كُرَيْبٌ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ أَخْبِرْنِي كَيْفَ صَنَعْتُمْ عَشِيَّةَ ‏ ‏رَدِفْتَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ جِئْنَا ‏ ‏الشِّعْبَ ‏ ‏الَّذِي ‏ ‏يُنِيخُ ‏ ‏فِيهِ النَّاسُ لِلْمَغْرِبِ ‏ ‏فَأَنَاخَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَاقَتَهُ ثُمَّ ‏ ‏بَالَ مَاءً ‏ ‏قَالَ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ ‏ ‏ثُمَّ دَعَا بِالْوَضُوءِ فَتَوَضَّأَ وُضُوءًا لَيْسَ بِالْبَالِغِ جِدًّا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ الصَّلَاةَ قَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ حَتَّى قَدِمَ ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَأَقَامَ الْمَغْرِبَ ثُمَّ ‏ ‏أَنَاخَ ‏ ‏النَّاسُ فِي مَنَازِلِهِمْ وَلَمْ يَحُلُّوا حَتَّى أَقَامَ الْعِشَاءَ فَصَلَّى ثُمَّ حَلَّ النَّاسُ قَالَ فَقُلْتُ كَيْفَ فَعَلْتُمْ حِينَ أَصْبَحْتُمْ قَالَ ‏ ‏رَدِفَهُ ‏ ‏الْفَضْلُ بْنُ عَبَّاسٍ ‏ ‏وَانْطَلَقْتُ أَنَا فِي ‏ ‏سُبَّاقِ ‏ ‏قُرَيْشٍ ‏ ‏عَلَى رِجْلَيَّ ‏","","",""],[20748,20748,"","আমরা পরের আর ঈশ্বরের শপথটা মুছে ফেলার চেষ্টা করেছিলাম... ...একটা ছেলেও হতে পারে, সে এখনো ঈশ্বরের কাছে প্রার্থনা করবে আর সে বলবে সে হয়ত তার হাত ছিল। মহিলা।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا رِبَا فِيمَا كَانَ يَدًا بِيَدٍ ‏ ‏قَالَ ‏ ‏يَعْنِي إِنَّمَا الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20749,20749,"","আমরা দুই দিন আগে কথা বলেছি, বাবা কিভাবে চেষ্টা করেছে সে সম্পর্কে কথা বলেছি। আমার কাছে একটা নাম আছে যেটা তার নাম আছে আর আমার ঈশ্বর তাকে ফোন করবেন। ফিসফিস করে বলছে যে তার টাকা ছিল, কেন সে দুইজনকে অভিযুক্ত করবে এবং তুমি বড় ভাই হতে শপথ নেবে। তুমি বলতে পার যে মানুষ একই কাজ করে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏حَدَّثَنِي ‏ ‏عَمْرُ بْنُ الْحَكَمِ ‏ ‏عَنْ ‏ ‏مَوْلَى قُدَامَةَ بْنِ مَظْعُونٍ ‏ ‏عَنْ ‏ ‏مَوْلَى أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ انْطَلَقَ مَعَ ‏ ‏أُسَامَةَ ‏ ‏إِلَى ‏ ‏وَادِي الْقُرَى ‏ ‏يَطْلُبُ مَالًا لَهُ وَكَانَ يَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَقَالَ لَهُ ‏ ‏مَوْلَاهُ ‏ ‏لِمَ تَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسِ وَأَنْتَ شَيْخٌ كَبِيرٌ قَدْ رَقَقْتَ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَصُومُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ فَسُئِلَ عَنْ ذَلِكَ فَقَالَ ‏ ‏إِنَّ أَعْمَالَ النَّاسِ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ ‏","","",""],[20750,20750,"","আমরা একজন শিকারীর নাম শুনেছি । তারপর তারা ডুবে গেল, সে আমার বিজয়কে হত্যা করতে পারেনি এবং তোমাকে এটা বলার মাধ্যমে তাকে হত্যা করেনি। আমি তাকে খুন করেছি। সে বলল, ঈশ্বর কখনো নয়। আমি বলেছি, ঈশ্বর কখনো তা বিশ্বাস করবেন না। ওকে বললাম, সে সময় ক্লান্ত হয়ে গেছে, আমি তোমাকে ছেড়ে দিতে চাইনি।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمُ بْنُ بَشِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏أَبِي ظِبْيَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏بَعَثَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْحُرَقَةِ ‏ ‏مِنْ ‏ ‏جُهَيْنَةَ ‏ ‏قَالَ فَصَبَّحْنَاهُمْ فَقَاتَلْنَاهُمْ فَكَانَ مِنْهُمْ رَجُلٌ إِذَا أَقْبَلَ الْقَوْمُ كَانَ مِنْ أَشَدِّهِمْ عَلَيْنَا وَإِذَا ‏ ‏أَدْبَرُوا ‏ ‏كَانَ حَامِيَتَهُمْ قَالَ ‏ ‏فَغَشِيتُهُ ‏ ‏أَنَا وَرَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏قَالَ فَلَمَّا ‏ ‏غَشِينَاهُ ‏ ‏قَالَ لَا إِلَهَ إِلَّا اللَّهُ فَكَفَّ عَنْهُ الْأَنْصَارِيُّ وَقَتَلْتُهُ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏أُسَامَةُ ‏ ‏أَقَتَلْتَهُ بَعْدَمَا قَالَ لَا إِلَهَ إِلَّا اللَّهُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِنَّمَا كَانَ ‏ ‏مُتَعَوِّذًا ‏ ‏مِنْ الْقَتْلِ فَكَرَّرَهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ إِلَّا يَوْمَئِذٍ ‏","","",""],[20751,20751,"","আমরা কথা বলেছি, একজন সহমানবের নামে আমার বাবার মৃত্যুর জন্য আমরা দুজনেই দায়ী। রাস্তা।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَرَكْتُ بَعْدِي فِتْنَةً أَضَرَّ عَلَى أُمَّتِي مِنْ النِّسَاءِ عَلَى الرِّجَالِ ‏","","",""],[20752,20752,"","আমরা ২ মাস ধরে ঐ ফুল নিয়ে কথা বলেছি, আমার কাছে একটা কুড়াল আছে, আর ঈশ্বর আদেশ দিয়েছেন প্রভুর মইর উত্তরাধিকারী না হতে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرِثُ الْمُسْلِمُ الْكَافِرَ وَلَا الْكَافِرُ الْمُسْلِمَ ‏","","",""],[20753,20753,"","আমরা মরুভূমি সম্পর্কে জানতে দুই মাস লেগেছি যে কিনা ঈশ্বরকে রক্ষা করেছে এবং কখনো স্বপ্ন দেখবে না, শহরের মৃত্যু সম্পর্কে।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشْرَفَ عَلَى ‏ ‏أُطُمٍ ‏ ‏مِنْ ‏ ‏آطَامِ ‏ ‏الْمَدِينَةِ ‏ ‏فَقَالَ هَلْ تَرَوْنَ مَا أَرَى ‏ ‏إِنِّي لَأَرَى مَوَاقِعَ ‏ ‏الْفِتَنِ ‏ ‏خِلَالَ بُيُوتِكُمْ كَمَوَاقِعِ ‏ ‏الْقَطْرِ ‏","","",""],[20754,20754,"","আমরা দুটো গল্প বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আমি তাকে উদ্ধার করবো যখন দাঙ্গা শেষ হয়ে গেল. লাইট লাইট লাইটিং, আর আমি বলেছিলাম তোমার মুখ বন্ধ করে দিয়ে প্রার্থনা করবে আর তোমার মুখকে মেরে ফেলবে... ...আর সে বললো বিষটা শেষ হয়েছে। মানে, এটা সব ডিনার।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْدَفَهُ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏فَلَمَّا أَتَى ‏ ‏الشِّعْبَ ‏ ‏نَزَلَ ‏ ‏فَبَالَ ‏ ‏وَلَمْ يَقُلْ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ ‏ ‏فَصَبَبْتُ عَلَيْهِ فَتَوَضَّأَ وُضُوءًا خَفِيفًا فَقُلْتُ الصَّلَاةَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ ثُمَّ أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَصَلَّى الْمَغْرِبَ ثُمَّ حَلُّوا ‏ ‏رِحَالَهُمْ ‏ ‏وَأَعَنْتُهُ ثُمَّ صَلَّى الْعِشَاءَ ‏","","",""],[20755,20755,"","আমরা দুই বছর ধরে চেষ্টা করেছি আমাকে মারতে। এক সময় আমি বলেছিলাম আমি একজন যাজকের ছেলে আটকে ছিলাম। তুমি যা বললে, আমি তা দেখে নেবো। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছে। ঈশ্বরের বইয়ে আমি খুঁজে পাই নি বা তার প্রভুর কাছে শুনেছি। আমি বলছি, ঈশ্বর আমাকে উদ্ধার করার জন্য একজন ভালো প্রভু।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرٌو يَعْنِي ابْنَ دِينَارٍ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا سَعِيدٍ ‏ ‏يَقُولُ الذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ قَالَ فَلَقِيتُ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقُلْتُ أَرَأَيْتَ مَا تَقُولُ أَشَيْئًا وَجَدْتَهُ فِي كِتَابِ اللَّهِ أَوْ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَيْسَ بِشَيْءٍ وَجَدْتُهُ فِي كِتَابِ اللَّهِ أَوْ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنْ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20756,20756,"","আমরা দুই বছর ধরে কথা বলেছি, যে কিনা খাবারে খুশি হবে এমন এক ছেলে যে কিনা খুশি হবে। আমি আপনাকে বলছি, আল্লাহ যেন তার কাছে এই কথা বলেন যে, সে যাবে বা না যাবে। আমার নিজের গোপন বিষয়ের উপর নির্ভর করে... ...আর মাঝে মাঝে কিছু সময় চলে যায়.","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَمْرٍو ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ يَسْأَلُ ‏ ‏سَعْدًا ‏ ‏عَنْ الطَّاعُونِ فَقَالَ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَا أُحَدِّثُكَ عَنْهُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ هَذَا عَذَابٌ أَوْ كَذَا أَرْسَلَهُ اللَّهُ عَلَى نَاسٍ قَبْلَكُمْ ‏ ‏أَوْ طَائِفَةٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَهُوَ يَجِيءُ أَحْيَانًا وَيَذْهَبُ أَحْيَانًا فَإِذَا وَقَعَ بِأَرْضٍ فَلَا تَدْخُلُوا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏","","",""],[20757,20757,"","বাবা যখন আমাকে কেটে ফেলতে চেষ্টা করছিল, আমি আমার কথোপকথনের কথা বলেছিলাম। আমি একটা ছেলেকে ফোন করেছি, প্রভু, যে তুমি আগামীকাল থেকে নামতে যাচ্ছ। এটা সংরক্ষিত নয়, শিকারের ভাগ্য।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي حَفْصَةَ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ أَيْنَ تَنْزِلُ غَدًا إِنْ شَاءَ اللَّهُ وَذَلِكَ زَمَنَ الْفَتْحِ فَقَالَ هَلْ تَرَكَ لَنَا ‏ ‏عَقِيلٌ ‏ ‏مِنْ مَنْزِلٍ ثُمَّ قَالَ ‏ ‏لَا يَرِثُ الْكَافِرُ الْمُؤْمِنَ وَلَا الْمُؤْمِنُ الْكَافِرَ ‏","","",""],[20758,20758,"","আমরা মাহদির ছেলেদের ব্যাপারে কথা বলেছি কিন্তু আমি সাহায্য করার চেষ্টা করছি। একটি হাত বলেছিল যে তিনি ঈশ্বরের কাছে প্রার্থনা করছেন, তিনি যে দিন তার মুক্তির দিনগুলো বহ করবেন, তা তিনি ভুলে যাবেন। আমি বলেছিলাম, প্রভু, তুমি এটা নিয়ে না নেওয়া পর্যন্ত চিন্তাও করোনি । আমি আমার কাজ দিচ্ছি আর আমি নেতা যে তোমাকে মাসখানেক পর থেকে ত্যাগ করতে দেইনি সে খারাপ ছেলে হবে. সে ছিল একজন বিখ্যাত মানুষ যে আমাকে সবচেয়ে ভালো কিছু করতে পারত।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ قَيْسٍ أَبُو غُصْنٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ الْأَيَّامَ ‏ ‏يَسْرُدُ ‏ ‏حَتَّى يُقَالَ لَا يُفْطِرُ وَيُفْطِرُ الْأَيَّامَ حَتَّى لَا يَكَادَ أَنْ يَصُومَ إِلَّا يَوْمَيْنِ مِنْ الْجُمُعَةِ إِنْ كَانَا فِي صِيَامِهِ وَإِلَّا صَامَهُمَا وَلَمْ يَكُنْ يَصُومُ مِنْ شَهْرٍ مِنْ الشُّهُورِ مَا يَصُومُ مِنْ شَعْبَانَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تَصُومُ لَا تَكَادُ أَنْ تُفْطِرَ وَتُفْطِرَ حَتَّى لَا تَكَادَ أَنْ تَصُومَ إِلَّا يَوْمَيْنِ إِنْ دَخَلَا فِي صِيَامِكَ وَإِلَّا صُمْتَهُمَا قَالَ أَيُّ يَوْمَيْنِ قَالَ قُلْتُ يَوْمُ ‏ ‏الِاثْنَيْنِ وَيَوْمُ الْخَمِيسِ قَالَ ‏ ‏ذَانِكَ يَوْمَانِ تُعْرَضُ فِيهِمَا الْأَعْمَالُ عَلَى رَبِّ الْعَالَمِينَ وَأُحِبُّ أَنْ يُعْرَضَ عَمَلِي وَأَنَا صَائِمٌ قَالَ قُلْتُ وَلَمْ أَرَكَ تَصُومُ مِنْ شَهْرٍ مِنْ الشُّهُورِ مَا تَصُومُ مِنْ شَعْبَانَ قَالَ ذَاكَ شَهْرٌ يَغْفُلُ النَّاسُ عَنْهُ بَيْنَ رَجَبٍ وَرَمَضَانَ وَهُوَ شَهْرٌ يُرْفَعُ فِيهِ الْأَعْمَالُ إِلَى رَبِّ الْعَالَمِينَ فَأُحِبُّ أَنْ يُرْفَعَ عَمَلِي وَأَنَا صَائِمٌ ‏","","",""],[20759,20759,"","আমি পার্টির সেরাদের ব্যাপারে কথা বলেছি, আমি একজন যাজকের ছেলেকে বলি আর সে একটা স্নাইপারের ছেলেকে একটা ছেলে দেয়। তিনি যখন বাইরে গিয়েছিলেন, তখন তিনি সেখান থেকে বেরিয়ে গিয়েছিলেন । চুমু দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَطَاءٍ ‏ ‏أَسَمِعْتَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَذَكَرَ قِصَّةً وَلَكِنِّي ‏ ‏سَمِعْتُهُ يَقُولُ أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا دَخَلَ الْبَيْتَ دَعَا فِي نَوَاحِيهِ كُلِّهَا وَلَمْ يُصَلِّ فِيهِ حَتَّى خَرَجَ فَلَمَّا خَرَجَ ‏ ‏رَكَعَ رَكْعَتَيْنِ فِي قِبَلِ ‏ ‏الْكَعْبَةِ ‏ ‏وَقَالَ هَذِهِ الْقِبْلَةُ ‏","","",""],[20760,20760,"","আমরা বাবার চোখের কথা বলেছিলাম যখন সে আমাকে তার ভালবাসার জন্য সাহায্য করতে চেষ্টা করেছিল। কিন্তু তার বাবার একটা হাত, একটা হাত, যে হাত বলেছিল, \"যখন সে ঈশ্বরের কাছে বলেছিল, তখন সে বলল, \"আমি এটা করেছি।\" ভুল করে নাও।\" শহর ভগবানকে উদ্ধার করতে ব্যর্থ হয়েছে। তারপর আমার দোষ। আমি জানি এটা আমার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عُبَيْدِ بْنِ السَّبَّاقِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏لَمَّا ‏ ‏ثَقُلَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَبَطْتُ وَهَبَطَ النَّاسُ مَعِي إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَدَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ أَصْمَتَ فَلَا يَتَكَلَّمُ فَجَعَلَ ‏ ‏يَرْفَعُ يَدَيْهِ إِلَى السَّمَاءِ ثُمَّ يَصُبُّهَا عَلَيَّ أَعْرِفُ أَنَّهُ يَدْعُو لِي ‏","","",""],[20761,20761,"","আমি যে - বাপ্তিস্মের কথা বলেছিলাম, তা এক বছরের জন্য আমাদের এক ছেলের বিষয়ে চিন্তা করেছিল । আর হয়তো কেউ স্পর্শ করতে পারবে না, মানুষ লাইনে আছে, এটা আলোতে নেই।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَنَا ‏ ‏قَيْسُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَةَ ‏ ‏وَرَدِيفُهُ ‏ ‏أُسَامَةُ ‏ ‏فَجَعَلَ ‏ ‏يَكْبَحُ ‏ ‏رَاحِلَتَهُ حَتَّى أَنَّ ‏ ‏ذِفْرَيْهَا ‏ ‏لَتَكَادُ أَنْ تَمَسَّ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَنْ تُصِيبَ ‏ ‏قَادِمَةَ الرَّحْلِ وَهُوَ يَقُولُ يَا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ بِالسَّكِينَةِ ‏ ‏وَالْوَقَارِ ‏ ‏فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ فِي ‏ ‏إِيضَاعِ ‏ ‏الْإِبِلِ ‏","","",""],[20762,20762,"","আমরা এক সেকেন্ড কথা বলেছি আর সে তার পিতার ছেলের জন্য এক বছরের জন্য একটা ছেলেও করেছে, ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি বললেন যে সে হয়ত তার হাত ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏ثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ طَاوُسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا رِبَا فِيمَا كَانَ يَدًا بِيَدٍ ‏","","",""],[20763,20763,"","আমরা একটি সুখী দম্পতি লিখতে চেষ্টা করেছি, বাবার স্মৃতির সাথে বসবাস করেছি, একজন অতিথি যিনি বেঁচে আছেন। তার নামের একটি মুক্তার একজন দু:খজনক ব্যক্তি যিনি ঈশ্বরের সাথে দেখা করেছেন। লর্ডশিপ, আল্লাহ তার শান্তি আছে এবং আমাকে তার হাত তুলে নিতে বলেছেন। আমরা তাকে ফেরত দিয়ে বলছি তিনি তার কাছে প্রার্থনা করেছেন এবং আমি তার কাছে প্রার্থনা করছি। আমি তার মুখের ফুল দেখে খুশি। আমি তার মুখ থেকে হাসির ফুল নিয়ে খুশি। আমি তাকে ফিরিয়ে আনতে চাই। আমি আমার কাছে ফিরে এসেছি। আমি এখন আমি তাকে ফিরিয়ে আনতে চাই, আমি যেন তার হাত গুটিয়ে নেই। আমি আমার মনের মানুষ, আমি আমার মনের কথা বলছি, আমি আমার মনের পানি দিয়ে তার দিকে তাকিয়ে আছি। আমি আমার মনের কথা বলছি, আমি আমার মনের কথা শুনতে থাকা অবস্থায়, আমি তার দিকে তাকিয়েছিলাম। আমি এখন আমি আমার মনের কথা বলছি, আমি যেন আমি আমার মনের কথা বুঝতে পারি। আমি আমার মনের কথা বলছি, আমি আমার মনের কথা বলছি, আমি আমার মনের কথা বলছি, আমি আমার মনের সামনে তার দিকে তাকিয়েই খুশি।","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عَبْدِ اللَّهِ بْنِ أُبَيٍّ ‏ ‏فِي مَرَضِهِ ‏ ‏نَعُودُهُ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ كُنْتُ أَنْهَاكَ عَنْ حُبِّ ‏ ‏يَهُودَ ‏ ‏فَقَالَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَدْ أَبْغَضَهُمْ ‏ ‏أَسْعَدُ بْنُ زُرَارَةَ ‏ ‏فَمَاتَ ‏","","",""],[20764,20764,"","আমরা যাজকদের কথা বলেছিলাম আমার কাছে ফিরে যাওয়ার কথা, খোদা ভুল করেছেন, সে বাড়িতে পৌঁছে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَلِيٍّ أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏الْبَيْتِ ‏","","",""],[20765,20765,"","আমি আমার মেয়েকে আমার মেয়ের কাছে নিয়ে এসেছিলাম, আমি ঈশ্বরের কাছে প্রার্থনা করছিলাম, আর তার বাসাকে তার কাছে পৌছে দিলাম যাতে সে সূর্য জয়ের জন্য সূর্য তৈরি হয়। সে একজন মই হবে। তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করবেন এবং তিনি তার জন্য প্রার্থনা করবেন এবং এই ভুলকে দূর করবেন । আমি যখন অসুস্থ হয়ে পড়ি, তখন আমি আমার পরিবারের সঙ্গে বাইবেল অধ্যয়ন করতে শুরু করি । প্রার্থনা অথবা তোমার মাকে হত্যা করার জন্য, সে উদ্ধার করে, এমনকি উপহাসের শিকার যখন সে তাকে ধাক্কা দিয়ে ফেলে দেয় এবং তার সাথে ছিল অন্ধকার প্রার্থনা এবং সূর্য।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏قَالَ فَلَمَّا وَقَعَتْ الشَّمْسُ دَفْعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا سَمِعَ ‏ ‏حَطْمَةَ ‏ ‏النَّاسِ خَلْفَهُ قَالَ رُوَيْدًا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ السَّكِينَةَ فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ ‏ ‏بِالْإِيضَاعِ ‏ ‏قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏الْتَحَمَ ‏ ‏عَلَيْهِ النَّاسُ ‏ ‏أَعْنَقَ ‏ ‏وَإِذَا وَجَدَ ‏ ‏فُرْجَةً ‏ ‏نَصَّ ‏ ‏حَتَّى مَرَّ ‏ ‏بِالشِّعْبِ ‏ ‏الَّذِي يَزْعُمُ كَثِيرٌ مِنْ النَّاسِ أَنَّهُ صَلَّى فِيهِ فَنَزَلَ بِهِ فَبَالَ ‏ ‏مَا يَقُولُ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ كَمَا يَقُولُونَ ‏ ‏ثُمَّ جِئْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَتَوَضَّأَ ثُمَّ قَالَ قُلْتُ الصَّلَاةَ يَا رَسُولَ اللَّهِ قَالَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا صَلَّى حَتَّى أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَنَزَلَ بِهَا فَجَمَعَ بَيْنَ الصَّلَاتَيْنِ الْمَغْرِبِ وَالْعِشَاءِ الْآخِرَةِ ‏","","",""],[20766,20766,"","আমরা আমার বাবার কথা বলেছিলাম তাকে মারতে। তার শান্তির জন্য এবং তিনি যখন মানুষের প্রতি আচরণ শোনেন তখন আত্মসমর্পণ করবেন যখন তিনি বললেন তিনি তাকে আদেশ করবেন, ঈশ্বরের ইচ্ছা ছিল যে তিনি তা হবেন এবং জিজ্ঞেস করলেন যে তিনি শান্তি চান কিনা। আমি শুধু তার কাছে আত্মসমর্পণ করবো। বের হয়ে একটা মেসেজ খুঁজে বের করে, যাতে সে একই খেলা পার হয়... ...যে সে অনেক লোক ভিতরে আসে। আমি পানির উপর দিয়ে পানির আঘাত করছি, তারপর তার লাশ যুদ্ধ করতে আসে। আর তারপর তিনি বলেন, \"আমি আল্লাহ্‌র নামে শপথ করে বলছি\" তিনি ঈশ্বরের অনুগ্রহে পালিয়েছেন, আর তাঁকে উদ্ধার করা হবে যখন তিনি গৌরবের উচ্চ অংশে পৌঁছলেন। আর শেষ ডিনার।\"","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏فَلَمَّا وَقَعَتْ الشَّمْسُ دَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا سَمِعَ ‏ ‏حَطْمَةَ ‏ ‏النَّاسِ خَلْفَهُ قَالَ رُوَيْدًا أَيُّهَا النَّاسُ ‏ ‏عَلَيْكُمْ السَّكِينَةَ فَإِنَّ ‏ ‏الْبِرَّ ‏ ‏لَيْسَ ‏ ‏بِالْإِيضَاعِ ‏ ‏قَالَ فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ‏ ‏الْتَحَمَ ‏ ‏عَلَيْهِ النَّاسُ ‏ ‏أَعْنَقَ ‏ ‏وَإِذَا وَجَدَ ‏ ‏فُرْجَةً ‏ ‏نَصَّ ‏ ‏حَتَّى مَرَّ ‏ ‏بِالشِّعْبِ ‏ ‏الَّذِي يَزْعُمُ كَثِيرٌ مِنْ النَّاسِ أَنَّهُ صَلَّى فِيهِ فَنَزَلَ بِهِ فَبَالَ ‏ ‏مَا يَقُولُ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ كَمَا يَقُولُونَ ‏ ‏ثُمَّ جِئْتُهُ ‏ ‏بِالْإِدَاوَةِ ‏ ‏فَتَوَضَّأَ ثُمَّ قَالَ قُلْتُ الصَّلَاةَ يَا رَسُولَ اللَّهِ قَالَ فَقَالَ الصَّلَاةُ أَمَامَكَ قَالَ فَرَكِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا صَلَّى حَتَّى أَتَى ‏ ‏الْمُزْدَلِفَةَ ‏ ‏فَنَزَلَ بِهَا فَجَمَعَ بَيْنَ الصَّلَاتَيْنِ الْمَغْرِبِ وَالْعِشَاءِ الْآخِرَةِ ‏","","",""],[20767,20767,"","আমি আমার বাবার ছেলেকে আমার ছেলের জন্য রক্ষার চেষ্টা করা একজন জেডুিয়ানের সঙ্গে কথা বলেছিলাম, তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তাকে বলতে বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَلِيِّ بْنِ أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا رِبًا إِلَّا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20768,20768,"","বাবার স্বপ্ন আমার উপর করুণা দেখানোর জন্য, আমার বাবার এক সুখী সন্তান এবং তার পিতার একজন সাহায্যকারীকে জিজ্ঞাসা করবে, তাকে অবশ্যই এক বিষের বাচ্চার কাছে পৌঁছে দিতে হবে। আমি গোপন বা আমার একটা শ্রেণী যে আগে আগে ছিল, তার জন্য আমি গোপন আছি। আর তুমি তাকে এটা থেকে বের করে দিতে যাচ্ছ, বলে দাও বাবা তার সময় মারা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ الْخُزَاعِيُّ ‏ ‏أَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏وَأَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ بْنِ مَعْمَرٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏مَاذَا سَمِعْتَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الطَّاعُونِ فَقَالَ ‏ ‏أُسَامَةُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏رِجْزٌ ‏ ‏أُرْسِلَ عَلَى طَائِفَةٍ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏أَوْ عَلَى طَائِفَةٍ مِمَّنْ كَانَ قَبْلَكُمْ الشَّكُّ فِي الْحَدِيثِ ‏ ‏فَإِذَا سَمِعْتُمْ بِهِ بِأَرْضٍ فَلَا تَقْدَمُوا عَلَيْهِ وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا فِرَارًا مِنْهُ ‏ ‏قَالَ ‏ ‏أَبُو النَّضْرِ ‏ ‏فِي حَدِيثِهِ لَا يُخْرِجُكُمْ إِلَّا فِرَارًا مِنْهُ ‏","","",""],[20769,20769,"","আমরা এক নির্দিষ্ট ছেলের কথা বলেছিলাম যে বাবা আর ছেলের সাথে কথা বলেছে, বিচারকের একটা ঘোড়ার নাম আছে আর সে তার মুখ বলে যে সে ১০ বছরের ছেলে। আমি শুনেছি লর্ডের কথা। আমি শুনেছি বাবা আর ছেলের কথা। আমি শুনেছি, আমি জানি, আমি জানি, আমি জানি, আমি কি বলছি, আমি জানি, আমি জানি, আমি কি বলছি, আমি জানি, আমি তোমার ছেলে। আমি কি করতে পারি। আমি জানি না, আমি যদি তুমি জানো, আমি তোমার কথা বলি, আমি তোমার বাবা। আমি তোমার সাথে কথা বলি, আমি তোমার ছেলে। আমি যদি আমার ছেলের কথা বলি, আমি এটা একটা ছোট ছেলের নাম জানি। আমি জানি। আমি জানি, আমি কি করতে পারি। আমি জানি না। আমি জানি, আমি যদি আমার ছেলে না, আমি তোমাকে এটা একটা ছেলে না। আমি জানি যে, আমি তোমার ছেলে না। আমি জানি, আমি জানি, আমি কি করবো। তার কাছে প্রার্থনা কর আর আমি বলবো যে খোদা দানবের মত না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمٍ ‏ ‏مَوْلًى ‏ ‏لِبَنِي لَيْثٍ ‏ ‏وَكَانَ قَدِيمًا ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏عَلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَحَكَاهُ ‏ ‏مَرْوَانُ ‏ ‏قَالَ ‏ ‏أَبُو مَعْشَرٍ ‏ ‏وَقَدْ لَقِيَهُمَا جَمِيعًا ‏ ‏فَقَالَ ‏ ‏أُسَامَةُ ‏ ‏يَا ‏ ‏مَرْوَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ ‏ ‏فَاحِشٍ ‏ ‏مُتَفَحِّشٍ ‏","","",""],[20770,20770,"","আমরা বলেছিলাম যে যখন এই গরম হয়েছিল তখন সে তার নাম শুনলো যে... ...একজন দুঃখের ছেলে বলেছে যে ঈশ্বরের অনুগ্রহ সংগ্রহ করতে. আর ডিনারটা নকল. আর তারপর তুমি যদি আমাকে বলতে চাও, আমি তাকে বলতে চাই যে, আমি তোমাকে বলি যে, \"আমি\"","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ الْمُنْكَدِرِ ‏ ‏حَدَّثَهُ أَنَّهُ أَخْبَرَهُ أَنَّهُ حَدَّثَهُ ‏ ‏مَنْ سَمِعَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يَقُولُ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ ‏ ‏بِالْمُزْدَلِفَةِ ‏","","",""],[20771,20771,"","আমরা আমাদের সেরাটার কথা বলেছিলাম, \"ঈশ্বর, কাল আমরা নিচে নেমে যাবো, যদি সে আমাদের মেরে ফেলতে চায়।\" আমার ভয় হচ্ছে যে আমি চুদে গেছি। আমার ছেলের অমানুষিক কারণে তারা বেঁচে যাবে না আর ভুলে যাবে না, সে বলেছিল ফুল আর বালিশদের ভয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَيْنَ نَنْزِلُ غَدًا فِي حَجَّتِهِ قَالَ وَهَلْ تَرَكَ لَنَا ‏ ‏عَقِيلٌ ‏ ‏مَنْزِلًا ثُمَّ قَالَ نَحْنُ نَازِلُونَ غَدًا إِنْ شَاءَ اللَّهُ ‏ ‏بِخَيْفِ ‏ ‏بَنِي كِنَانَةَ ‏ ‏يَعْنِي ‏ ‏الْمُحَصَّبَ ‏ ‏حَيْثُ قَاسَمَتْ ‏ ‏قُرَيْشٌ ‏ ‏عَلَى الْكُفْرِ وَذَلِكَ أَنَّ ‏ ‏بَنِي كِنَانَةَ ‏ ‏حَالَفَتْ ‏ ‏قُرَيْشًا ‏ ‏عَلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنْ لَا ‏ ‏يُنَاكِحُوهُمْ وَلَا يُبَايِعُوهُمْ وَلَا ‏ ‏يُؤْوُهُمْ ‏ ‏ثُمَّ قَالَ عِنْدَ ذَلِكَ ‏ ‏لَا يَرِثُ الْكَافِرُ الْمُسْلِمَ وَلَا الْمُسْلِمُ الْكَافِرَ ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏وَالْخَيْفُ الْوَادِي ‏","","",""],[20772,20772,"","আমরা সবার সাথে কথা বলেছি, ঐ শয়তানের ফুলওয়ালা ছেলে সম্পর্কে। আমার বন্য থ্রেডে রাজত্ব, এই দুই মস্তকের উপরে প্রভু প্রভু ঈশ্বরের উপর বিশ্বাসঘাতকতা করেছেন, আদালত আমার উপর আল্লাহ্‌র প্রচণ্ড আঘাত হানল। বাবা, সে তার ঠান্ডা ভেঙ্গে দিয়েছে আর সে বলেছে না, ঈশ্বর তাকে আদেশ দিয়েছেন, আর সে ব্যর্থ হয়েছে। সে বলেছে, সে আমাদের লড়াইয়ে প্রতারণা করেছে... ...যদি আমরা যেমন বলি সে আমাদের মারতে পারবে না, এমনকি তারা ছেলেকেও মারতে পারবে না তিনি যদি বলেন যে তিনি যা বলেন, তা যদি শোনেন, তাহলে তিনি কখনোই বলবেন না যে, ঈশ্বর কিন্তু আমার বাবা চলে যাবেন । সে তোমাকে নিয়ে গেছে, ঈশ্বর তাই করেছেন, আমরা এমন একটা ছেলে খুঁজে বের করেছি যে আমাকে খুন করতে চাচ্ছে, সে হয়তো তার কথা বলতে পারে না আমি বলছি, একজন ভালো প্রভুর ভালোর মূল্য বাড়াতে... ...যে তাকে আদেশ করেছে... আক্রমণ এবং আমি একটি ভাল শপথ কল করতে চাই, সে এটা উল্লেখ করতে শুরু করে এবং গরমের কথা বলে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ حِمَارًا عَلَيْهِ ‏ ‏إِكَافٌ ‏ ‏تَحْتَهُ قَطِيفَةٌ ‏ ‏فَدَكِيَّةٌ ‏ ‏وَأَرْدَفَ ‏ ‏وَرَاءَهُ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏يَعُودُ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏فِي ‏ ‏بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ ‏ ‏وَذَلِكَ قَبْلَ وَقْعَةِ ‏ ‏بَدْرٍ ‏ ‏حَتَّى مَرَّ بِمَجْلِسٍ فِيهِ أَخْلَاطٌ مِنْ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الْأَوْثَانِ ‏ ‏وَالْيَهُودِ ‏ ‏فِيهِمْ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏وَفِي الْمَجْلِسِ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏فَلَمَّا ‏ ‏غَشِيَتْ ‏ ‏الْمَجْلِسَ ‏ ‏عَجَاجَةُ ‏ ‏الدَّابَّةِ ‏ ‏خَمَّرَ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏أَنْفَهُ بِرِدَائِهِ ثُمَّ قَالَ لَا تُغَبِّرُوا عَلَيْنَا فَسَلَّمَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ وَقَفَ فَنَزَلَ ‏ ‏فَدَعَاهُمْ إِلَى اللَّهِ وَقَرَأَ عَلَيْهِمْ الْقُرْآنَ فَقَالَ لَهُ ‏ ‏عَبْدُ اللَّهِ بْنُ أُبَيٍّ ‏ ‏أَيُّهَا الْمَرْءُ لَا أَحْسَنَ مِنْ هَذَا إِنْ كَانَ مَا تَقُولُ حَقًّا فَلَا ‏ ‏تُؤْذِينَا فِي مَجَالِسِنَا وَارْجِعْ إِلَى ‏ ‏رَحْلِكَ ‏ ‏فَمَنْ جَاءَكَ مِنَّا فَاقْصُصْ عَلَيْهِ قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ رَوَاحَةَ ‏ ‏اغْشَنَا ‏ ‏فِي مَجَالِسِنَا فَإِنَّا نُحِبُّ ذَلِكَ قَالَ ‏ ‏فَاسْتَبَّ ‏ ‏الْمُسْلِمُونَ وَالْمُشْرِكُونَ ‏ ‏وَالْيَهُودُ ‏ ‏حَتَّى هَمُّوا أَنْ ‏ ‏يَتَوَاثَبُوا ‏ ‏فَلَمْ يَزَلْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَفِّضُهُمْ ‏ ‏ثُمَّ رَكِبَ دَابَّتَهُ حَتَّى دَخَلَ عَلَى ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ أَيْ ‏ ‏سَعْدُ ‏ ‏أَلَمْ تَسْمَعْ مَا قَالَ ‏ ‏أَبُو حُبَابٍ يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَيٍّ ‏ ‏قَالَ كَذَا وَكَذَا فَقَالَ اعْفُ عَنْهُ يَا رَسُولَ اللَّهِ وَاصْفَحْ فَوَاللَّهِ لَقَدْ أَعْطَاكَ اللَّهُ الَّذِي أَعْطَاكَ وَلَقَدْ اصْطَلَحَ أَهْلُ هَذِهِ الْبُحَيْرَةِ أَنْ يُتَوِّجُوهُ فَيُعَصِّبُونَهُ بِالْعِصَابَةِ فَلَمَّا رَدَّ اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَهُ شَرِقَ بِذَلِكَ فَذَاكَ فَعَلَ بِهِ مَا رَأَيْتَ فَعَفَا عَنْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏حَدَّثَنِي ‏ ‏عُقَيْلٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ وَلَقَدْ اجْتَمَعَ أَهْلُ هَذِهِ الْبُحَيْرَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏أَنَا ‏ ‏شُعَيْبٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَكِبَ حِمَارًا عَلَى ‏ ‏إِكَافٍ ‏ ‏عَلَيْهِ قَطِيفَةٌ ‏ ‏فَدَكِيَّةٌ ‏ ‏وَأَرْدَفَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏وَرَاءَهُ يَعُودُ ‏ ‏سَعْدَ بْنَ عُبَادَةَ ‏ ‏فِي ‏ ‏بَنِي الْخَزْرَجِ ‏ ‏قَبْلَ وَقْعَةِ ‏ ‏بَدْرٍ ‏ ‏فَذَكَرَهُ وَقَالَ الْبَحْرَةِ ‏","","",""],[20773,20773,"","আমরা বলেছিলাম যে কীভাবে আমরা হারিয়ে গিয়েছি । ঈশ্বর বেঁচে গেছেন, আমি বলতে চাই যে তিনি বলেছিলেন তিনি কখনো এটা বলেননি, না, তোমার আত্মা কখনো আঘাত করে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَيَّاشُ بْنُ عَبَّاسٍ ‏ ‏أَنَّ ‏ ‏أَبَا النَّضْرِ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَامِرِ بْنِ سَعْدِ بْنِ أَبِي وَقَّاصٍ ‏ ‏أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏أَخْبَرَ وَالِدَهُ ‏ ‏سَعْدَ بْنَ مَالِكٍ ‏ ‏قَالَ فَقَالَ لَهُ إِنَّ رَجُلًا جَاءَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي أَعْزِلُ عَنْ امْرَأَتِي قَالَ لِمَ قَالَ شَفَقًا عَلَى وَلَدِهَا ‏ ‏أَوْ عَلَى أَوْلَادِهَا ‏ ‏فَقَالَ إِنْ كَانَ كَذَلِكَ فَلَا مَا ضَارَّ ذَلِكَ ‏ ‏فَارِسَ ‏ ‏وَلَا ‏ ‏الرُّومَ ‏","","",""],[20774,20774,"","ঈশ্বর একটা ভালো ছেলের ছেলে, যার ছেলে ছেলে আছে, তার একটা ভালো স্বপ্ন আছে । আদেশ দেওয়া হয়েছে, আর সে তার আলো রক্ষা করেছে, আমরা হাত থেকে হাত বাড়িয়ে দেওয়ার চেষ্টা করছি, তার জন্য ভাববাদী প্রার্থনা করছিলেন এবং আলো জ্বালাতেন।","‏ ‏حَدَّثَنَا ‏ ‏هَيْثَمٌ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْهَيْثَمِ بْنِ خَارِجَةَ ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُقَيْلٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏لَمَّا نَزَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَعَلَّمَهُ الْوُضُوءَ فَلَمَّا فَرَغَ مِنْ وُضُوئِهِ أَخَذَ حَفْنَةً مِنْ مَاءٍ فَرَشَّ بِهَا نَحْوَ الْفَرْجِ قَالَ فَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرُشُّ بَعْدَ وُضُوئِهِ ‏","","",""],[20775,20775,"","আমি ঈশ্বরের কাছে প্রার্থনা করি যেন তিনি তার হতাশা দূর করে দেন এবং তার হতাশা দূর করে দেন । ৩ জন লোক বলেছে যে সে মারা গেছে, তার কাছে হয়ত অনেক বড় ধরনের কাজ ছিল, যখন ঈশ্বর তাকে আত্মসমর্পণ করতে বললেন সে বলল যে সে আমাকে খুঁজে পায়নি যে আমরা ভেতরে নেই। ( লূক ২২: ২৮) কিন্তু, যিশু যখন মারা গিয়েছিলেন, তখন তিনি তাঁর কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏الْكَآبَةُ ‏ ‏فَسَأَلْتُهُ مَا لَهُ فَقَالَ لَمْ يَأْتِنِي ‏ ‏جِبْرِيلُ ‏ ‏مُنْذُ ثَلَاثٍ قَالَ فَإِذَا ‏ ‏جِرْوُ ‏ ‏كَلْبٍ بَيْنَ بُيُوتِهِ ‏ ‏فَأَمَرَ بِهِ فَقُتِلَ فَبَدَا لَهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَبَهَشَ ‏ ‏إِلَيْهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ رَآهُ فَقَالَ لَمْ تَأْتِنِي فَقَالَ إِنَّا لَا نَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا تَصَاوِيرُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏كُرَيْبٍ ‏ ‏مَوْلَى ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ ‏ ‏كَآبَةٌ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏عُثْمَانَ بْنِ عُمَرَ ‏ ‏إِلَّا أَنَّهُ قَالَ فَلَمْ يَأْتِنِي مُنْذُ ثَلَاثٍ ‏","","",""],[20776,20776,"","আমরা এক বছর, ঈশ্বরের সেরা ছেলে বানাতে যাচ্ছি, কিন্তু তিনি আমাকে বলেছিলেন তিনি ঈশ্বরের কাছে প্রার্থনা করেছেন তিনি আমাকে ভিতরে প্রবেশ করতে এবং তিনি আমার স্বপ্নের মধ্যে ছিলেন ঈশ্বর ওয়াদা করেছেন, তারা তাদের ছেলেদের কবর কেড়ে নিয়েছে, আমাদের জীবনের রহস্য, তিনি বলেছিলেন এবং সে আছে. নিশ্চিত সে একজন বেশ্যার সাথে আছে আর সে তাকে শুটার বলে না।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسُ بْنُ الرَّبِيعِ ‏ ‏حَدَّثَنَا ‏ ‏جَامِعُ بْنُ شَدَّادٍ ‏ ‏عَنْ ‏ ‏كُلْثُومٍ الْخُزَاعِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَدْخِلْ عَلَيَّ أَصْحَابِي فَدَخَلُوا عَلَيْهِ فَكَشَفَ الْقِنَاعَ ثُمَّ قَالَ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏جَامِعٍ ‏ ‏إِلَّا أَنَّهُ قَالَ فَدَخَلُوا عَلَيْهِ وَهُوَ ‏ ‏مُتَقَنِّعٌ ‏ ‏بِبُرْدٍ ‏ ‏لَهُ ‏ ‏مَعَافِرِيٍّ وَلَمْ يَقُلْ ‏ ‏وَالنَّصَارَى ‏","","",""],[20777,20777,"","আমরা একটি আবেগ কথা বলেছি যা আমাদের বিশ্বের রাজধানীর উপর একটি দাঙ্গা ঘটিয়েছে বিশ্বের বিশ্বের বিশ্বের বিশ্বের বিশ্বের বিশ্বের বিশ্বের উপর। তিনি ঈশ্বরের অনুগ্রহ প্রার্থনা করেছেন এবং তার কিছু মেয়েকে তার ছেলে বা মেয়ের উদ্ধার করবেন। সিঁড়ি দিয়ে সে বলে আমি যা করব আর আমি যা করব তা পেয়ে যাব। আর সে তার কাজ কসম করে বলে, আমরা বালক নাকি তার গ্রেসকে সম্মান করি। আমরা শপথ নিয়েছি, এটা পৃথিবীর সবচেয়ে খারাপ জায়গা। আমি কি করবো? আমি জানি, আমি জানি, আমি এটা করতে পারি, আমি কি করব? এবং আমি এটা করতে পারি। এবং আমি যা করব তা হবে, আমি যা করব তা হবে, আমি কি করব? এবং আমি তা হবে, আমি জানি, এবং আমি যা করব তা হবে তা হবে, আমি কি করব? আমি তা হবে, আমি জানি না? আমি জানি না? আমি এটা হবে, এবং আমি জানি না। আমি এটা হবে, আমি জানি না। আমি এটা হবে, আমি জানি না। আমি এটা হবে, আমি এটা হবে, আমি জানি না। এবং আমি এটা হবে না। আমি এটা হবে না। আমি এটা হবে, আমি জানি, আমি এটা হবে আমার জন্য অনেক বড়। তিনি বলেছিলেন যে, তার ওপর তিনি করুণা দেখান, যিনি তার হৃদয়ের মধ্যে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عُثْمَانَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَتْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْضُ بَنَاتِهِ ‏ ‏أَنَّ صَبِيًّا لَهَا ‏ ‏ابْنًا ‏ ‏أَوْ ابْنَةً ‏ ‏قَدْ ‏ ‏احْتُضِرَتْ ‏ ‏فَاشْهَدْنَا قَالَ فَأَرْسَلَ إِلَيْهَا يَقْرَأُ السَّلَامَ وَيَقُولُ ‏ ‏إِنَّ لِلَّهِ مَا أَخَذَ وَمَا أَعْطَى وَكُلُّ شَيْءٍ عِنْدَهُ إِلَى أَجَلٍ مُسَمًّى فَلْتَصْبِرْ وَلْتَحْتَسِبْ فَأَرْسَلَتْ تُقْسِمُ عَلَيْهِ فَقَامَ وَقُمْنَا فَرُفِعَ الصَّبِيُّ إِلَى حِجْرِ ‏ ‏أَوْ فِي حِجْرِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَفْسُهُ ‏ ‏تَقَعْقَعُ ‏ ‏وَفِي الْقَوْمِ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏وَأُبَيٌّ ‏ ‏أَحْسِبُ ‏ ‏فَفَاضَتْ عَيْنَا رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ ‏ ‏سَعْدٌ ‏ ‏مَا هَذَا يَا رَسُولَ اللَّهِ قَالَ هَذِهِ رَحْمَةٌ يَضَعُهَا اللَّهُ فِي قُلُوبِ مَنْ يَشَاءُ مِنْ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20778,20778,"","আমরা রাজার পর্দার উপর নজর রাখতে চেষ্টা করেছি যেটা আমরা করেছি তার চেয়ে ভাল কিছু. আর সে আমাকে আশ্বস্ত করেছে যে আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার জন্য এবং তার প্রতি দয়া করার জন্য। আমি চাই আপনি এটা করুন এবং বলতে চাই যে এটা ঈশ্বরের ইচ্ছা। আমরা তাকে জিজ্ঞাসা করি একটি নামের নামে। আমি আপনাকে বলি, আমি আপনাকে আমার প্রতি শ্রদ্ধা দেখাতে হবে যে, আপনি যদি আমার প্রতি দয়া করে, আপনি আমাকে যেতে চান। এবং আমি আপনাকে অবশ্যই ক্ষমা চাইতে হবে। আমি চাই যে আপনি আমাকে এর জন্য অনুরোধ করছি, আপনি আমাকে এর জন্য ক্ষমা করবেন। এবং আপনি কি করবেন? এবং আপনি আপনার প্রতি দয়া করে আপনার বিশ্বাস করতে পারবেন। এবং আপনি যদি আমার প্রতি দয়া করেন, আপনি আমাকে যে, আপনি আমাকে এর জন্য ধন্যবাদ জানাতে চান, আপনি আমাকে এর জন্য ধন্যবাদ। আপনি আমাকে আপনার সাহায্য করুন। আপনি আমাকে যে, আপনি জানেন, আপনি জানেন, আমি আপনাকে অবশ্যই, আপনি আপনার কাছে ক্ষমা করবেন। এবং আপনি যা করতে চান, আপনি কি তা করতে চান না। আমি আমার বাবাকে বলেছি যে তারা ভিতরে আছে। তারা বলেছে, আমি কাকে বলছি, তারা আপনাকে জবাব দিতে চায়। আমি আপনাদের জিজ্ঞেস করছি, আমি আপনার নিজের চোখে দেখেছি। কাপড় আর আমি তোমাকে কখনো দেখি নি আমার টাকা আর আমার সব থেকে ভালো।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ قُسَيْطٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏اجْتَمَعَ ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيٌّ ‏ ‏وَزَيْدُ بْنُ حَارِثَةَ ‏ ‏فَقَالَ ‏ ‏جَعْفَرٌ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلِيٌّ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏زَيْدٌ ‏ ‏أَنَا أَحَبُّكُمْ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا انْطَلِقُوا بِنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى نَسْأَلَهُ فَقَالَ ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏فَجَاءُوا يَسْتَأْذِنُونَهُ فَقَالَ اخْرُجْ فَانْظُرْ مَنْ هَؤُلَاءِ فَقُلْتُ هَذَا ‏ ‏جَعْفَرٌ ‏ ‏وَعَلِيٌّ ‏ ‏وَزَيْدٌ ‏ ‏مَا أَقُولُ أَبِي قَالَ ائْذَنْ لَهُمْ وَدَخَلُوا فَقَالُوا مَنْ أَحَبُّ إِلَيْكَ قَالَ ‏ ‏فَاطِمَةُ ‏ ‏قَالُوا نَسْأَلُكَ عَنْ الرِّجَالِ قَالَ ‏ ‏أَمَّا أَنْتَ يَا ‏ ‏جَعْفَرُ ‏ ‏فَأَشْبَهَ خَلْقُكَ خَلْقِي وَأَشْبَهَ خُلُقِي خُلُقُكَ وَأَنْتَ مِنِّي وَشَجَرَتِي وَأَمَّا أَنْتَ يَا ‏ ‏عَلِيُّ ‏ ‏فَخَتَنِي ‏ ‏وَأَبُو وَلَدِي وَأَنَا مِنْكَ وَأَنْتَ مِنِّي وَأَمَّا أَنْتَ يَا ‏ ‏زَيْدُ ‏ ‏فَمَوْلَايَ ‏ ‏وَمِنِّي وَإِلَيَّ وَأَحَبُّ الْقَوْمِ إِلَيَّ ‏","","",""],[20779,20779,"","আমরা বাবার ছেলের হাতে ঈশ্বরের হাত নিয়ে দুইটা তলোয়ার কথা বলেছি... ...আমার নাম শুনে একজন যাজকের নাম শুনে। ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন আর একবার বলেছিলেন যে তিনি ঈশ্বর তাকে বলেছিলেন।","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي يَزِيدَ ‏ ‏سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏أَخْبَرَنِي ‏ ‏أُسَامَةُ ‏ ‏أَنَّهُ قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20780,20780,"","আমরা বাবার রেভ্যরেন্সের কথা বলেছিলাম, আমরা আমার বাবার মৃত্যুর কথা বলেছিলাম যে কিনা ভুলে গেছে, সে একটা ছেলের মেয়েকে সে ছেড়ে দিয়েছে। শপথ করে বলছি, আল্লাহ তাকে ভালো কথা বলেছেন। লর্ড তাকে তার সৌহার্দ্য আচরণ থেকে বলে দিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُمَيْمَةَ ابْنَةِ زَيْنَبَ ‏ ‏وَنَفْسُهَا ‏ ‏تَقَعْقَعُ ‏ ‏كَأَنَّهَا فِي ‏ ‏شَنٍّ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلٌّ إِلَى أَجَلٍ مُسَمًّى فَدَمَعَتْ عَيْنَاهُ فَقَالَ لَهُ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَتَبْكِي أَوَلَمْ تَنْهَ عَنْ الْبُكَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هِيَ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20781,20781,"","আমরা আমার বাবার সঙ্গে বন থেকে বের হওয়ার চেষ্টা করেছিলাম । দুঃখ থেকে মুক্তি পেতে হবে যে সে আমার ভাই, আমি বলছি আমি এটা কিভাবে করলাম, তাই আমি শপথ করে বলছি যে আমি তার সাথে আবার কথা বলেছি। আমার মনে হয় আমি একটা প্রয়োজন বলে মনে করি। আমি অবাক হয়ে যাই যে, তিনি পাগল হয়ে যাওয়ার আগে পর্যন্ত আমাকে বলেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي الشَّعْثَاءِ ‏ ‏قَالَ ‏ ‏خَرَجْتُ حَاجًّا فَدَخَلْتُ ‏ ‏الْبَيْتَ ‏ ‏فَلَمَّا كُنْتُ عِنْدَ السَّارِيَتَيْنِ مَضَيْتُ حَتَّى لَزِقْتُ بِالْحَائِطِ قَالَ وَجَاءَ ‏ ‏ابْنُ عُمَرَ ‏ ‏حَتَّى قَامَ إِلَى جَنْبِي فَصَلَّى أَرْبَعًا قَالَ فَلَمَّا صَلَّى قُلْتُ لَهُ أَيْنَ صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْبَيْتِ ‏ ‏قَالَ فَقَالَ هَاهُنَا أَخْبَرَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏صَلَّى قَالَ قُلْتُ فَكَمْ صَلَّى قَالَ عَلَى هَذَا أَجِدُنِي أَلُومُ نَفْسِي أَنِّي مَكَثْتُ مَعَهُ عُمُرًا ثُمَّ لَمْ أَسْأَلْهُ كَمْ صَلَّى فَلَمَّا كَانَ الْعَامُ الْمُقْبِلُ قَالَ خَرَجْتُ حَاجًّا قَالَ فَجِئْتُ حَتَّى قُمْتُ فِي مَقَامِهِ قَالَ فَجَاءَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏حَتَّى قَامَ إِلَى جَنْبِي فَلَمْ يَزَلْ يُزَاحِمُنِي حَتَّى أَخْرَجَنِي مِنْهُ ثُمَّ صَلَّى فِيهِ أَرْبَعًا ‏","","",""],[20782,20782,"","বাবার মৃত্যুর মানে আমার পরবর্তী পদক্ষেপ। আমি এমন এক জনতার সামনে মরতে মরতে মরতে মরতে মরতে মরতে মরতে মরতে যাচ্ছি, যা আমার কাছে একটা ঘোড়ার মতো হয়েছিল। আমার হৃদয় হচ্ছে আমার হৃদয়। আমি আমার বাবার মৃত্যুর কথা বলছি, আমি একটা ঘোড়ার মতো করে বাজি ধরতে চাই। আমি একটা ঘোড়াকে হারাতে চাই। আমি যদি আমি মরেই না যাই, তাহলে আমি এই টাকাটা একটা ঘোড়ার সাথে বাজি ধরতে চাই। আমি যদি আমি আমার বাবার মৃত্যুর কারণ হয়ে যাই, তাহলে আমি মারা যাব। আমি জানি, আমি যদি আমার বাবা মারা যাই, তাহলে আমি মারা যাই। আর আমি জানি যে, আমি মারা যাব, আমি জানি, আমি যদি আমার ছেলে-মেয়েদের সাথে যোগ করি, তাহলে আমি মারা যাই। আর আমি জানি না যে, আমি আমার ছেলে-মেয়ে। আমি জানি যে, আমি জানি, আমি যদি তুমি জানো না, আমি মারাই না যে, আমি এটা একটা ঘোড়াও না। কিন্তু আমি যদি তুমি জানো, আমি তোমার জন্য এখানে নেই, তাহলে আমি তোমার জন্য এখানে আর আমার বাবা খুশি। আমি এটা একটা স্বপ্ন দেখতে পারি। আর আমি যদি তুমি জানো যে, তাহলে আমি তোমার জন্য একটা স্বপ্ন দেখতে পারি। ৫টা হচ্ছে, তুমি কেন বিছানায় আটকে আছো... ...আর তুমি চলে গেলে, সে দুইটা বিষে আক্রান্ত হয়ে যেত আর পঞ্চমটা ঈশ্বর যা ডিজাইন করেছেন তার জন্য। দুটো নির্ধারিত ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي الدَّسْتُوَائِيَّ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ الْحَكَمِ بْنِ ثَوْبَانَ ‏ ‏أَنَّ ‏ ‏مَوْلَى قُدَامَةَ بْنِ مَظْعُونٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏مَوْلَى أُسَامَةَ بْنِ زَيْدٍ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏كَانَ يَخْرُجُ فِي مَالٍ لَهُ ‏ ‏بِوَادِي الْقُرَى ‏ ‏فَيَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فَقُلْتُ لَهُ لِمَ تَصُومُ فِي السَّفَرِ وَقَدْ كَبِرْتَ وَرَقَقْتَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ فَقُلْتُ يَا رَسُولَ اللَّهِ لِمَ تَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ قَالَ إِنَّ الْأَعْمَالَ تُعْرَضُ يَوْمَ ‏ ‏الِاثْنَيْنِ وَيَوْمَ الْخَمِيسِ ‏","","",""],[20783,20783,"","আমরা বাবার নাম হারানোর যোগ্যতা নিয়ে কথা বলেছি। ঈশ্বরের তা করার দরকার আছে এবং আমি স্বর্গকে আত্মসমর্পণ করব, তাই সে অন্তরের কাছে সাহায্য করবে। গুলি করো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُمْتُ عَلَى بَابِ الْجَنَّةِ فَإِذَا عَامَّةُ مَنْ دَخَلَهَا الْمَسَاكِينُ وَإِذَا أَصْحَابُ الْجَدِّ ‏ ‏وَقَالَ ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَغَيْرُهُ إِلَّا أَصْحَابَ الْجَدِّ ‏ ‏مَحْبُوسُونَ إِلَّا أَصْحَابَ النَّارِ فَقَدْ أُمِرَ بِهِمْ إِلَى النَّارِ وَقُمْتُ عَلَى بَابِ النَّارِ فَإِذَا عَامَّةُ مَنْ يَدْخُلُهَا النِّسَاءُ ‏","","",""],[20784,20784,"","আমরা আনন্দের সাথে আমার বাবার কথা বলেছি যে তিনি আমাকে ঈশ্বরের দোহাই চাইতে বলেছেন। মেসেজটা পেয়ে গেছে, ওর সাথে দেখা করে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏سُئِلَ ‏ ‏أُسَامَةُ ‏ ‏عَنْ سَيْرِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ وَأَنَا شَاهِدٌ قَالَ كَانَ ‏ ‏سَيْرُهُ ‏ ‏الْعَنَقَ ‏ ‏فَإِذَا وَجَدَ ‏ ‏فَجْوَةً ‏ ‏نَصَّ ‏ ‏وَالنَّصُّ ‏ ‏فَوْقَ ‏ ‏الْعَنَقِ ‏ ‏وَأَنَا ‏ ‏رَدِيفُهُ ‏","","",""],[20785,20785,"","আমরা আমার বাবার সাথে কথা বলেছি যে তুমি কখনো আমার সাথে কথা বলবে না, না আমি তার সাথে কথা বলব না, না আমি তার সাথে কথা বলবো না, ঈশ্বর, আমি কারো সাথে কথা বলবো না। ভালো মানুষ আর বলে এটা যখন আমি শুনেছি তখন সে শুনে শুনে শুনে শুনে শুনে যে সে পুরুষদের মুখে যেতে পারে আর বলবে যে সে গুলি করবে. সেরা আগুনের মধ্যে আছে যে আপনি কখনই হবেন না। আমরা আপনাকে বলতে চাচ্ছি না যে আমি আপনাকে এটা জানাতে চাচ্ছি এবং ধন্যবাদ জানাতে চাই না।","‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِأُسَامَةَ ‏ ‏أَلَا تُكَلِّمُ ‏ ‏عُثْمَانَ ‏ ‏فَقَالَ إِنَّكُمْ تَرَوْنَ أَنْ لَا أُكَلِّمَهُ إِلَّا سَمْعَكُمْ إِنِّي لَا أُكَلِّمُهُ فِيمَا بَيْنِي وَبَيْنَهُ مَا دُونَ أَنْ أَفْتَتِحَ أَمْرًا لَا أُحِبُّ أَنْ أَكُونَ أَوَّلَ مَنْ افْتَتَحَهُ وَاللَّهِ لَا أَقُولُ لِرَجُلٍ إِنَّكَ خَيْرُ النَّاسِ وَإِنْ كَانَ عَلَيَّ أَمِيرًا بَعْدَ إِذْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالُوا وَمَا سَمِعْتَهُ يَقُولُ قَالَ سَمِعْتُهُ يَقُولُ ‏ ‏يُجَاءُ بِالرَّجُلِ يَوْمَ الْقِيَامَةِ ‏ ‏فَيُلْقَى فِي النَّارِ ‏ ‏فَتَنْدَلِقُ ‏ ‏بِهِ ‏ ‏أَقْتَابُهُ ‏ ‏فَيَدُورُ بِهَا فِي النَّارِ كَمَا يَدُورُ الْحِمَارُ ‏ ‏بِرَحَاهُ ‏ ‏فَيُطِيفُ بِهِ أَهْلُ النَّارِ فَيَقُولُونَ يَا فُلَانُ مَا لَكَ مَا أَصَابَكَ أَلَمْ تَكُنْ تَأْمُرُنَا بِالْمَعْرُوفِ ‏ ‏وَتَنْهَانَا عَنْ الْمُنْكَرِ فَقَالَ كُنْتُ آمُرُكُمْ بِالْمَعْرُوفِ وَلَا آتِيهِ وَأَنْهَاكُمْ عَنْ الْمُنْكَرِ وَآتِيهِ ‏","","",""],[20786,20786,"","আমরা বাবার কথা বলেছি, আমার বাবা বছরের পর বছর ধরে একজন শক্তিশালী কাস্টমারের সাথে মরুভূমিতে বসে আছেন। গ্রামটা বলে আমার ছেলে শেষবারের মত এখানে আছে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنِي ‏ ‏صَالِحُ بْنُ أَبِي الْأَخْضَرِ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى قَرْيَةٍ يُقَالُ لَهَا ‏ ‏أُبْنَى ‏ ‏فَقَالَ ائْتِهَا صَبَاحًا ثُمَّ حَرِّقْ ‏","","",""],[20787,20787,"","তার বাবা বলেছিলেন যে, আমার জিহ্বা ঈশ্বরের কাছে তার অসন্তোষের দ্বারা রক্ষা পেয়েছে । ঈশ্বর তাকে উদ্ধার করেছেন আর জিজ্ঞেস করেছেন যে তুমি কি করতে চাও না। আমি বলতে চাই, ঈশ্বর এমন একটা ধারণা করেছেন যে তিনি কখনও মুক্তি পেয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنِ ‏ ‏ابْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أُسَامَةَ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبْطِيَّةً ‏ ‏كَثِيفَةً كَانَتْ مِمَّا أَهْدَاهَا ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏فَكَسَوْتُهَا امْرَأَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَكَ لَمْ تَلْبَسْ ‏ ‏الْقُبْطِيَّةَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَسَوْتُهَا امْرَأَتِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُرْهَا فَلْتَجْعَلْ تَحْتَهَا غِلَالَةً إِنِّي أَخَافُ أَنْ تَصِفَ حَجْمَ عِظَامِهَا ‏","","",""],[20788,20788,"","আমরা তার বাবার সাথে কথা বলেছি যে বাবা তার বাবার কথা বলেছে। এটা হয় আমার বাবা একটা ছেলে যে আমার ছেলে ছিল, তাকে নিয়ে যাও আর তারপর সে আমাদের সাথে আসবে। আর এরপর তিনি ঈশ্বরের কাছে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَارِمُ بْنُ الْفَضْلِ ‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا تَمِيمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏يُحَدِّثُهُ ‏ ‏أَبُو عُثْمَانَ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏كَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْخُذُنِي ‏ ‏فَيُقْعِدُنِي عَلَى فَخِذِهِ وَيُقْعِدُ ‏ ‏الْحَسَنَ بْنَ عَلِيٍّ ‏ ‏عَلَى فَخِذِهِ الْأُخْرَى ثُمَّ يَضُمُّنَا ثُمَّ يَقُولُ اللَّهُمَّ ارْحَمْهُمَا فَإِنِّي أَرْحَمُهُمَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏عَلِيُّ بْنُ الْمَدِينِيِّ ‏ ‏هُوَ ‏ ‏السَّلِّيُّ ‏ ‏مِنْ ‏ ‏عَنَزَةَ ‏ ‏إِلَى ‏ ‏رَبِيعَةَ يَعْنِي أَبَا تَمِيمَةَ السَّلِّيَّ ‏","","",""],[20789,20789,"","আমরা আমার কথা বলছি, ঈশ্বরের দোহাই দিয়ে বলছি আমরা একটা ঘোড়াকে ফোন করেছি, আমার বাবা বলেছেন যে আল্লাহ তাকে শান্তি দেবেন। তুমি যা করো নি তার কথা তার কাছে বলে তুমি তার রাগ প্রকাশ করবে","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أُسَامَةَ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَسَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُبْطِيَّةً ‏ ‏كَثِيفَةً مِمَّا أَهْدَاهَا لَهُ ‏ ‏دِحْيَةُ الْكَلْبِيُّ ‏ ‏فَكَسَوْتُهَا امْرَأَتِي فَقَالَ ‏ ‏مَا لَكَ لَمْ تَلْبَسْ ‏ ‏الْقُبْطِيَّةَ ‏ ‏قُلْتُ كَسَوْتُهَا امْرَأَتِي فَقَالَ مُرْهَا فَلْتَجْعَلْ تَحْتَهَا ‏ ‏غِلَالَةً ‏ ‏فَإِنِّي أَخَافُ أَنْ تَصِفَ حَجْمَ عِظَامِهَا ‏","","",""],[20790,20790,"","আমরা বাবার জীবনের সবচেয়ে ভাল নাম নিয়ে কথা বলেছি। তার কাছে প্রার্থনা করেছিলাম। তিনি তাকে বললেন যে, আমার ছেলে কিসকি হবে। সে তার কথা ফিরে আসবে, সে আর ছেলে আর তার কথা শুনবে। তিনি তাকে হত্যা করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أَرْسَلَتْ ‏ ‏ابْنَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ ‏ ‏ابْنِي ‏ ‏يُقْبَضُ ‏ ‏فَأْتِنَا فَأَرْسَلَ بِإِقْرَاءِ السَّلَامِ ‏ ‏وَيَقُولُ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلُّ شَيْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى قَالَ فَأَرْسَلَتْ إِلَيْهِ تُقْسِمُ عَلَيْهِ لَيَأْتِيَنَّ قَالَ فَقَامَ وَقُمْنَا مَعَهُ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏وَسَعْدُ بْنُ عُبَادَةَ ‏ ‏قَالَ فَأَخَذَ الصَّبِيَّ وَنَفْسُهُ ‏ ‏تَقَعْقَعُ ‏ ‏قَالَ فَدَمَعَتْ عَيْنَاهُ فَقَالَ ‏ ‏سَعْدٌ ‏ ‏يَا رَسُولَ اللَّهِ مَا هَذَا قَالَ هَذِهِ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""],[20791,20791,"","আমরা বাবার ছেলের কথা বলেছিলাম খারাপ ছেলের ব্যাপারে মন খারাপ হয়ে গেছে কিন্তু সে ঈশ্বরের কাছে পাঠাতে চায়, ঈশ্বর তার শান্তি ফিরিয়ে আনবে এবং তাকে সেই প্রবেশের জন্য পাঠানো হবে। অন্ধকার, সে এসে দৌড় দিল এবং সে পালিয়ে গেলো।","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ الْحَجَّاجِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي فُدَيْكٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏أَنَّهُ ‏ ‏أَرْدَفَهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏عَرَفَةَ ‏ ‏حَتَّى دَخَلَ ‏ ‏الشِّعْبَ ‏ ‏ثُمَّ ‏ ‏أَهْرَاقَ ‏ ‏الْمَاءَ وَتَوَضَّأَ ثُمَّ رَكِبَ وَلَمْ يُصَلِّ ‏","","",""],[20792,20792,"","আমরা ভালোবাসার কথা বলেছি, আমি বাবার সুখী মাস্টারের সাথে... ...আর ঈশ্বর এই দুই আর পাঁচ জনের বিষ প্রয়োগ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَصُومُ ‏ ‏الِاثْنَيْنِ وَالْخَمِيسَ ‏","","",""],[20793,20793,"","আমরা বাবার ছেলে মাখন নিয়ে কথা বলেছি যে সে এমন একটা গ্রাম থেকে চলে গেছে, তারা তাকে প্রার্থনা করতে বলবে। একটা হাতে একটা হাত রেখে আমি জিজ্ঞাসা করবো যে, বিকেলের জন্য লর্ড এসেছে, মরুভূমিকে দেখতে পাবে না... অভিযোগ এবং অভিযোগের বিরুদ্ধে আনা ব্যবসার নাম, তারা প্রার্থনা করে এবং তার কাছে প্রার্থনা করে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزِّبْرِقَانِ ‏ ‏أَنَّ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مَرَّ بِهِمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَهُمْ مُجْتَمِعُونَ فَأَرْسَلُوا إِلَيْهِ غُلَامَيْنِ لَهُمْ يَسْأَلَانِهِ عَنْ الصَّلَاةِ الْوُسْطَى فَقَالَ هِيَ الْعَصْرُ فَقَامَ إِلَيْهِ رَجُلَانِ مِنْهُمْ فَسَأَلَاهُ فَقَالَ هِيَ الظُّهْرُ ‏ ‏ثُمَّ انْصَرَفَا إِلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏فَسَأَلَاهُ فَقَالَ هِيَ الظُّهْرُ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الظُّهْرَ ‏ ‏بِالْهَجِيرِ ‏ ‏وَلَا يَكُونُ وَرَاءَهُ إِلَّا الصَّفُّ وَالصَّفَّانِ مِنْ النَّاسِ فِي ‏ ‏قَائِلَتِهِمْ ‏ ‏وَفِي تِجَارَتِهِمْ فَأَنْزَلَ اللَّهُ تَعَالَى ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَقُومُوا لِلَّهِ ‏ ‏قَانِتِينَ ‏ } ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَنْتَهِيَنَّ رِجَالٌ أَوْ لَأُحَرِّقَنَّ بُيُوتَهُمْ ‏","","",""],[20794,20794,"","আমি তার প্রতি অনুগ্রহ বোধ করছিলাম এবং এমনকি কয়েক বছর এমন একটি পৃথিবী দিয়েছিলাম যা একটি দেশ থেকে উঠিয়ে নেয়া হয়েছে। যে মানুষ খুন করেছে সে একজন হিরো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عَزْرَةَ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّهُ حَدَّثَهُ قَالَ ‏ ‏كُنْتُ ‏ ‏رِدْفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ‏ ‏أَفَاضَ ‏ ‏مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏فَلَمْ تَرْفَعْ رَاحِلَتُهُ رِجْلَهَا عَادِيَةً حَتَّى بَلَغَ ‏ ‏جَمْعًا ‏","","",""],[20795,20795,"","আমরা আমার বাবার কথা বলেছিলাম যে আমার একটা নাম আছে একটা দুঃখের নামে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং বলবেন যে, যে ব্যক্তি কথা দিয়েছিল তাকে আমার দেবীর প্রতি বাধ্য করা হয়েছিল। আমি তা লিখেছি। আমি জানি, ঈশ্বর আমার বাবার প্রতি আমার নাম লিখে রেখেছেন। আমি জানি, আমি জানি, আমার নাম লিখেছি, আমার নিজের নাম লিখেছি। যেভাবে আমি সবচেয়ে ভালো ভাবে জিজ্ঞাসা করি, তুমি আমাদের বলবে আমি তোমাকে আদেশ দিচ্ছি... ...আর আমি তোমাকে বলছি কিভাবে এটি গাইতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏قَالَ قِيلَ ‏ ‏لِأُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يُؤْتَى بِالرَّجُلِ الَّذِي كَانَ يُطَاعُ فِي مَعَاصِي اللَّهِ تَعَالَى فَيُقْذَفُ فِي النَّارِ ‏ ‏فَتَنْدَلِقُ ‏ ‏بِهِ ‏ ‏أَقْتَابُهُ ‏ ‏فَيَسْتَدِيرُ فِيهَا كَمَا يَسْتَدِيرُ الْحِمَارُ فِي الرَّحَا فَيَأْتِي عَلَيْهِ أَهْلُ طَاعَتِهِ مِنْ النَّاسِ فَيَقُولُونَ أَيْ ‏ ‏فُلَ أَيْنَ مَا كُنْتَ تَأْمُرُنَا بِهِ فَيَقُولُ إِنِّي كُنْتُ آمُرُكُمْ بِأَمْرٍ وَأُخَالِفُكُمْ إِلَى غَيْرِهِ ‏","","",""],[20796,20796,"","আমি এমন এক ছেলের সঙ্গে কথা বলেছিলাম, যিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং প্রভুর কাছে প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ أَبِي الْفُرَاتِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ يَعْنِي الصَّائِغَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏حَدَّثَنِي ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الرِّبَا فِي ‏ ‏النَّسِيئَةِ ‏","","",""],[20797,20797,"","আমরা যত দুঃখের যাজকের কাছে বাস করি, তাদের কথা বলছি, যারা তাদের ঋণ অন্য দুই সন্তানের কাছ থেকে ফিরিয়ে নেবে। একজন যাজকের ছেলে, যে তার সাথে কথা বলেছে, ঈশ্বর তাকে আদেশ করেছেন আর একটা ছেলেকে দিয়েছেন যে বলে আমি ঈশ্বরের অনুগ্রহ থেকে তার কথা শুনি নাই। আমি আমার সাহায্য চাই যে ঈশ্বর এসে পৌঁছেছেন। ( আদি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَنَا ‏ ‏يَحْيَى بْنُ قَيْسٍ الْمَازِنِيُّ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَطَاءً ‏ ‏عَنْ الدِّينَارِ بِالدِّينَارِ وَبَيْنَهُمَا فَضْلٌ وَالدِّرْهَمِ بِالدِّرْهَمِ قَالَ كَانَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏يُحِلُّهُ فَقَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏إِنَّ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يُحَدِّثُ بِمَا لَمْ يَسْمَعْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَلَغَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏فَقَالَ إِنِّي لَمْ أَسْمَعْهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَكِنَّ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏حَدَّثَنِي أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الرِّبَا إِلَّا فِي ‏ ‏النَّسِيئَةِ ‏ ‏أَوْ ‏ ‏النُّقْرَةِ ‏","","",""],[20798,20798,"","বাবা আমাকে তার পক্ষ থেকে ঘুমাতে সাহায্য করার চেষ্টা করছিল ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أُسَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏الْكَعْبَةِ ‏","","",""],[20799,20799,"","আমার বাবা কেমন পছন্দ করতেন, তার কথা বলেছিলাম আমি আমার বাবার ব্যাপারে কথা বলেছি। আমি একটা খারাপ হাত দিয়ে শুনেছি যেটা শোনা যায়। হ্যাঁ, অবশ্যই।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏أَخْبَرَنَا قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ بْنَ سَعْدٍ ‏ ‏يُحَدِّثُ أَنَّهُ سَمِعَ ‏ ‏أُسَامَةَ بْنَ زَيْدٍ ‏ ‏يُحَدِّثُ ‏ ‏سَعْدًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَمِعْتُمْ ‏ ‏بِالطَّاعُونِ ‏ ‏بِأَرْضٍ فَلَا تَدْخُلُوهَا وَإِذَا وَقَعَ بِأَرْضٍ وَأَنْتُمْ بِهَا فَلَا تَخْرُجُوا مِنْهَا قَالَ قُلْتُ أَنْتَ سَمِعْتَهُ يُحَدِّثُ ‏ ‏سَعْدًا ‏ ‏وَهُوَ لَا يُنْكِرُ قَالَ نَعَمْ ‏","","",""],[20800,20800,"","আমরা বাবা একসাথে কথা বলেছি আমার বাবার নামে শপথ করা শিল্পীর নাম নিয়ে। ঈশ্বরের অফিস, আল্লাহ তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর প্রতি দয়া দেখানোর সময় তাকে আত্মসমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُثْمَانَ النَّهْدِيُّ ‏ ‏عَنْ ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏قَالَ ‏ ‏أُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأُمَيْمَةَ بِنْتِ زَيْنَبَ ‏ ‏وَنَفْسُهَا ‏ ‏تَقَعْقَعُ ‏ ‏كَأَنَّهَا فِي ‏ ‏شَنٍّ ‏ ‏فَقَالَ ‏ ‏لِلَّهِ مَا أَخَذَ وَلِلَّهِ مَا أَعْطَى وَكُلٌّ إِلَى أَجَلٍ مُسَمًّى قَالَ فَدَمَعَتْ عَيْنَاهُ فَقَالَ لَهُ ‏ ‏سَعْدُ بْنُ عُبَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَتَبْكِي أَوَلَمْ تَنْهَ عَنْ الْبُكَاءِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا هِيَ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ ‏","","",""]];
